// --- MAGE RANKINGS ---
static std::pair<std::string, ofColor> getMageRank(int elo) {
	// The Shame Tiers (When the dice betray you)
	if (elo < 600) return { "Target Dummy", ofColor(186, 140, 99) }; // Burlap / Wood Brown
	if (elo < 700) return { "Wall Bumper", ofColor(112, 128, 144) }; // Slate / Stone Gray
	if (elo < 800) return { "Draft Dodger", ofColor(240, 230, 140) }; // Faded Parchment / Cowardly Khaki

	// The Standard Climb
	if (elo < 1000) return { "Kobold Fodder", ofColor(178, 34, 34) }; // Murky Kobold Red
	if (elo < 1100) return { "Neophyte", ofColor(205, 127, 50) }; // Bronze
	if (elo < 1200) return { "Spellsword", ofColor(192, 192, 192) }; // Silver / Steel
	if (elo < 1300) return { "Hex Master", ofColor(255, 215, 0) }; // Brilliant Gold
	if (elo < 1400) return { "Archmage", ofColor(0, 150, 255) }; // Glowing Arcane Blue
	if (elo < 1500) return { "Reality Warper", ofColor(148, 0, 211) }; // Deep Void Purple
	return { "Architect of Fate", ofColor(0, 255, 255) }; // Blinding Cyan
}

static void writeLockstepTrace(bool isHost, int turn, const std::string & eventStr) {
	// Use a fixed filename so it overwrites every match and prevents folder bloat
	std::string role = isHost ? "host" : "client";
	std::string filename = "lockstep_trace_" + role + ".log";

	std::string timeStr = ofGetTimestampString("%H:%M:%S");
	std::string logLine = "[" + timeStr + "] T:" + std::to_string(turn) + " | " + eventStr + "\n";

	ofFile file(filename, ofFile::Append);
	file << logLine;
}

#ifdef _WIN32
static int runHiddenWindowsCommand(const std::string & cmd) {
	STARTUPINFOA si;
	PROCESS_INFORMATION pi;
	ZeroMemory(&si, sizeof(si));
	si.cb = sizeof(si);
	si.dwFlags = STARTF_USESHOWWINDOW;
	si.wShowWindow = SW_HIDE;
	ZeroMemory(&pi, sizeof(pi));

	std::vector<char> cmdBuffer(cmd.begin(), cmd.end());
	cmdBuffer.push_back('\0');

	if (CreateProcessA(NULL, cmdBuffer.data(), NULL, NULL, FALSE, CREATE_NO_WINDOW, NULL, NULL, &si, &pi)) {
		WaitForSingleObject(pi.hProcess, INFINITE);
		DWORD exitCode = 0;
		GetExitCodeProcess(pi.hProcess, &exitCode);
		CloseHandle(pi.hProcess);
		CloseHandle(pi.hThread);
		return (int)exitCode;
	}
	return -1;
}
#endif

static void sendDiscordWebhook(const std::string & url, const std::string & content) {
	if (url.empty() || url.find("YOUR_") != std::string::npos) return;

	std::thread([url, content]() {
		std::string safeContent = "";
		for (char c : content) {
			if (c == '\"')
				safeContent += "\\\"";
			else if (c == '\\')
				safeContent += "\\\\";
			else if (c == '\n')
				safeContent += "\\n";
			else if (c == '\r')
				continue;
			else
				safeContent += c;
		}

		std::string jsonStr = "{\"content\": \"" + safeContent + "\"}";

		ofHttpRequest request;
		request.url = url;
		request.method = ofHttpRequest::POST;
		request.body = jsonStr;
		request.contentType = "application/json";
		request.headers["User-Agent"] = "DiscordBot (MageFight, 1.0)";

		ofURLFileLoader loader;
		ofHttpResponse response = loader.handleRequest(request);

		// If native OF fails (usually SSL cert issues on Linux/Proton), fallback to curl.exe
		if (response.status != 200 && response.status != 204) {
			ofLogWarning("Discord") << "Native Webhook failed (" << response.status << "). Trying curl fallback...";

			std::string tmpFilename = "discord_tmp_" + std::to_string(ofGetSystemTimeMillis()) + ".json";
			std::string tmpPath = ofToDataPath(tmpFilename, true);
			ofFile f(tmpPath, ofFile::WriteOnly);
			f << jsonStr;
			f.close();

			std::string dataDir = ofToDataPath("", true);
			std::string args = "--max-time 10 -k -s -H \"Content-Type: application/json\" -H \"User-Agent: DiscordBot (MageFight, 1.0)\" -d @\"" + tmpFilename + "\" \"" + url + "\"";

#ifdef _WIN32
			std::string winDataDir = dataDir;
			for (auto & c : winDataDir) {
				if (c == '/') c = '\\';
			}
			// Use /s /c "..." so cmd.exe preserves the inner quotes required by curl
			std::string cmd1 = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && curl.exe " + args + "\"";
			int sysRet = runHiddenWindowsCommand(cmd1);

			// If Windows/Wine curl.exe fails, escape Proton/Wine library sandbox via Z: or Y: drive mapping
			if (sysRet != 0) {
				ofLogWarning("Discord") << "curl.exe failed. Attempting native host curl via sandbox escape...";

				// Try to use 'env' to strip sandboxed Proton library paths, preventing host curl from crashing
				std::string cmdEscZ = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && Z:\\usr\\bin\\env -u LD_LIBRARY_PATH -u DYLD_LIBRARY_PATH -u DYLD_FALLBACK_LIBRARY_PATH curl " + args + "\"";
				sysRet = runHiddenWindowsCommand(cmdEscZ);

				if (sysRet != 0) {
					// Fallback to Y: drive (sometimes used on macOS Whisky/Wine mappings)
					std::string cmdEscY = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && Y:\\usr\\bin\\env -u LD_LIBRARY_PATH -u DYLD_LIBRARY_PATH -u DYLD_FALLBACK_LIBRARY_PATH curl " + args + "\"";
					sysRet = runHiddenWindowsCommand(cmdEscY);
				}

				if (sysRet != 0) {
					// Hard fallback directly to Z: drive curl if env tool is missing
					std::string cmdDirectZ = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && Z:\\usr\\bin\\curl " + args + "\"";
					sysRet = runHiddenWindowsCommand(cmdDirectZ);
				}
			}
#else
			std::string cmd1 = "cd \"" + dataDir + "\" && curl " + args;
			int sysRet = system(cmd1.c_str());
			(void)sysRet; // Suppress unused warning on Linux
#endif

			ofFile::removeFile(tmpPath, false);
		}
	}).detach();
}

static void sendDiscordFileWebhook(const std::string & url, const std::string & content, const std::vector<std::string> & filePaths) {
	if (url.empty() || url.find("YOUR_") != std::string::npos) return;

	std::thread([url, content, filePaths]() {
		std::string safeContent = "";
		for (char c : content) {
			if (c == '\"')
				safeContent += "\\\"";
			else if (c == '\\')
				safeContent += "\\\\";
			else if (c == '\n')
				safeContent += "\\n";
			else if (c == '\r')
				continue;
			else
				safeContent += c;
		}

		std::string jsonStr = "{\"content\": \"" + safeContent + "\"}";
		std::string boundary = "----DiscordWebhookBoundary" + std::to_string(ofGetSystemTimeMillis());
		std::string body = "";

		body += "--" + boundary + "\r\n";
		body += "Content-Disposition: form-data; name=\"payload_json\"\r\n";
		body += "Content-Type: application/json\r\n\r\n";
		body += jsonStr + "\r\n";

		for (size_t i = 0; i < filePaths.size(); ++i) {
			ofFile file(filePaths[i]);
			if (!file.exists() || file.getSize() == 0) continue;

			ofBuffer fileBuf = file.readToBuffer();
			std::string fileName = file.getFileName();

			body += "--" + boundary + "\r\n";
			body += "Content-Disposition: form-data; name=\"files[" + std::to_string(i) + "]\"; filename=\"" + fileName + "\"\r\n";
			body += "Content-Type: text/plain\r\n\r\n";
			body += fileBuf.getText() + "\r\n";
		}

		body += "--" + boundary + "--\r\n";

		ofHttpRequest request;
		request.url = url;
		request.method = ofHttpRequest::POST;
		request.body = body;
		request.contentType = "multipart/form-data; boundary=" + boundary;
		request.headers["User-Agent"] = "DiscordBot (MageFight, 1.0)";

		ofURLFileLoader loader;
		ofHttpResponse response = loader.handleRequest(request);

		if (response.status != 200 && response.status != 204) {
			ofLogWarning("Discord") << "Native File Webhook failed (" << response.status << "). Trying curl fallback...";

			std::string tmpFilename = "discord_payload_" + std::to_string(ofGetSystemTimeMillis()) + ".json";
			std::string tmpPath = ofToDataPath(tmpFilename, true);
			ofFile f(tmpPath, ofFile::WriteOnly);
			f << jsonStr;
			f.close();

			std::string dataDir = ofToDataPath("", true);
			std::string args = "--max-time 15 -k -s -H \"User-Agent: DiscordBot (MageFight, 1.0)\" -F \"payload_json=<" + tmpFilename + "\" ";
			for (size_t i = 0; i < filePaths.size(); ++i) {
				ofFile file(filePaths[i]);
				std::string fileName = file.getFileName();
				args += "-F \"files[" + std::to_string(i) + "]=@" + fileName + "\" ";
			}
			args += "\"" + url + "\"";

#ifdef _WIN32
			std::string winDataDir = dataDir;
			for (auto & c : winDataDir) {
				if (c == '/') c = '\\';
			}
			std::string cmd1 = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && curl.exe " + args + "\"";
			int sysRet = runHiddenWindowsCommand(cmd1);

			// If Windows/Wine curl.exe fails, escape Proton/Wine library sandbox via Z: or Y: drive mapping
			if (sysRet != 0) {
				ofLogWarning("Discord") << "curl.exe failed. Attempting native host curl via sandbox escape...";

				// Try to use 'env' to strip sandboxed Proton library paths, preventing host curl from crashing
				std::string cmdEscZ = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && Z:\\usr\\bin\\env -u LD_LIBRARY_PATH -u DYLD_LIBRARY_PATH -u DYLD_FALLBACK_LIBRARY_PATH curl " + args + "\"";
				sysRet = runHiddenWindowsCommand(cmdEscZ);

				if (sysRet != 0) {
					// Fallback to Y: drive (sometimes used on macOS Whisky/Wine mappings)
					std::string cmdEscY = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && Y:\\usr\\bin\\env -u LD_LIBRARY_PATH -u DYLD_LIBRARY_PATH -u DYLD_FALLBACK_LIBRARY_PATH curl " + args + "\"";
					sysRet = runHiddenWindowsCommand(cmdEscY);
				}

				if (sysRet != 0) {
					// Hard fallback directly to Z: drive curl if env tool is missing
					std::string cmdDirectZ = "cmd.exe /s /c \"cd /d \"" + winDataDir + "\" && Z:\\usr\\bin\\curl " + args + "\"";
					sysRet = runHiddenWindowsCommand(cmdDirectZ);
				}
			}
#else
			std::string cmd1 = "cd \"" + dataDir + "\" && curl " + args;
			int sysRet = system(cmd1.c_str());
			(void)sysRet; // Suppress unused warning on Linux
#endif

			ofFile::removeFile(tmpPath, false);
		}
	}).detach();
}

