				EffectOp aoeDmg = {};
				aoeDmg.type = EffectOpType::APPLY_GENERIC_DAMAGE;
				aoeDmg.data.damage.targetIndex = pidx;
				aoeDmg.data.damage.damageType = DAMAGE_ELECTRIC; // Electric damage strictly
				aoeDmg.data.damage.fixedDamage = dmg;
