		if (missingHP > 0) {
			EffectOp healOp = {};
			healOp.type = EffectOpType::HEAL;
			healOp.data.heal.targetIndex = currentPlayerIndex;
			healOp.data.heal.amount = missingHP;
			healOp.data.heal.amountFromSlot = -1;
			queueEffect(healOp);
		}

