//--------------------------------------------------------------
void ofApp::drawCardSpawnerUI() {
	drawMenuOverlay();
	float barWidth = 600.0f;
	float barHeight = 50.0f;
	float barX = (ofGetWidth() - barWidth) / 2.0f;
	float barY = ofGetHeight() * 0.15f;

	// Main input bar background
	ofSetColor(30, 30, 30, 250);
	ofDrawRectRounded(barX, barY, barWidth, barHeight, 8);

	// Input area (left side)
	float inputWidth = barWidth - 180.0f; // Room for buttons
	cardSpawnerInputRect.set(barX, barY, inputWidth, barHeight);

	// Draw input border
	ofSetColor(80, 80, 80);
	ofNoFill();
	ofSetLineWidth(2);
	ofDrawRectRounded(barX + 2, barY + 2, inputWidth - 4, barHeight - 4, 6);
	ofFill();

	// Draw input text
	ofSetColor(ofColor::white);
	string displayText = cardSpawnerInput;
	if (displayText.empty()) {
		ofSetColor(120, 120, 120);
		displayText = "Type card name...";
	}
	// Add blinking cursor
	if (!cardSpawnerInput.empty() || (int)(ofGetElapsedTimef() * 2) % 2 == 0) {
		if (cardSpawnerInput.empty()) {
			displayText = "|";
			ofSetColor(ofColor::white);
		} else {
			displayText += "|";
		}
	}
	uiFont.drawString(displayText, barX + 15, barY + barHeight / 2 + 6);

	// Quantity display and +/- buttons
	float btnSize = 30.0f;
	float btnY = barY + (barHeight - btnSize) / 2.0f;
	float quantityX = barX + inputWidth + 10.0f;

	// Minus button
	cardSpawnerMinusButton.set(quantityX, btnY, btnSize, btnSize);
	if (cardSpawnerMinusButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "spawn_minus";
	ofSetColor(60, 60, 60);
	ofDrawRectRounded(cardSpawnerMinusButton, 5);
	ofSetColor(ofColor::white);
	uiFont.drawString("-", quantityX + 10, btnY + btnSize / 2 + 6);

	// Quantity number
	ofSetColor(ofColor::white);
	string qtyStr = ofToString(cardSpawnerQuantity);
	float plusX = quantityX + btnSize + 20;
	float minusCenterX = quantityX + btnSize * 0.5f;
	float plusCenterX = plusX + btnSize * 0.5f;
	float qtyCenterX = (minusCenterX + plusCenterX) * 0.5f;
	ofRectangle qtyBox = uiFont.getStringBoundingBox(qtyStr, 0, 0);
	uiFont.drawString(qtyStr, qtyCenterX - qtyBox.width * 0.5f, btnY + btnSize / 2 + qtyBox.height * 0.5f);

	// Plus button
	cardSpawnerPlusButton.set(plusX, btnY, btnSize, btnSize);
	if (cardSpawnerPlusButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "spawn_plus";
	ofSetColor(60, 60, 60);
	ofDrawRectRounded(cardSpawnerPlusButton, 5);
	ofSetColor(ofColor::white);
	uiFont.drawString("+", plusX + 9, btnY + btnSize / 2 + 6);

	// Encyclopedia button
	float encBtnWidth = 40.0f;
	float closeBtnX = barX + barWidth - 40;
	cardSpawnerEncyclopediaButton.set(closeBtnX - encBtnWidth - 6, btnY, encBtnWidth, btnSize);
	if (cardSpawnerEncyclopediaButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "spawn_ency";
	ofSetColor(70, 50, 100);
	ofDrawRectRounded(cardSpawnerEncyclopediaButton, 5);
	// Draw 3 horizontal lines (hamburger menu icon)
	ofSetColor(ofColor::white);
	float lineX = cardSpawnerEncyclopediaButton.x + 10;
	float lineWidth = 20;
	float lineY1 = btnY + 8;
	float lineY2 = btnY + btnSize / 2;
	float lineY3 = btnY + btnSize - 8;
	ofSetLineWidth(2);
	ofDrawLine(lineX, lineY1, lineX + lineWidth, lineY1);
	ofDrawLine(lineX, lineY2, lineX + lineWidth, lineY2);
	ofDrawLine(lineX, lineY3, lineX + lineWidth, lineY3);

	// Close button (X)
	cardSpawnerCloseButton.set(closeBtnX, btnY, btnSize, btnSize);
	if (cardSpawnerCloseButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "spawn_close";
	ofSetColor(100, 40, 40);
	ofDrawRectRounded(cardSpawnerCloseButton, 5);
	ofSetColor(ofColor::white);
	uiFont.drawString("X", cardSpawnerCloseButton.x + 9, btnY + btnSize / 2 + 6);

	// Draw filtered card suggestions below the bar
	if (!cardSpawnerInput.empty() && !filteredCards.empty()) {
		float suggestionY = barY + barHeight + 5.0f;
		float suggestionHeight = 35.0f;
		int maxSuggestions = std::min((int)filteredCards.size(), 8);

		ofSetColor(40, 40, 40, 245);
		ofDrawRectRounded(barX, suggestionY, inputWidth, suggestionHeight * maxSuggestions + 10, 8);

		for (int i = 0; i < maxSuggestions; i++) {
			float itemY = suggestionY + 5 + i * suggestionHeight;

			// Highlight on hover - check if mouse is over this item
			ofRectangle itemRect(barX + 5, itemY, inputWidth - 10, suggestionHeight - 2);
			if (itemRect.inside(ofGetMouseX(), ofGetMouseY())) {
				ofSetColor(70, 70, 100);
				ofDrawRectRounded(itemRect, 4);
				g_hoveredButtonId = "spawn_item_" + ofToString(i);
			}

			ofSetColor(ofColor::white);
			string cardInfo = filteredCards[i].name + " (Cost: " + ofToString(filteredCards[i].cost) + ")";
			uiFont.drawString(cardInfo, barX + 15, itemY + suggestionHeight / 2 + 5);
		}
	}

	// Instructions text
	ofSetColor(180, 180, 180);
	string helpText = "Press ENTER to add card | ESC to close";
	ofRectangle helpBox = uiFont.getStringBoundingBox(helpText, 0, 0);
	uiFont.drawString(helpText, (ofGetWidth() - helpBox.width) / 2, barY + barHeight + (filteredCards.empty() ? 30 : 35 * std::min((int)filteredCards.size(), 8) + 45));
}

//--------------------------------------------------------------
void ofApp::drawCardEncyclopediaUI() {
	drawMenuOverlay();

	// Encyclopedia panel
	float panelWidth = ofGetWidth() * 0.85f;
	float panelHeight = ofGetHeight() * 0.85f;
	float panelX = (ofGetWidth() - panelWidth) / 2.0f;
	float panelY = (ofGetHeight() - panelHeight) / 2.0f;

	encyclopediaRect.set(panelX, panelY, panelWidth, panelHeight);

	ofSetColor(25, 25, 30, 250);
	ofDrawRectRounded(encyclopediaRect, 15);

	// Title bar
	ofSetColor(40, 40, 50);
	ofDrawRectRounded(panelX, panelY, panelWidth, 50, 15);
	// Fix bottom corners of title bar
	ofDrawRectangle(panelX, panelY + 35, panelWidth, 15);

	// Title will be drawn based on mode below

	// Close button
	encyclopediaCloseButton.set(panelX + panelWidth - 45, panelY + 10, 30, 30);
	if (encyclopediaCloseButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "ency_close";
	ofSetColor(100, 40, 40);
	ofDrawRectRounded(encyclopediaCloseButton, 5);
	ofSetColor(ofColor::white);
	uiFont.drawString("X", encyclopediaCloseButton.x + 9, encyclopediaCloseButton.y + 22);

	// Card grid - 10 cards per row, fills width; vertical scrolling for extra rows
	const float encyCardAspect = 1.4f;

	float contentY = panelY + 60;
	float acceptW = 160.0f;
	float acceptH = 44.0f;
	float acceptY = panelY + panelHeight - 70;
	float contentBottom = acceptY - 12.0f;
	float contentHeight = std::max(0.0f, contentBottom - contentY);

	// Build displayed list depending on current encyclopedia mode
	std::vector<Card> displayList;
	string titleSuffix = "";
	if (encyclopediaMode == ENC_SPAWN_TO_HAND) {
		displayList = allCards;
		titleSuffix = "Spawner - Select Cards for Hand";
	} else if (encyclopediaMode == ENC_ADD_FROM_ALL) {
		displayList = allCards;
		titleSuffix = "Add from All Cards";
	} else if (encyclopediaMode == ENC_REMOVE_FROM_PILE) {
		if (encyclopediaTargetPlayerIndex >= 0 && encyclopediaTargetPlayerIndex < (int)players.size()) {
			Player & tgt = players[encyclopediaTargetPlayerIndex];
			if (encyclopediaTargetIsDiscard)
				displayList = tgt.discardPile;
			else
				displayList = tgt.deck;
			titleSuffix = "Modify Player " + ofToString(tgt.playerID) + (encyclopediaTargetIsDiscard ? " Discard" : " Deck");
		} else {
			displayList = allCards;
			titleSuffix = "All Cards";
		}
	} else {
		displayList = allCards;
		titleSuffix = "All Cards";
	}

	// Update title depending on mode
	string titleMode = "Select to Add";
	if (encyclopediaMode == ENC_REMOVE_FROM_PILE) titleMode = "Select to Remove";
	if (encyclopediaMode == ENC_SPAWN_TO_HAND) titleMode = "Select then Accept (adds to hand)";
	string titleFull = "Card Encyclopedia - " + titleSuffix + " - " + titleMode;
	ofSetColor(ofColor::white);
	ofRectangle titleBox2 = uiFont.getStringBoundingBox(titleFull, 0, 0);
	uiFont.drawString(titleFull, panelX + (panelWidth - titleBox2.width) / 2, panelY + 32);

	// Fixed horizontal layout (10 columns)
	int totalCards = displayList.size();
	if (totalCards == 0) return;

	// Keep exactly 10 cards per row and use scroll for additional rows.
	const int cols = 10;
	const float padX = 8.0f;
	const float padY = 10.0f;
	const float nameBand = 16.0f; // reserved text strip below each card
	float cardW = (panelWidth - 2.0f * padX - (cols - 1) * padX) / (float)cols;
	cardW = std::max(12.0f, cardW);
	float cardH = cardW * encyCardAspect;
	float rowStep = cardH + padY + nameBand;
	float gridWidth = cols * cardW + (cols - 1) * padX;
	float startX = panelX + (panelWidth - gridWidth) / 2.0f;
	int totalRows = (totalCards + cols - 1) / cols;
	float totalContentHeight = totalRows * rowStep;
	float maxScroll = std::max(0.0f, totalContentHeight - contentHeight);
	encyclopediaScrollOffset = ofClamp(encyclopediaScrollOffset, 0.0f, maxScroll);

	// Check for hover and update hover state
	int currentHoveredIndex = -1;
	int row = 0;
	int col = 0;
	for (size_t i = 0; i < displayList.size(); i++) {
		float drawX = startX + col * (cardW + padX);
		float drawY = contentY + row * rowStep - encyclopediaScrollOffset;

		if (drawY + cardH > contentY && drawY < contentBottom) {
			ofRectangle cardRect(drawX, drawY, cardW, cardH);
			if (cardRect.inside(ofGetMouseX(), ofGetMouseY()) && drawY >= contentY && drawY < contentBottom) {
				currentHoveredIndex = i;
				break;
			}
		}

		col++;
		if (col >= cols) {
			col = 0;
			row++;
		}
	}

	// Update hover timing
	if (currentHoveredIndex != encyclopediaHoveredIndex) {
		encyclopediaHoveredIndex = currentHoveredIndex;
		encyclopediaHoverStartTime = ofGetElapsedTimef();
		encyclopediaHoverScaled = false;
	} else if (currentHoveredIndex >= 0) {
		float hoverDuration = ofGetElapsedTimef() - encyclopediaHoverStartTime;
		if (hoverDuration >= 0.4f) {
			encyclopediaHoverScaled = true;
		}
	}

	// Clip card rendering to content area so cards never obscure Accept button
	ofPushStyle();
	glEnable(GL_SCISSOR_TEST);
	int scX = (int)panelX;
	int scW = (int)panelWidth;
	int scY = (int)(ofGetHeight() - (contentY + contentHeight));
	int scH = (int)contentHeight;
	glScissor(scX, scY, scW, scH);

	// Draw cards (draw non-hovered first, then hovered on top)
	row = 0;
	col = 0;
	for (int pass = 0; pass < 2; pass++) {
		row = 0;
		col = 0;
		for (size_t i = 0; i < displayList.size(); i++) {
			bool isThisCardHovered = (encyclopediaHoverScaled && (int)i == encyclopediaHoveredIndex);
			if ((pass == 0 && isThisCardHovered) || (pass == 1 && !isThisCardHovered)) {
				col++;
				if (col >= cols) {
					col = 0;
					row++;
				}
				continue;
			}

			float baseDrawX = startX + col * (cardW + padX);
			float baseDrawY = contentY + row * rowStep - encyclopediaScrollOffset;

			// Only draw if visible
			if (baseDrawY + cardH > contentY && baseDrawY < contentBottom) {
				const Card & card = displayList[i];

				// Apply hover scale
				float thisCardW = cardW;
				float thisCardH = cardH;
				float drawX = baseDrawX;
				float drawY = baseDrawY;

				if (isThisCardHovered) {
					float scaleUp = 1.8f;
					thisCardW = cardW * scaleUp;
					thisCardH = cardH * scaleUp;
					// Center the scaled card on its original position
					drawX = baseDrawX - (thisCardW - cardW) / 2.0f;
					drawY = baseDrawY - (thisCardH - cardH) / 2.0f;

					// Add glow for scaled card
					ofPushStyle();
					ofNoFill();
					const float lineW = 5.0f;
					ofSetLineWidth(lineW);
					ofSetColor(255, 255, 100, 190);
					drawCardOutlineOutside(drawX, drawY, thisCardW, thisCardH, lineW, 1.0f);
					ofPopStyle();
				}

				// Card rect for interaction
				ofRectangle cardRect(drawX, drawY, thisCardW, thisCardH);

				// Hover glow for non-scaled hover
				bool isHovered = (int)i == encyclopediaHoveredIndex && !encyclopediaHoverScaled;
				if (isHovered) {
					ofPushStyle();
					ofNoFill();
					const float lineW = 3.0f;
					ofSetLineWidth(lineW);
					ofSetColor(100, 150, 255, 170);
					drawCardOutlineOutside(drawX, drawY, thisCardW, thisCardH, lineW, 1.0f);
					ofPopStyle();
				}

				// Draw card art
				ofSetColor(255);

				Player * pPtr = nullptr;
				if (encyclopediaMode == ENC_REMOVE_FROM_PILE && encyclopediaTargetPlayerIndex >= 0 && encyclopediaTargetPlayerIndex < (int)players.size()) {
					pPtr = &players[encyclopediaTargetPlayerIndex];
				}

				drawCardFaceDynamic(cardSpriteSheet, cardEffectFont, titleFont, card, drawX, drawY, thisCardW, thisCardH, pPtr);

				// If selected, draw a yellow outline
				if (std::find(encyclopediaSelectedIndices.begin(), encyclopediaSelectedIndices.end(), (int)i) != encyclopediaSelectedIndices.end()) {
					ofNoFill();
					const float lineW = 6.0f;
					ofSetLineWidth(lineW);
					ofSetColor(ofColor::yellow);
					drawCardOutlineOutside(drawX, drawY, thisCardW, thisCardH, lineW, 1.0f);
					ofFill();
				}

				// Draw card name below
				if (isHovered || isThisCardHovered)
					ofSetColor(255, 255, 100);
				else
					ofSetColor(200, 200, 200);
				string shortName = card.name;
				if (shortName.length() > 15) shortName = shortName.substr(0, 12) + "...";
				ofRectangle nameBounds = uiFont.getStringBoundingBox(shortName, 0, 0);
				float nameX = drawX + (thisCardW - nameBounds.width) * 0.5f;
				float nameY = drawY + thisCardH + std::max(14.0f, nameBounds.height + 2.0f);
				uiFont.drawString(shortName, nameX, nameY);
			}

			col++;
			if (col >= cols) {
				col = 0;
				row++;
			}
		}
	}

	glDisable(GL_SCISSOR_TEST);
	ofPopStyle();

	// Scroll indicator
	if (maxScroll > 0.0f) {
		float scrollBarHeight = contentHeight * (contentHeight / totalContentHeight);
		scrollBarHeight = std::max(28.0f, scrollBarHeight);
		float scrollBarY = contentY + (encyclopediaScrollOffset / maxScroll) * (contentHeight - scrollBarHeight);
		ofSetColor(80, 80, 80, 220);
		float scrollBarX = panelX + panelWidth + 6.0f;
		ofDrawRectRounded(scrollBarX, scrollBarY, 8, scrollBarHeight, 4);
	}

	// Draw Accept button at bottom center
	encyclopediaAcceptButton.set(panelX + (panelWidth - acceptW) / 2.0f, acceptY, acceptW, acceptH);
	ofSetColor(0, 160, 0);
	if (encyclopediaAcceptButton.inside(ofGetMouseX(), ofGetMouseY())) {
		ofSetColor(0, 200, 0);
		g_hoveredButtonId = "ency_accept";
	}
	ofDrawRectRounded(encyclopediaAcceptButton, 8);

	ofSetColor(255);
	ofRectangle aBox = uiFont.getStringBoundingBox("Accept", 0, 0);
	uiFont.drawString("Accept", encyclopediaAcceptButton.getCenter().x - aBox.width / 2, encyclopediaAcceptButton.getCenter().y + aBox.height / 2 - 2);
}

// resolveDoubleHanded inlined at call sites. Legacy helper removed.
//--------------------------------------------------------------
void ofApp::determineStatusOptions(Player * target) {
	statusSelectLabels.clear();
	statusSelectButtons.clear();

	if (target->onFire) statusSelectLabels.push_back("Burning");
	if (target->isParalyzed) statusSelectLabels.push_back("Paralysis");
	if (target->isPoisoned) statusSelectLabels.push_back("Poisoned");
	if (target->sleepTurnsRemaining > 0) statusSelectLabels.push_back("Sleeping");

	if (statusSelectLabels.empty()) {
		// Use in-game floating text instead of a system dialog (preserves fullscreen)
		if (target) {
			queueFloatingTextVisual(gridToWorld(target->x, target->y), "Target has no status effects!", ofColor::yellow);
		} else {
			queueFloatingTextVisual(glm::vec3(ofGetWidth() / 2, ofGetHeight() / 2, 0), "Target has no status effects!", ofColor::yellow);
		}
		// Still consume the played Dispel card/AP so behavior matches other cards.
		if (interactingCardIndex != -1 && currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
			// Do NOT resetCardState() here, it wipes the state machine
			currentCardOutcome.cardType = CARD_DISPEL;
			currentCardOutcome.cardIndex = interactingCardIndex;
			currentCardOutcome.casterIndex = currentPlayerIndex;
			beginEffectSequence();
			advanceCardState(CARD_PLAY_STATE_EFFECT_SEQUENCE); // <-- FIXED
		}
		// Close status/menu UI only. Do not touch `cardPlayState` here.
		cardInteractionState = CARD_INTERACTION_STATE_IDLE; // <-- FIXED
		interactingCardType = CARD_NONE;
		interactingCardIndex = -1;
		interactionTargetIndex = -1;
		interactionMenuChoice.clear();
		statusSelectLabels.clear();
		statusSelectButtons.clear();
		statusSelectMenuRect.set(0, 0, 0, 0);
		dispelMode = 0;
		return;
	}

	// Otherwise, build menu
	float w = 400;
	float h = 60 + (statusSelectLabels.size() * 60);
	float x = ofGetWidth() / 2 - w / 2;
	float y = ofGetHeight() / 2 - h / 2;
	statusSelectMenuRect.set(x, y, w, h);

	for (size_t i = 0; i < statusSelectLabels.size(); i++) {
		statusSelectButtons.push_back(ofRectangle(x + 20, y + 60 + (i * 60), w - 40, 50));
	}
}

//--------------------------------------------------------------
void ofApp::applyDispelEffect(int statusID) {
	Player * target = getPlayer(interactionTargetIndex);
	if (!target) return;
	if (statusID <= STATUS_NONE) return;

	int safeCardIdx = interactingCardIndex; // Cache it!

	beginEffectSequence();
	EffectOp rm = {};
	rm.type = EffectOpType::REMOVE_STATUS;
	rm.data.status.targetIndex = interactionTargetIndex;
	rm.data.status.statusType = statusID;
	rm.data.status.duration = 0;
	queueEffect(rm);

	ofLogNotice("Dispel") << "Removed status id " << statusID;

	// FINALIZATION: route through centralized outcome path so AP/card handling
	// is consistent with other cards and lockstep-safe.
	if (safeCardIdx != -1 && currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
		resetCardState();
		currentCardOutcome.cardType = CARD_DISPEL;
		currentCardOutcome.cardIndex = safeCardIdx; // Use the cached value
		currentCardOutcome.casterIndex = currentPlayerIndex;
		advanceCardState(CARD_PLAY_STATE_EFFECT_SEQUENCE); // <-- FIXED
	}

	// FIX: Let both peers enter targeting mode!
	if (g_pendingShellSpikes > 0) {
		tryTriggerShellSpike();
	}

	// Always clear dispel UI transient state.
	statusSelectLabels.clear();
	statusSelectButtons.clear();
	statusSelectMenuRect.set(0, 0, 0, 0);
	dispelMode = 0;

	// Keep Shell Spike targeting prompt alive if it was opened.
	if (cardInteractionState != CARD_INTERACTION_STATE_TARGETING) {
		resetCardInteraction();
	}
}

//--------------------------------------------------------------
// Helper function to draw white outlined tiles that join together when adjacent
void ofApp::drawJoinedOutlines(bool highlightedTiles[BOARD_WIDTH][BOARD_HEIGHT], ofColor color, float surfaceY) {
	if (disableAllGlow) return;

	// Use solid geometric fills to guarantee thickness on Windows
	ofFill();
	ofSetColor(color);
	ofEnableDepthTest();

	float thickness = TILE_SIZE * 0.08f;
	float halfThick = thickness * 0.5f;
	float halfSize = TILE_SIZE * 0.5f;

	for (int x = 0; x < BOARD_WIDTH; x++) {
		for (int y = 0; y < BOARD_HEIGHT; y++) {
			if (!highlightedTiles[x][y]) continue;

			glm::vec3 worldPos = gridToWorld(x, y);
			float height = surfaceY + 0.03f;
			if (board[x][y].hasWall) {
				height = (TILE_SIZE * 0.5f) + 0.08f;
			}

			bool drawTop = (y == 0 || !highlightedTiles[x][y - 1]);
			bool drawBottom = (y == BOARD_HEIGHT - 1 || !highlightedTiles[x][y + 1]);
			bool drawLeft = (x == 0 || !highlightedTiles[x - 1][y]);
			bool drawRight = (x == BOARD_WIDTH - 1 || !highlightedTiles[x + 1][y]);

			ofPushMatrix();
			ofTranslate(worldPos.x, height, worldPos.z);
			ofRotateXDeg(90);

			if (drawTop) {
				ofDrawRectangle(-halfSize - halfThick, -halfSize - halfThick, TILE_SIZE + thickness, thickness);
			}
			if (drawBottom) {
				ofDrawRectangle(-halfSize - halfThick, halfSize - halfThick, TILE_SIZE + thickness, thickness);
			}
			if (drawLeft) {
				ofDrawRectangle(-halfSize - halfThick, -halfSize - halfThick, thickness, TILE_SIZE + thickness);
			}
			if (drawRight) {
				ofDrawRectangle(halfSize - halfThick, -halfSize - halfThick, thickness, TILE_SIZE + thickness);
			}

			ofPopMatrix();
		}
	}
}

//--------------------------------------------------------------
void ofApp::drawExpandingAOERings(float surfaceY) {
	// Draw expanding ring visualization for Magic Bolt / Psionic Wave previews
	// Rings expand from the center tile outward based on elapsed time
	auto drawOneRing = [&](const ExpandingAOERing & ring) {
		float elapsed = ofGetElapsedTimef() - ring.startTime;
		if (elapsed > ring.duration) return;

		float progress = elapsed / ring.duration;
		float currentRadiusFeet = 1.0f + (progress * (ring.maxRadiusFeet - 1.0f));

		std::vector<glm::ivec2> affectedTiles;
		for (int x = 0; x < BOARD_WIDTH; x++) {
			for (int y = 0; y < BOARD_HEIGHT; y++) {
				float centerDistFeet = glm::distance(glm::vec2(ring.centerTile.x + 0.5f, ring.centerTile.y + 0.5f), glm::vec2((float)x + 0.5f, (float)y + 0.5f)) * 5.0f;
				float neededFeetRaw = std::max(0.0f, centerDistFeet - 2.5f);
				int neededFeet = (int)floor(neededFeetRaw + 1e-4f);

				// For Psionic Wave, ignore LOS (walls don't block ring). For Magic Bolt, we check LOS elsewhere,
				// but visually the expanding ring passing through walls is fine/looks cool.
				if (neededFeet <= (int)currentRadiusFeet) {
					affectedTiles.push_back({ x, y });
				}
			}
		}

		if (!affectedTiles.empty()) {
			bool highlightedTiles[BOARD_WIDTH][BOARD_HEIGHT];
			memset(highlightedTiles, 0, sizeof(highlightedTiles));
			for (const auto & tile : affectedTiles) {
				highlightedTiles[tile.x][tile.y] = true;
			}

			float alpha = 200.0f * (1.0f - progress);
			ofColor ringColor(100, 200, 255, (int)alpha);
			drawJoinedOutlines(highlightedTiles, ringColor, surfaceY);
		}
	};

	if (disableAllGlow) return;

	if (activeAOERing.centerTile.x >= 0 && activeAOERing.centerTile.y >= 0) {
		drawOneRing(activeAOERing);
	}

	for (auto it = activeMagicBoltAOERings.begin(); it != activeMagicBoltAOERings.end();) {
		float elapsed = ofGetElapsedTimef() - it->startTime;
		if (elapsed > it->duration) {
			it = activeMagicBoltAOERings.erase(it);
			continue;
		}
		drawOneRing(*it);
		++it;
	}
}

//--------------------------------------------------------------
void ofApp::drawOpponentMenu() {
	drawMenuOverlay();
	ofEnableBlendMode(OF_BLENDMODE_ALPHA);
	ofSetColor(0, 0, 0, 100);
	ofDrawRectangle(0, 0, ofGetWidth(), ofGetHeight());

	auto drawHoverGlow = [&](const ofRectangle & rect) {
		ofPushStyle();
		ofNoFill();
		ofSetColor(255, 255, 255, 220); // Bright white glow
		ofSetLineWidth(5.0f);
		ofDrawRectRounded(rect.x - 2, rect.y - 2, rect.width + 4, rect.height + 4, 12);
		ofPopStyle();
	};

	int hover = opponentInteraction.hoveredChoice;

	// Standard Math
	float w = 720.0f, h = 360.0f;
	float mx = ofGetWidth() / 2.0f - w / 2.0f;
	float my = ofGetHeight() / 2.0f - h / 2.0f;
	ofRectangle menuRect(mx, my, w, h);
	float pad = 24.0f, cardH = 160.0f, spacing = 28.0f;
	float availableW = w - pad * 2.0f - spacing;
	float cardW = std::min(520.0f, availableW / 2.0f);

	ofRectangle btn1(mx + pad, my + h - pad - cardH, cardW, cardH);
	ofRectangle btn2(mx + pad + cardW + spacing, my + h - pad - cardH, cardW, cardH);

	if (opponentInteraction.type == 1) {
		bool isSelfTarget = (opponentInteraction.targetIndex >= 0 && opponentInteraction.targetIndex < (int)players.size() && currentPlayerIndex >= 0 && opponentInteraction.targetIndex == currentPlayerIndex);
		int deckSize = 0;
		if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) deckSize = (int)players[currentPlayerIndex].deck.size();

		string title = "Wisdom Boon";
		string desc = "Effect Strength: " + ofToString(deckSize) + " (Deck Size)";
		ofColor magicAccent(180, 140, 230);
		ofColor blockAccent(120, 120, 120);

		if (isSelfTarget) {
			drawCardChoicePanel(menuRect, title, desc, btn1, btn2, "Gain Block", "", blockAccent, blockAccent, false, false);
			if (hover == 1) drawHoverGlow(btn1);
		} else {
			drawCardChoicePanel(menuRect, title, desc, btn1, btn2, "Deal Magic Dmg", "", magicAccent, magicAccent, false, false);
			if (hover == 1) drawHoverGlow(btn1);
		}
	} else if (opponentInteraction.type == 2) {
		bool selfTarget = (opponentInteraction.targetIndex >= 0 && opponentInteraction.targetIndex < (int)players.size() && currentPlayerIndex >= 0 && opponentInteraction.targetIndex == currentPlayerIndex);
		bool healEnabled = true;
		if (opponentInteraction.targetIndex >= 0 && opponentInteraction.targetIndex < (int)players.size()) {
			healEnabled = (players[opponentInteraction.targetIndex].health < players[opponentInteraction.targetIndex].maxHealth);
		}

		drawCardChoicePanel(menuRect, "Burst of Light", "Waiting for player to choose...",
			btn1, btn2,
			selfTarget ? "Cannot Damage Self" : "Deal 3 Holy",
			healEnabled ? "Heal 3 HP" : "Target Full HP",
			ofColor(255, 213, 79), ofColor(144, 238, 144), false, false);

		if (hover == 1)
			drawHoverGlow(btn1);
		else if (hover == 2 && healEnabled)
			drawHoverGlow(btn2);
	} else if (opponentInteraction.type == 3) {
		drawCardChoicePanel(menuRect, "Double-Handed", "Waiting for player to choose...",
			btn1, btn2, "Punch", "Block",
			ofColor(200, 100, 100), ofColor(100, 150, 200), false, false);

		if (hover == 1)
			drawHoverGlow(btn1);
		else if (hover == 2)
			drawHoverGlow(btn2);
	} else if (opponentInteraction.type == 4) {
		int dmgAmount = 5;
		if (opponentInteraction.cardIndex >= 0 && opponentInteraction.cardIndex < (int)players[currentPlayerIndex].hand.size()) {
			int bd = players[currentPlayerIndex].hand[opponentInteraction.cardIndex].baseDamage;
			if (bd > 0) dmgAmount = bd;
		}

		string desc = "Waiting for player to choose... (" + ofToString(magicBlastChoicesRemaining) + " left)";
		drawCardChoicePanel(menuRect, "Magic Blast", desc,
			btn1, btn2, "Take " + ofToString(dmgAmount) + " Damage", "Remove Top Card",
			ofColor::indianRed, ofColor::darkSlateBlue, false, false);

		if (hover == 1)
			drawHoverGlow(btn1);
		else if (hover == 2)
			drawHoverGlow(btn2);
	} else if (opponentInteraction.type == 5) {
		string title = "Materialized in Wall";
		string desc = "Waiting for player to choose a tile...";
		float fw = 520, fh = 200;
		float fx = ofGetWidth() / 2 - fw / 2, fy = ofGetHeight() / 2 - fh / 2;
		ofRectangle mRect(fx, fy, fw, fh);
		ofSetColor(30, 30, 40, 240);
		ofDrawRectRounded(mRect, 12);
		ofSetColor(ofColor::white);
		ofRectangle tbox = uiFont.getStringBoundingBox(title, 0, 0);
		uiFont.drawString(title, mRect.getCenter().x - tbox.getWidth() / 2, mRect.y + 48);
		ofRectangle dbox = uiFont.getStringBoundingBox(desc, 0, 0);
		uiFont.drawString(desc, mRect.getCenter().x - dbox.getWidth() / 2, mRect.y + 88);
	} else if (opponentInteraction.type == 6) { // <--- ADD THIS BLOCK
		string title = "Renewed Inspiration";
		string desc = "Waiting for player to select cards...";
		float fw = 520, fh = 200;
		float fx = ofGetWidth() / 2 - fw / 2, fy = ofGetHeight() / 2 - fh / 2;
		ofRectangle mRect(fx, fy, fw, fh);
		ofSetColor(30, 30, 40, 240);
		ofDrawRectRounded(mRect, 12);
		ofSetColor(ofColor::white);
		ofRectangle tbox = uiFont.getStringBoundingBox(title, 0, 0);
		uiFont.drawString(title, mRect.getCenter().x - tbox.getWidth() / 2, mRect.y + 48);
		ofRectangle dbox = uiFont.getStringBoundingBox(desc, 0, 0);
		uiFont.drawString(desc, mRect.getCenter().x - dbox.getWidth() / 2, mRect.y + 88);
	}
}
// Helper: member equivalent of the local applyDamage lambda used in playCard
bool ofApp::applyDamageTo(Player & target, int damage, DamageType type, int attackerIndex) {
	string typeLabel = "";
	switch (type) {
	case DAMAGE_PHYSICAL:
		typeLabel = " Physical";
		break;
	case DAMAGE_PIERCING:
		typeLabel = " Piercing";
		break;
	case DAMAGE_MAGIC:
		typeLabel = " Magic";
		break;
	case DAMAGE_ELECTRIC:
		typeLabel = " Electric";
		break;
	case DAMAGE_FIRE:
		typeLabel = " Fire";
		break;
	case DAMAGE_POISON:
		typeLabel = " Poison";
		break;
	case DAMAGE_HOLY:
		typeLabel = " Holy";
		break;
	}

	int calculatedDamage = damage;

	ofLogNotice("Game") << "Dealing " << calculatedDamage << " damage to Player " << target.playerID;

	// Preserve starting HP for resurrection/checks
	int initialHealth = target.health;

	// Delegate deterministic absorption + HP modification to helper
	int applied = applyDamageWithMitigations(target, calculatedDamage, type, attackerIndex);
	glm::vec3 targetPos = gridToWorld(target.x, target.y);

	if (applied > 0) {
		queueFloatingTextVisual(targetPos, "-" + ofToString(applied) + typeLabel, ofColor::red);

		// --- AI REWARD SHAPING (POINTS) ---
		// Consolidates rewards to prevent double-accumulation, and supports status damage (attackerIndex == -1)
		if (headless && isAIvsAI) {
			// The AI ID is the owner of the currently active unit (whose turn it is)
			int aiID = players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID;

			// Figure out who the true attacker is (accounting for direct casts and start-of-turn status damage)
			int attackerOwner = -1;
			if (attackerIndex >= 0 && attackerIndex < (int)players.size()) {
				attackerOwner = players[attackerIndex].isMinion ? players[attackerIndex].ownerID : players[attackerIndex].playerID;
			} else {
				if (type == DAMAGE_FIRE && target.fireApplierPlayerID != -1) {
					attackerOwner = target.fireApplierPlayerID;
				} else if (type == DAMAGE_POISON && target.poisonApplierPlayerID != -1) {
					attackerOwner = target.poisonApplierPlayerID;
				}
			}

			int victimOwner = target.isMinion ? target.ownerID : target.playerID;

			if (attackerOwner != -1) {
				if (attackerOwner == aiID && victimOwner != aiID) {
					// The AI successfully hurt the enemy! Give it +0.2 points per damage dealt.
					cumulativeReward += (applied * 0.2f);
				} else if (victimOwner == aiID && attackerOwner != aiID) {
					// The AI got hurt! Penalize it -0.2 points per damage taken.
					cumulativeReward -= (applied * 0.2f);
				}
			}
		}
		// ----------------------------------

	} else {
		queueFloatingTextVisual(targetPos, "-0" + typeLabel, ofColor::gray);
	}

	// DEATH LOGIC COMPLETELY REMOVED FROM HERE!
	// It is now handled exclusively and safely inside simulationTick()
	// so that AOE spells don't shift array indices mid-resolution.

	return target.health < initialHealth;
}

void ofApp::drawGhostRelocateUI() {
	Player * targetPlayer = getPlayer(ghostRelocateTargetIndex);
	if (!targetPlayer) return;

	bool isLocalTarget = true;
	if (isMultiplayer) {
		isLocalTarget = (targetPlayer->playerID == myLocalPlayerID);
	}

	string title = "Materialized in Wall";
	string desc = isLocalTarget ? "Choose a nearby empty tile to teleport to:" : ("Waiting for Player " + ofToString(targetPlayer->playerID + 1) + "...");

	float panelW = 720, panelH = 360;
	float px = ofGetWidth() / 2.0f - panelW / 2.0f;
	float py = ofGetHeight() / 2.0f - panelH / 2.0f;
	ofRectangle panel(px, py, panelW, panelH);

	ofSetColor(30, 30, 40, 240 * g_menuAlphaMult);
	ofDrawRectRounded(panel, 12);

	ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
	ofRectangle tbox = uiFont.getStringBoundingBox(title, 0, 0);
	uiFont.drawString(title, panel.getCenter().x - tbox.getWidth() / 2.0f, panel.y + 48);
	ofRectangle dbox = uiFont.getStringBoundingBox(desc, 0, 0);
	uiFont.drawString(desc, panel.getCenter().x - dbox.getWidth() / 2.0f, panel.y + 88);

	// Build label, accent and enabled arrays and render as drafting-style cards
	int maxChoices = std::min((int)ghostRelocateChoices.size(), 4);
	std::vector<std::string> labels;
	std::vector<ofColor> accents;
	std::vector<bool> enabled;
	labels.reserve(maxChoices);
	accents.reserve(maxChoices);
	enabled.reserve(maxChoices);
	for (int i = 0; i < maxChoices; ++i) {
		glm::ivec2 g = ghostRelocateChoices[i];
		labels.push_back(std::string("Teleport to (") + ofToString(g.x) + "," + ofToString(g.y) + ")");
		accents.push_back(ofColor(100, 180, 220));
		enabled.push_back(isLocalTarget);
	}
	drawOptionCards(panel, title, desc, labels, accents, enabled, ghostRelocateButtons);
}

//------------------------------------------------------------------------
// Standardized card-choice panel helper
// Draws a panel and one or two buttons with consistent styling.
void ofApp::drawCardChoicePanel(const ofRectangle & panelRect,
	const std::string & title,
	const std::string & desc,
	ofRectangle & primaryRect,
	ofRectangle & secondaryRect,
	const std::string & primaryLabel,
	const std::string & secondaryLabel,
	ofColor primaryAccent,
	ofColor secondaryAccent,
	bool primaryEnabled,
	bool secondaryEnabled) {
	float pad = 24;
	float titleY = panelRect.y + 40;
	float descY = panelRect.y + 76;
	float cardH = 160.0f;
	float spacing = 28.0f;

	// Panel background (caller is expected to draw overlay if desired)
	ofSetColor(30, 30, 40, 240 * g_menuAlphaMult);
	ofDrawRectRounded(panelRect, 12);

	// Mini decision timer (used when another player's menu decision pauses the turn timer)
	if (opponentDecisionTimerActive) {
		float elapsed = (float)((int)(simulationFrame - opponentDecisionStartFrame));
		float remaining = std::max(0.0f, (float)opponentDecisionDurationFrames - elapsed);
		float pct = (opponentDecisionDurationFrames > 0) ? (remaining / (float)opponentDecisionDurationFrames) : 0.0f;
		float barW = std::min(240.0f, panelRect.getWidth() * 0.5f);
		float barH = 14.0f;
		float barX = panelRect.getCenter().x - barW * 0.5f;
		float barY = panelRect.y - 26.0f;

		ofSetColor(20, 20, 30, 220 * g_menuAlphaMult);
		ofDrawRectRounded(barX - 4.0f, barY - 4.0f, barW + 8.0f, barH + 8.0f, 6.0f);
		ofSetColor(60, 60, 70, 255 * g_menuAlphaMult);
		ofDrawRectRounded(barX, barY, barW, barH, 4.0f);
		ofColor fillC = ofColor::fromHsb(120 * pct, 200, 220);
		ofSetColor(fillC.r, fillC.g, fillC.b, 255 * g_menuAlphaMult);
		ofDrawRectRounded(barX, barY, barW * pct, barH, 4.0f);

		int secs = (int)std::ceil(remaining / turnTimerFramesPerSecond);
		std::string secsText = "Decision " + ofToString(secs) + "s";
		ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
		ofRectangle tb = uiFont.getStringBoundingBox(secsText, 0, 0);
		uiFont.drawString(secsText, barX + barW / 2.0f - tb.getWidth() / 2.0f, barY - 6.0f);
	}

	// Title
	ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
	ofRectangle titleBox = uiFont.getStringBoundingBox(title, 0, 0);
	uiFont.drawString(title, panelRect.getCenter().x - titleBox.getWidth() / 2, titleY);

	// Description
	if (!desc.empty()) {
		ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
		ofRectangle descBox = uiFont.getStringBoundingBox(desc, 0, 0);
		uiFont.drawString(desc, panelRect.getCenter().x - descBox.getWidth() / 2, descY);
	}

	// Compute card widths for one-or-two option layout (draft-like)
	if (secondaryLabel.empty()) {
		float cardW = std::min(520.0f, panelRect.getWidth() - pad * 2);
		primaryRect.set(panelRect.getCenter().x - cardW / 2, panelRect.y + panelRect.getHeight() - pad - cardH, cardW, cardH);
	} else {
		float availableW = panelRect.getWidth() - pad * 2 - spacing;
		float cardW = std::min(520.0f, availableW / 2.0f);
		primaryRect.set(panelRect.x + pad, panelRect.y + panelRect.getHeight() - pad - cardH, cardW, cardH);
		secondaryRect.set(panelRect.x + pad + cardW + spacing, panelRect.y + panelRect.getHeight() - pad - cardH, cardW, cardH);
	}

	// Draw primary card panel
	if (primaryEnabled) {
		if (primaryRect.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "panel_primary";
		ofSetColor(primaryAccent.r, primaryAccent.g, primaryAccent.b, 255 * g_menuAlphaMult);
	} else
		ofSetColor(90, 90, 90, 255 * g_menuAlphaMult);
	ofDrawRectRounded(primaryRect, 10);
	// small inner white inset for card-like look
	ofSetColor(255, 255, 255, 12 * g_menuAlphaMult);
	ofDrawRectRounded(primaryRect.x + 8, primaryRect.y + 8, primaryRect.width - 16, primaryRect.height - 16, 8);
	// Label
	ofSetColor((primaryEnabled && primaryAccent.getBrightness() > 200) ? ofColor(0, 0, 0, 255 * g_menuAlphaMult) : ofColor(255, 255, 255, 255 * g_menuAlphaMult));
	ofRectangle pBox = uiFont.getStringBoundingBox(primaryLabel, 0, 0);
	uiFont.drawString(primaryLabel, primaryRect.getCenter().x - pBox.getWidth() / 2, primaryRect.getCenter().y + pBox.getHeight() / 2);

	// Draw secondary card panel if present
	if (!secondaryLabel.empty()) {
		if (secondaryEnabled) {
			if (secondaryRect.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "panel_secondary";
			ofSetColor(secondaryAccent.r, secondaryAccent.g, secondaryAccent.b, 255 * g_menuAlphaMult);
		} else
			ofSetColor(90, 90, 90, 255 * g_menuAlphaMult);
		ofDrawRectRounded(secondaryRect, 10);
		ofSetColor(255, 255, 255, 12 * g_menuAlphaMult);
		ofDrawRectRounded(secondaryRect.x + 8, secondaryRect.y + 8, secondaryRect.width - 16, secondaryRect.height - 16, 8);
		ofSetColor((secondaryEnabled && secondaryAccent.getBrightness() > 200) ? ofColor(0, 0, 0, 255 * g_menuAlphaMult) : ofColor(255, 255, 255, 255 * g_menuAlphaMult));
		ofRectangle sBox = uiFont.getStringBoundingBox(secondaryLabel, 0, 0);
		uiFont.drawString(secondaryLabel, secondaryRect.getCenter().x - sBox.getWidth() / 2, secondaryRect.getCenter().y + sBox.getHeight() / 2);
	}
}

void ofApp::drawAcceptButtonShared(const ofRectangle & buttonRect, bool canAccept, float scale, float alpha) {
	ofPushMatrix();
	ofTranslate(buttonRect.getCenter().x, buttonRect.getCenter().y);
	ofScale(scale, scale);
	ofTranslate(-buttonRect.getCenter().x, -buttonRect.getCenter().y);

	ofSetColor(canAccept ? ofColor(70, 160, 255, (int)(255.0f * alpha)) : ofColor(100, 100, 100, (int)(255.0f * alpha)));
	ofDrawRectRounded(buttonRect, 12);

	ofSetColor(ofColor(255, 255, 255, (int)(255.0f * alpha)));
	ofRectangle tb = uiFont.getStringBoundingBox("Accept", 0, 0);
	float tx = std::round(buttonRect.getCenter().x - (tb.x + tb.width * 0.5f));
	float ty = std::round(buttonRect.getCenter().y - (tb.y + tb.height * 0.5f));
	uiFont.drawString("Accept", tx, ty);
	ofPopMatrix();
}

// Draw up to 4 drafting-style option cards inside panelRect. Populates outRects
// with the rectangles used for hit-testing (ordered to correspond to labels).
void ofApp::drawOptionCards(const ofRectangle & panelRect,
	const std::string & title,
	const std::string & desc,
	const std::vector<std::string> & labels,
	const std::vector<ofColor> & accents,
	const std::vector<bool> & enabled,
	std::vector<ofRectangle> & outRects) {

	float pad = 20.0f;
	float titleY = panelRect.y + 40;
	float descY = panelRect.y + 76;
	float spacing = 28.0f;
	float cardH = 160.0f;

	// Panel background
	ofSetColor(30, 30, 40, 240 * g_menuAlphaMult);
	ofDrawRectRounded(panelRect, 12);

	// Mini decision timer above panel
	if (opponentDecisionTimerActive) {
		float elapsed = (float)((int)(simulationFrame - opponentDecisionStartFrame));
		float remaining = std::max(0.0f, (float)opponentDecisionDurationFrames - elapsed);
		float pct = (opponentDecisionDurationFrames > 0) ? (remaining / (float)opponentDecisionDurationFrames) : 0.0f;
		float barW = std::min(240.0f, panelRect.getWidth() * 0.5f);
		float barH = 14.0f;
		float barX = panelRect.getCenter().x - barW * 0.5f;
		float barY = panelRect.y - 26.0f;

		ofSetColor(20, 20, 30, 220 * g_menuAlphaMult);
		ofDrawRectRounded(barX - 4.0f, barY - 4.0f, barW + 8.0f, barH + 8.0f, 6.0f);
		ofSetColor(60, 60, 70, 255 * g_menuAlphaMult);
		ofDrawRectRounded(barX, barY, barW, barH, 4.0f);
		ofColor fillC = ofColor::fromHsb(120 * pct, 200, 220);
		ofSetColor(fillC.r, fillC.g, fillC.b, 255 * g_menuAlphaMult);
		ofDrawRectRounded(barX, barY, barW * pct, barH, 4.0f);

		int secs = (int)std::ceil(remaining / turnTimerFramesPerSecond);
		std::string secsText = "Decision " + ofToString(secs) + "s";
		ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
		ofRectangle tb = uiFont.getStringBoundingBox(secsText, 0, 0);
		uiFont.drawString(secsText, barX + barW / 2.0f - tb.getWidth() / 2.0f, barY - 6.0f);
	}

	// Title
	ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
	ofRectangle titleBox = uiFont.getStringBoundingBox(title, 0, 0);
	uiFont.drawString(title, panelRect.getCenter().x - titleBox.getWidth() / 2, titleY);

	// Description
	if (!desc.empty()) {
		ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
		ofRectangle descBox = uiFont.getStringBoundingBox(desc, 0, 0);
		uiFont.drawString(desc, panelRect.getCenter().x - descBox.getWidth() / 2, descY);
	}

	int n = (int)labels.size();
	outRects.clear();
	if (n <= 0) return;

	int cols = (n == 1) ? 1 : 2;

	float totalW = panelRect.getWidth() - pad * 2 - spacing * (cols - 1);
	float cardW = std::min(520.0f, totalW / cols);

	float startX = panelRect.x + pad + (panelRect.getWidth() - (cardW * cols + spacing * (cols - 1))) / 2.0f;
	float startY = panelRect.y + panelRect.getHeight() - pad - cardH;

	for (int i = 0; i < n; ++i) {
		int r = i / cols;
		int c = i % cols;
		float bx = startX + c * (cardW + spacing);
		float by = startY - r * (cardH + spacing);
		ofRectangle br(bx, by, cardW, cardH);
		outRects.push_back(br);

		bool en = (i < (int)enabled.size()) ? enabled[i] : true;
		if (en && br.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "opt_card_" + ofToString(i);
		ofColor accent = (i < (int)accents.size()) ? accents[i] : ofColor(120, 120, 120);
		if (en)
			ofSetColor(accent.r, accent.g, accent.b, 255 * g_menuAlphaMult);
		else
			ofSetColor(70, 70, 70, 255 * g_menuAlphaMult);
		ofDrawRectRounded(br, 10);

		ofSetColor(255, 255, 255, 12 * g_menuAlphaMult);
		ofDrawRectRounded(br.x + 8, br.y + 8, br.width - 16, br.height - 16, 8);

		ofSetColor((en && accent.getBrightness() > 200) ? ofColor(0, 0, 0, 255 * g_menuAlphaMult) : ofColor(255, 255, 255, 255 * g_menuAlphaMult));
		ofRectangle tb = uiFont.getStringBoundingBox(labels[i], 0, 0);
		float tx = std::round(br.getCenter().x - (tb.x + tb.width * 0.5f));
		float ty = std::round(br.getCenter().y - (tb.y + tb.height * 0.5f));
		uiFont.drawString(labels[i], tx, ty);
	}
}
//--------------------------------------------------------------
// --- NEW HELPER: Converts a specific point in world space back to grid coordinates ---
glm::vec2 ofApp::worldToGrid(glm::vec3 worldPos) {
	float gridX = (worldPos.x / TILE_SIZE) + (BOARD_WIDTH / 2.0f);
	float gridY = (worldPos.z / TILE_SIZE) + (BOARD_HEIGHT / 2.0f);
	return glm::vec2(floor(gridX), floor(gridY));
}

//--------------------------------------------------------------
// Returns true if the ray is clear, false if blocked
bool ofApp::checkRayPhysics(glm::vec2 rayStart, glm::vec2 rayEnd) {
	int x = (int)floor(rayStart.x);
	int y = (int)floor(rayStart.y);
	int endX = (int)floor(rayEnd.x);
	int endY = (int)floor(rayEnd.y);

	if (x == endX && y == endY) return true;

	float dx = rayEnd.x - rayStart.x;
	float dy = rayEnd.y - rayStart.y;
	int stepX = (dx > 0) ? 1 : ((dx < 0) ? -1 : 0);
	int stepY = (dy > 0) ? 1 : ((dy < 0) ? -1 : 0);

	// DDA Math: Perfectly tracks which tile borders we cross
	float tMaxX = (stepX != 0) ? (floor(rayStart.x) + (stepX > 0 ? 1.0f : 0.0f) - rayStart.x) / std::abs(dx) : FLT_MAX;
	float tMaxY = (stepY != 0) ? (floor(rayStart.y) + (stepY > 0 ? 1.0f : 0.0f) - rayStart.y) / std::abs(dy) : FLT_MAX;

	float tDeltaX = (stepX != 0) ? 1.0f / std::abs(dx) : FLT_MAX;
	float tDeltaY = (stepY != 0) ? 1.0f / std::abs(dy) : FLT_MAX;

	auto isObstacle = [&](int qx, int qy) {
		if (qx < 0 || qx >= BOARD_WIDTH || qy < 0 || qy >= BOARD_HEIGHT) return true;
		return (board[qx][qy].hasWall || board[qx][qy].hasPlayer);
	};

	int steps = 0;

	while ((x != endX || y != endY) && steps < 1000) {
		steps++;

		if (std::abs(tMaxX - tMaxY) < 0.0001f) {
			// Perfect Diagonal crossing
			if (isObstacle(x + stepX, y) && isObstacle(x, y + stepY)) {
				return false; // Diagonal pinch!
			}
			x += stepX;
			y += stepY;
			tMaxX += tDeltaX;
			tMaxY += tDeltaY;
		} else if (tMaxX < tMaxY) {
			x += stepX;
			tMaxX += tDeltaX;
		} else {
			y += stepY;
			tMaxY += tDeltaY;
		}

		if (x == endX && y == endY) break;

		// The ray cannot hit anything in the middle
		if (isObstacle(x, y)) return false;

		// THE GAP RULE
		// If the tile is blocked on BOTH sides, the ray must be perfectly straight
		bool blockLeft = isObstacle(x - 1, y);
		bool blockRight = isObstacle(x + 1, y);
		bool blockUp = isObstacle(x, y - 1);
		bool blockDown = isObstacle(x, y + 1);

		if (blockLeft && blockRight) {
			if (std::abs(dx) > 0.001f) return false; // Squeezing horizontally through a vertical gap
		}
		if (blockUp && blockDown) {
			if (std::abs(dy) > 0.001f) return false; // Squeezing vertically through a horizontal gap
		}
	}
	return true;
}

ofApp::LosResult ofApp::getClearLosRay(glm::vec2 casterTile, glm::vec2 targetTile, CardType cardType) {
	// Return floats for the visualizer, but use 100% deterministic integers for logic
	glm::vec2 casterCenter = casterTile + 0.5f;
	glm::vec2 targetCenter = targetTile + 0.5f;

	if (cardType == CARD_ETHEREAL_JOLT || cardType == CARD_MAGIC_BOLT || cardType == CARD_TELEPORT) {
		return { true, casterCenter, targetCenter };
	}
	if (casterTile == targetTile) return { true, casterCenter, targetCenter };

	int cx = (int)casterTile.x;
	int cy = (int)casterTile.y;
	int tx = (int)targetTile.x;
	int ty = (int)targetTile.y;

	auto isObstacle = [&](int x, int y) {
		if (x < 0 || x >= BOARD_WIDTH || y < 0 || y >= BOARD_HEIGHT) return true;
		if (x == cx && y == cy) return false;
		if (x == tx && y == ty) return false;
		if (board[x][y].hasWall || board[x][y].hasPlayer) return true;
		return false;
	};

	// Immediate Adjacency Bypass
	int dxDist = std::abs(tx - cx);
	int dyDist = std::abs(ty - cy);
	if (dxDist <= 1 && dyDist <= 1) {
		if (dxDist + dyDist == 1) return { true, casterCenter, targetCenter };
		if (dxDist == 1 && dyDist == 1) {
			if (isTileBlocked(cx + (tx - cx), cy) && isTileBlocked(cx, cy + (ty - cy))) {
				return { false, casterCenter, targetCenter };
			}
			return { true, casterCenter, targetCenter };
		}
	}

	// --- INTEGER MATH GRID (Multiply by 1000) ---
	struct TileFaceInt {
		long long x, y;
		int nx, ny;
	};

	TileFaceInt tFaces[4] = {
		{ tx * 1000LL + 500LL, ty * 1000LL, 0, -1 }, // North
		{ tx * 1000LL + 500LL, ty * 1000LL + 1000LL, 0, 1 }, // South
		{ tx * 1000LL, ty * 1000LL + 500LL, -1, 0 }, // West
		{ tx * 1000LL + 1000LL, ty * 1000LL + 500LL, 1, 0 } // East
	};

	long long cCenterX = cx * 1000LL + 500LL;
	long long cCenterY = cy * 1000LL + 500LL;

	// 1. Find Target's closest face
	long long minDistSq = LLONG_MAX;
	for (int i = 0; i < 4; i++) {
		long long dx = tFaces[i].x - cCenterX;
		long long dy = tFaces[i].y - cCenterY;
		long long dSq = dx * dx + dy * dy;
		if (dSq < minDistSq) minDistSq = dSq;
	}

	std::vector<TileFaceInt> validTargetFaces;
	for (int i = 0; i < 4; i++) {
		long long dx = tFaces[i].x - cCenterX;
		long long dy = tFaces[i].y - cCenterY;
		long long dSq = dx * dx + dy * dy;

		// Exact integer match guarantees platforms never disagree on ties!
		if (dSq == minDistSq) {
			if (!isObstacle(tx + tFaces[i].nx, ty + tFaces[i].ny)) {
				validTargetFaces.push_back(tFaces[i]);
			}
		}
	}

	if (validTargetFaces.empty()) {
		return { false, casterCenter, targetCenter };
	}

	TileFaceInt cFaces[4] = {
		{ cx * 1000LL + 500LL, cy * 1000LL, 0, -1 },
		{ cx * 1000LL + 500LL, cy * 1000LL + 1000LL, 0, 1 },
		{ cx * 1000LL, cy * 1000LL + 500LL, -1, 0 },
		{ cx * 1000LL + 1000LL, cy * 1000LL + 500LL, 1, 0 }
	};

	// 2. Test valid caster faces against valid target faces
	for (const auto & tFace : validTargetFaces) {
		std::vector<TileFaceInt> validCasterFaces;

		for (int i = 0; i < 4; i++) {
			if (!isObstacle(cx + cFaces[i].nx, cy + cFaces[i].ny)) {
				long long dirX = tFace.x - cFaces[i].x;
				long long dirY = tFace.y - cFaces[i].y;

				if (dirX != 0 || dirY != 0) {
					long long dot = dirX * cFaces[i].nx + dirY * cFaces[i].ny;
					if (dot >= 0) {
						validCasterFaces.push_back(cFaces[i]);
					}
				}
			}
		}

		// Deterministic sort: use distance squared, tie-break with absolute coordinates
		std::sort(validCasterFaces.begin(), validCasterFaces.end(), [&](const TileFaceInt & a, const TileFaceInt & b) {
			long long dxa = a.x - tFace.x;
			long long dya = a.y - tFace.y;
			long long dxb = b.x - tFace.x;
			long long dyb = b.y - tFace.y;
			long long distA = dxa * dxa + dya * dya;
			long long distB = dxb * dxb + dyb * dyb;
			if (distA != distB) return distA < distB;
			if (a.x != b.x) return a.x < b.x;
			return a.y < b.y;
		});

		int facesToTest = std::min(2, (int)validCasterFaces.size());
		for (int i = 0; i < facesToTest; i++) {
			long long startX = validCasterFaces[i].x;
			long long startY = validCasterFaces[i].y;
			long long endX = tFace.x;
			long long endY = tFace.y;

			if (startX == endX && startY == endY) {
				return { true, glm::vec2(startX / 1000.0f, startY / 1000.0f), glm::vec2(endX / 1000.0f, endY / 1000.0f) };
			}

			long long rayDx = endX - startX;
			long long rayDy = endY - startY;

			bool blocked = false;
			int lastX = -1, lastY = -1;

			// Raycast using pure integer division. (Avoid s=0 and s=50 to slightly nudge inward)
			for (long long s = 1; s < 50; s++) {
				long long curX = startX + (rayDx * s) / 50LL;
				long long curY = startY + (rayDy * s) / 50LL;

				// Positive integer division securely acts as floor()
				int gx = (int)(curX / 1000LL);
				int gy = (int)(curY / 1000LL);

				if (gx == lastX && gy == lastY) continue;
				lastX = gx;
				lastY = gy;

				if (gx == cx && gy == cy) continue;
				if (gx == tx && gy == ty) continue;

				if (isObstacle(gx, gy)) {
					blocked = true;
					break;
				}

				bool horizGap = isObstacle(gx, gy - 1) && isObstacle(gx, gy + 1);
				bool vertGap = isObstacle(gx - 1, gy) && isObstacle(gx + 1, gy);

				if (horizGap && ty != gy) {
					blocked = true;
					break;
				}
				if (vertGap && tx != gx) {
					blocked = true;
					break;
				}
			}

			if (!blocked) {
				// Success! Convert back to floats exclusively for the Visual Tracer to draw it.
				return { true, glm::vec2(startX / 1000.0f, startY / 1000.0f), glm::vec2(endX / 1000.0f, endY / 1000.0f) };
			}
		}
	}

	// Fallback response for visualizer if all shots are blocked
	return { false, casterCenter, targetCenter };
}

TargetInfo ofApp::isLosTargetValid(glm::vec2 casterTile, glm::vec2 targetTile, float maxRangeFeet, CardType cardType) {
	TargetInfo result;
	result.reason = VALID;

	int casterIndexForSelfChecks = -1;
	if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
		if (players[currentPlayerIndex].x == (int)casterTile.x && players[currentPlayerIndex].y == (int)casterTile.y) {
			casterIndexForSelfChecks = currentPlayerIndex;
		}
	}
	if (casterTile == targetTile) {
		// NEVER allow these to hit the caster's own tile!
		if (cardType == CARD_FIREBALL || cardType == CARD_CHAIN_LIGHTNING || cardType == CARD_MAGIC_BOLT || cardType == CARD_ETHEREAL_JOLT || cardType == CARD_SHOOT_ARROW) {
			result.reason = INVALID_SELF;
			result.isTargetable = false;
			return result;
		}

		if (cardType == CARD_HEAL || cardType == CARD_LESSER_HEAL || cardType == CARD_BURST_OF_LIGHT) {
			if (casterIndexForSelfChecks >= 0 && players[casterIndexForSelfChecks].health >= players[casterIndexForSelfChecks].maxHealth) {
				result.reason = INVALID_SELF;
				result.isTargetable = false;
				return result;
			}
			result.reason = VALID;
			result.isTargetable = true;
			return result;
		}
		if (cardType == CARD_DOUBLE_HANDED || cardType == CARD_AMNESIA || cardType == CARD_WISDOM_BOON || cardType == CARD_DISPEL) {
			result.reason = VALID;
			result.isTargetable = true;
			return result;
		}
		int occupants = 0, ghostOccupants = 0;
		for (size_t i = 0; i < players.size(); ++i) {
			if (players[i].x == (int)casterTile.x && players[i].y == (int)casterTile.y) {
				occupants++;
				if (players[i].inGhostForm) ghostOccupants++;
			}
		}
		if (ghostOccupants > 0 && occupants > ghostOccupants) {
			result.reason = VALID;
			result.isTargetable = true;
			return result;
		}
		result.reason = INVALID_SELF;
		return result;
	}

	if (isTileWall((int)targetTile.x, (int)targetTile.y)) {
		bool allowWallTarget = false;
		if (cardType == CARD_ETHEREAL_JOLT || cardType == CARD_PSIONIC_WAVE || cardType == CARD_DEATH || cardType == CARD_MAGIC_BOLT) {
			if (board[(int)targetTile.x][(int)targetTile.y].hasPlayer) allowWallTarget = true;
		}
		if (!allowWallTarget) {
			result.reason = INVALID_OCCUPIED_BY_WALL;
			return result;
		}
	}

	auto los = getClearLosRay(casterTile, targetTile, cardType);

	if (!los.hasLos) {
		result.reason = INVALID_NO_LOS;
		return result;
	}

	long long distScaledSq = getFaceToFaceDistanceSquaredScaled(casterTile, targetTile);
	long long maxRangeSqScaled = (long long)maxRangeFeet * (long long)maxRangeFeet * 4LL;

	if (distScaledSq * 25LL > maxRangeSqScaled) {
		result.reason = INVALID_OUT_OF_RANGE;
		return result;
	}

	bool isOccupied = board[(int)targetTile.x][(int)targetTile.y].hasPlayer;

	// FIX: Explicitly allow ground-targeted AOE spells to target empty floor tiles!
	// ADDED: Magic Bolt and Magic Blast are also allowed to ground-target.
	bool isGroundTargetAoe = (cardType == CARD_FIREBALL || cardType == CARD_CHAIN_LIGHTNING || cardType == CARD_PSIONIC_WAVE || cardType == CARD_MAGIC_BOLT || cardType == CARD_MAGIC_BLAST);

	if (isGroundTargetAoe) {
		// Even if ground-targeting, the tile still must catch someone in the splash!
		if (cardType == CARD_MAGIC_BOLT || cardType == CARD_MAGIC_BLAST || cardType == CARD_CHAIN_LIGHTNING) {
			bool hasTargetInAoe = false;

			if (cardType == CARD_MAGIC_BOLT) {
				long long maxAoeFeet = 20LL;
				long long maxAoeDistSqScaled = maxAoeFeet * maxAoeFeet * 4LL;
				for (size_t i = 0; i < players.size(); ++i) {
					if (casterIndexForSelfChecks >= 0 && (int)i == casterIndexForSelfChecks) continue; // Cannot validate on self
					if (players[i].health <= 0) continue;
					long long distSq = getFaceToFaceDistanceSquaredScaled(targetTile, glm::vec2((float)players[i].x, (float)players[i].y));
					if (distSq * 25LL <= maxAoeDistSqScaled) {
						auto innerLosPath = getLineOfSightPath(targetTile + 0.5f, glm::vec2((float)players[i].x + 0.5f, (float)players[i].y + 0.5f));
						bool blockedByWall = false;
						for (const auto & stepP : innerLosPath) {
							if ((int)stepP.x == (int)targetTile.x && (int)stepP.y == (int)targetTile.y) continue;
							if ((int)stepP.x == players[i].x && (int)stepP.y == players[i].y) break;
							if (isTileWall((int)stepP.x, (int)stepP.y)) {
								blockedByWall = true;
								break;
							}
						}
						if (!blockedByWall) {
							hasTargetInAoe = true;
							break;
						}
					}
				}
			} else if (cardType == CARD_MAGIC_BLAST || cardType == CARD_CHAIN_LIGHTNING) {
				for (int dx = -1; dx <= 1; ++dx) {
					for (int dy = -1; dy <= 1; ++dy) {
						// Magic Blast is strictly orthogonal
						if (cardType == CARD_MAGIC_BLAST && std::abs(dx) == 1 && std::abs(dy) == 1) continue;

						int nx = (int)targetTile.x + dx;
						int ny = (int)targetTile.y + dy;
						if (nx >= 0 && nx < BOARD_WIDTH && ny >= 0 && ny < BOARD_HEIGHT && board[nx][ny].hasPlayer) {
							auto occs = getTileOccupants(nx, ny);
							for (int o : occs) {
								if (casterIndexForSelfChecks < 0 || o != casterIndexForSelfChecks) { // Must be someone other than caster
									bool blocked = false;
									if (dx != 0 || dy != 0) {
										// Chain Lightning diagonal pinch block
										if (cardType == CARD_CHAIN_LIGHTNING && std::abs(dx) == 1 && std::abs(dy) == 1) {
											if (isTileBlocked((int)targetTile.x + dx, (int)targetTile.y) && isTileBlocked((int)targetTile.x, (int)targetTile.y + dy)) {
												blocked = true;
											}
										}
									}
									if (!blocked) {
										hasTargetInAoe = true;
										break;
									}
								}
							}
						}
						if (hasTargetInAoe) break;
					}
					if (hasTargetInAoe) break;
				}
			}
			result.isTargetable = hasTargetInAoe;
		} else {
			// Fireball / Psionic Wave
			result.isTargetable = true;
		}
	} else {
		result.isTargetable = isOccupied;
	}

	return result;
}

std::vector<glm::vec2> ofApp::getLineOfSightPath(glm::vec2 startPoint, glm::vec2 endPoint) {
	std::vector<glm::vec2> path;

	// Convert floats to strict deterministic integers (scaled by 1000)
	long long sx = (long long)std::round(startPoint.x * 1000.0);
	long long sy = (long long)std::round(startPoint.y * 1000.0);
	long long ex = (long long)std::round(endPoint.x * 1000.0);
	long long ey = (long long)std::round(endPoint.y * 1000.0);

	long long dx = ex - sx;
	long long dy = ey - sy;

	// Point blank
	if (dx == 0 && dy == 0) {
		path.push_back(glm::vec2((float)(sx / 1000LL), (float)(sy / 1000LL)));
		return path;
	}

	long long absDx = std::abs(dx);
	long long absDy = std::abs(dy);
	long long maxDist = std::max(absDx, absDy);

	// Nudge inward slightly (1/1000th of a tile) to match old float logic
	// This prevents the ray from clipping the exact corners of walls
	sx += (dx * 1LL) / maxDist;
	sy += (dy * 1LL) / maxDist;
	ex -= (dx * 1LL) / maxDist;
	ey -= (dy * 1LL) / maxDist;

	// We replicate the "50 samples per tile" logic using pure integers
	long long numSamples = (maxDist * 50LL) / 1000LL;
	if (numSamples < 1) numSamples = 1;

	int lastX = -1, lastY = -1;
	for (long long s = 0; s <= numSamples; s++) {
		long long curX = sx + (dx * s) / numSamples;
		long long curY = sy + (dy * s) / numSamples;

		// Safe floor for negative numbers (just in case rays exit board)
		int gx = (curX >= 0) ? (int)(curX / 1000LL) : (int)((curX - 999LL) / 1000LL);
		int gy = (curY >= 0) ? (int)(curY / 1000LL) : (int)((curY - 999LL) / 1000LL);

		if (gx != lastX || gy != lastY) {
			path.push_back(glm::vec2((float)gx, (float)gy));
			lastX = gx;
			lastY = gy;
		}
	}

	return path;
}
// ----------------- HELPERS -----------------

// Returns true if the tile is a Wall, Unit, or Out of Bounds
bool ofApp::isTileBlocked(int x, int y) {
	if (x < 0 || x >= BOARD_WIDTH || y < 0 || y >= BOARD_HEIGHT) return true;
	// Both Walls AND Players block Line of Sight
	if (board[x][y].hasWall) return true;
	if (board[x][y].hasPlayer) return true;
	return false;
}

// Returns true ONLY if the tile is a Wall or Out of Bounds (ignores Units)
bool ofApp::isTileWall(int x, int y) {
	if (x < 0 || x >= BOARD_WIDTH || y < 0 || y >= BOARD_HEIGHT) return true;
	return board[x][y].hasWall;
}

// 0 = Open
// 1 = Vertical Choke (Blocked Left & Right) -> Requires Vertical Shot
// 2 = Horizontal Choke (Blocked Up & Down) -> Requires Horizontal Shot
int ofApp::isGapTile(glm::vec2 tile) {
	int x = (int)tile.x;
	int y = (int)tile.y;
	if (isTileBlocked(x, y)) return 0;

	bool blockLeft = isTileBlocked(x - 1, y);
	bool blockRight = isTileBlocked(x + 1, y);
	bool blockUp = isTileBlocked(x, y - 1);
	bool blockDown = isTileBlocked(x, y + 1);

	if (blockLeft && blockRight) return 1; // Vertical Choke
	if (blockUp && blockDown) return 2; // Horizontal Choke

	return 0;
}
//--------------------------------------------------------------
glm::vec2 ofApp::getClosestPointOnLineSegment(glm::vec2 p, glm::vec2 start, glm::vec2 end) {
	glm::vec2 lineVec = end - start;
	float lenSq = glm::dot(lineVec, lineVec);
	if (lenSq < 1e-5f) return start;

	glm::vec2 pVec = p - start;
	float t = glm::dot(pVec, lineVec) / lenSq;
	t = std::max(0.0f, std::min(1.0f, t));

	return start + lineVec * t;
}
//--------------------------------------------------------------
float ofApp::getFaceToFaceDistance(glm::vec2 casterTile, glm::vec2 targetTile) {
	if (casterTile == targetTile) return 0.0f;

	int cx = (int)casterTile.x;
	int cy = (int)casterTile.y;
	int tx = (int)targetTile.x;
	int ty = (int)targetTile.y;

	auto isFaceOpen = [&](int x, int y, int dirX, int dirY) {
		int nx = x + dirX;
		int ny = y + dirY;
		if (nx < 0 || nx >= BOARD_WIDTH || ny < 0 || ny >= BOARD_HEIGHT) return false;
		if (nx == cx && ny == cy) return true;
		if (nx == tx && ny == ty) return true;
		return !(board[nx][ny].hasWall || board[nx][ny].hasPlayer);
	};

	glm::vec2 cCenter = casterTile + 0.5f;
	glm::vec2 tCenter = targetTile + 0.5f;

	glm::vec2 faceOffsets[] = {
		{ 0.5f, 0.0f }, { -0.5f, 0.0f }, { 0.0f, 0.5f }, { 0.0f, -0.5f }
	};
	int faceDirs[4][2] = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };

	std::vector<glm::vec2> validCasterFaces;
	std::vector<glm::vec2> validTargetFaces;

	for (int i = 0; i < 4; i++) {
		if (isFaceOpen(cx, cy, faceDirs[i][0], faceDirs[i][1])) {
			validCasterFaces.push_back(cCenter + faceOffsets[i]);
		}
		if (isFaceOpen(tx, ty, faceDirs[i][0], faceDirs[i][1])) {
			validTargetFaces.push_back(tCenter + faceOffsets[i]);
		}
	}

	// Fallback to center if perfectly boxed in
	if (validCasterFaces.empty()) validCasterFaces.push_back(cCenter);
	if (validTargetFaces.empty()) validTargetFaces.push_back(tCenter);

	float shortestDist = std::numeric_limits<float>::max();
	for (const auto & cFace : validCasterFaces) {
		for (const auto & tFace : validTargetFaces) {
			float d = glm::distance(cFace, tFace);
			if (d < shortestDist) shortestDist = d;
		}
	}

	return std::max(0.2f, shortestDist);
}

long long ofApp::getFaceToFaceDistanceSquaredScaled(glm::vec2 casterTile, glm::vec2 targetTile) {
	if (casterTile == targetTile) return 0;

	int cx = (int)casterTile.x;
	int cy = (int)casterTile.y;
	int tx = (int)targetTile.x;
	int ty = (int)targetTile.y;

	int cx2 = cx * 2 + 1;
	int cy2 = cy * 2 + 1;
	int tx2 = tx * 2 + 1;
	int ty2 = ty * 2 + 1;

	int faceDirs[4][2] = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };

	auto isFaceOpen = [&](int x, int y, int dirX, int dirY) {
		int nx = x + dirX;
		int ny = y + dirY;
		if (nx < 0 || nx >= BOARD_WIDTH || ny < 0 || ny >= BOARD_HEIGHT) return false;
		if (nx == cx && ny == cy) return true;
		if (nx == tx && ny == ty) return true;
		return !(board[nx][ny].hasWall || board[nx][ny].hasPlayer);
	};

	std::vector<std::pair<int, int>> validCasterFaces;
	std::vector<std::pair<int, int>> validTargetFaces;

	for (int i = 0; i < 4; ++i) {
		if (isFaceOpen(cx, cy, faceDirs[i][0], faceDirs[i][1])) {
			validCasterFaces.push_back({ cx2 + faceDirs[i][0], cy2 + faceDirs[i][1] });
		}
		if (isFaceOpen(tx, ty, faceDirs[i][0], faceDirs[i][1])) {
			validTargetFaces.push_back({ tx2 + faceDirs[i][0], ty2 + faceDirs[i][1] });
		}
	}

	if (validCasterFaces.empty()) validCasterFaces.push_back({ cx2, cy2 });
	if (validTargetFaces.empty()) validTargetFaces.push_back({ tx2, ty2 });

	long long best = LLONG_MAX;
	for (const auto & cFace : validCasterFaces) {
		for (const auto & tFace : validTargetFaces) {
			long long dx = (long long)cFace.first - tFace.first;
			long long dy = (long long)cFace.second - tFace.second;
			long long d2 = dx * dx + dy * dy;
			if (d2 < best) best = d2;
		}
	}
	return best;
}
//--------------------------------------------------------------
bool ofApp::isOrthogonalPathBlocked(glm::vec2 start, glm::vec2 end) {
	int x1 = (int)start.x;
	int y1 = (int)start.y;
	int x2 = (int)end.x;
	int y2 = (int)end.y;

	// 1. Vertical Check (Same Column)
	if (x1 == x2) {
		int minY = std::min(y1, y2);
		int maxY = std::max(y1, y2);
		// Check every tile strictly between start and end
		for (int y = minY + 1; y < maxY; y++) {
			if (isTileWall(x1, y)) return true; // Blocked!
		}
		return false; // Path clear
	}

	// 2. Horizontal Check (Same Row)
	if (y1 == y2) {
		int minX = std::min(x1, x2);
		int maxX = std::max(x1, x2);
		// Check every tile strictly between start and end
		for (int x = minX + 1; x < maxX; x++) {
			if (isTileWall(x, y1)) return true; // Blocked!
		}
		return false; // Path clear
	}

	// Not orthogonal (Diagonal or Angled), so this check doesn't apply
	return false;
}
