void ofApp::updateDebugRects() {
	if (!isDebugMode) return;
	float panelWidth = 220;
	float panelX = ofGetWidth() - panelWidth - 20;
	float panelY = 40;
	if (players.size() >= 2 && currentPlayerIndex != -1) {
		panelY = p1_deckRect.getBottom() + 20;
	}
	float btnH = 45;
	float pad = 10;
	float curY = panelY + pad + uiFont.getLineHeight() + pad;

	debugDrawCardButton.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
	curY += btnH + pad;
	debugSpawnCardButton.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
	curY += btnH + pad;
	debugDiceDropdownButton.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
	curY += btnH + pad;

	if (isDebugDiceDropdownOpen) {
		debugRollD6Button.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
		curY += btnH + pad;
		debugRollD4Button.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
		curY += btnH + pad;
		debugRollD20Button.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
		curY += btnH + pad;
	}

	debugSpawnUnitButton.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
	curY += btnH + pad;
	debugUnlimitedAPButton.set(panelX + pad, curY, panelWidth - 2 * pad, btnH);
	curY += btnH + pad;
	// Force End Turn button removed

	debugPanel.set(panelX, panelY, panelWidth, curY - panelY);
}
//--------------------------------------------------------------
void ofApp::debugSkipDraftRandomCards() {
	// Only works in singleplayer during draft
	if (isMultiplayer || currentState != STATE_DRAFTING) {
		ofLogWarning("Debug") << "Cannot skip draft: multiplayer=" << isMultiplayer << " state=" << currentState;
		return;
	}

	ofLogNotice("Debug") << "Skipping entire draft and adding random cards";

	// Add random cards from ALL classes to simulate full draft for both players
	for (size_t pIdx = 0; pIdx < players.size(); ++pIdx) {
		if (players[pIdx].isMinion) continue;

		Player & targetPlayer = players[pIdx];

		// Class 1: Add 2 random cards, 2 copies each
		for (int pick = 0; pick < 2; ++pick) {
			if (!class1Cards.empty()) {
				int randomIdx = getGameRandom(0, (int)class1Cards.size() - 1);
				Card card = class1Cards[randomIdx];
				targetPlayer.deck.push_back(card);
				targetPlayer.deck.push_back(card);
			}
		}

		// Class 2: Add 1 random card, 1 copy
		if (!class2Cards.empty()) {
			int randomIdx = getGameRandom(0, (int)class2Cards.size() - 1);
			Card card = class2Cards[randomIdx];
			targetPlayer.deck.push_back(card);
		}

		shuffleGameVector(targetPlayer.deck, pIdx);
	}

	// Clear draft state
	draftOptions.clear();
	initialDraftComplete = true;
	isInGameDraft = false;
	inGameDraftTargetIdx = -1;
	networkPending.keyDraftKeyX = -1;
	networkPending.keyDraftKeyY = -1;
	selectedDraftIndices.clear();
	draftAcceptLocked = false;
	waitingForDraftOptionsStartTime = 0.0f;

	// Initialize game - move directly to gameplay
	ofLogNotice("Debug") << "Draft skipped, starting gameplay";

	// Set up the first player to move
	currentPlayerIndex = 0;
	if (!isMultiplayer && players.size() > 0) {
		// Find player 0 index
		for (size_t i = 0; i < players.size(); ++i) {
			if (players[i].playerID == 0) {
				currentPlayerIndex = i;
				break;
			}
		}
	}

	// Initialize turn state
	currentAP = 3; // Standard starting AP
	players[currentPlayerIndex].ap = currentAP;
	hasDrawnCardsThisTurn = false;

	// In singleplayer/AI, we must set the first player explicitly to match the initiative roll winner.
	if (!isMultiplayer) {
		currentPlayerIndex = draftPlayerIndex;
	}

	// NO DRAWING - decks are pre-populated with cards from draft

	// Set state to gameplay
	currentState = STATE_GAMEPLAY;

	// Ensure visuals and turn-start logic are initialized for the chosen active player
	if (currentPlayerIndex >= 0 && currentPlayerIndex < (int)players.size()) {
		playerVisualPos = gridToWorld(players[currentPlayerIndex].x, players[currentPlayerIndex].y);
		// Run the normal continue-of-turn initialization so AP, draws, and effects are correct
		// Defer authoritative turn-start to the deterministic tick
		requestStartNewTurn();
	}
}
//--------------------------------------------------------------
void ofApp::cleanupGame() {
	s_pendingRemoteChecksums.clear();
	s_pendingLocalChecksums.clear();

	players.clear();
	activeDiceRolls.clear();
	activeCardDisplays.clear();
	activeStolenCardAnimations.clear();
	activePlayedCardAnimations.clear();
	activeRemovedCardAnimations.clear();

	for (int x = 0; x < BOARD_WIDTH; ++x) {
		for (int y = 0; y < BOARD_HEIGHT; ++y) {
			board[x][y] = Tile(); // Reset each tile
		}
	}

	currentPlayerIndex = -1;
	currentTurnOwnerID = -1;
	currentTurnHadMeaningfulAction = false;
	currentTurnTimeoutProcessed = false;
	afkStrikeCounts = { 0, 0 };
	reconnectForfeitStartTime = -1.0f;
	g_isGameOver = false;
	g_drawOfferPlayerID = -1; // <--- ADDED THIS
	waitingForReconnect = false;
	playerAction = NONE;
	g_playerDefenses.clear();
	selectedCardIndex = -1;
	draggedCardIndex = -1;
	isPlayerAnimating = false;
	animatingPlayerIndex = -1;
	isLoadingGame = false;
	hasReceivedHandshake = false;
	clientSentReady = false;

	g_opponentDecisionQueue.clear(); // Clear the decision queue!

	g_isSpectator = false; // Safely reset spectator flag when match ends

	// Reset Chat State to prevent Hotkeys from getting locked in menus
	isChatOpen = false;
	isChatMinimized = true;
	chatInput.clear();
	lastChatInteractionTime = -999.0f;

	// --- FIX: Reset all Lobby and Connection flags to prevent getting stuck ---
	g_isHostingLobby = false;
	g_isConnectingToLobby = false;
	waitingForClientHandshake = false;
	hostWaitingForClientsReadyStartTime = 0.0f; // <--- This caused the "Endless Dice" bug!
	isInGameDraft = false;
	initialDraftComplete = false;

	ofLogNotice("Game") << "--- GAME SESSION CLEANED UP ---";
}
//-----------------------------------------------------------
void ofApp::loadCardData(const std::string & filePath) {
	ofJson json;
	if (!ofFile(filePath).exists()) {
		ofLogError("ofApp::loadCardData") << "Could not find card data file: " << filePath;
		return;
	}
	json = ofLoadJson(filePath);

	allCards.clear();
	class1Cards.clear();
	class2Cards.clear();
	class3Cards.clear();

	int cardPixelWidth = 409;
	int cardPixelHeight = 585;
	// If using a custom template, match texture rect dimensions to the
	// template image size so cards are not clipped/overlapped.
	{
		ofImage templateProbe;
		std::string chosenProbePath = findCardTemplatePath();
		if (!chosenProbePath.empty() && templateProbe.load(chosenProbePath)) {
			if (templateProbe.getWidth() > 0 && templateProbe.getHeight() > 0) {
				cardPixelWidth = (int)templateProbe.getWidth();
				cardPixelHeight = (int)templateProbe.getHeight();
				ofLogNotice("Cards") << "Card slot size set from template: " << cardPixelWidth << "x" << cardPixelHeight << " (" << chosenProbePath << ")";
			}
		} else {
			ofLogNotice("Cards") << "No template probe found in UI/; using default card slot size: " << cardPixelWidth << "x" << cardPixelHeight;
		}
	}
	const int numCols = 10;

	for (const auto & cardJson : json) {
		Card newCard;
		int cardId = cardJson.value("id", 0);
		if (cardId == 0) continue;

		newCard.name = cardJson.value("name", "Unnamed");
		newCard.type = stringToCardType(cardJson.value("type", "CARD_NONE"));
		newCard.cost = cardJson.value("cost", 0);
		newCard.value = cardJson.value("value", 0);
		newCard.targeting = stringToTargetingType(cardJson.value("targeting", "TARGET_NONE"));
		newCard.damageType = stringToDamageType(cardJson.value("damageType", "DAMAGE_PHYSICAL"));
		newCard.numDice = cardJson.value("numDice", 0);
		newCard.diceSides = cardJson.value("diceSides", 0);
		newCard.rangeDiceNum = cardJson.value("rangeDiceNum", 0);
		newCard.rangeDiceSides = cardJson.value("rangeDiceSides", 0);
		newCard.utilityDiceNum = cardJson.value("utilityDiceNum", 0);
		newCard.utilityDiceSides = cardJson.value("utilityDiceSides", 0);
		newCard.summonDiceNum = cardJson.value("summonDiceNum", 0);
		newCard.summonDiceSides = cardJson.value("summonDiceSides", 0);
		newCard.summonKind = cardJson.value("summonKind", 0);

		// Optional variant definitions and HP derivation (used for Golem/KoboldKing)
		if (cardJson.contains("variants")) newCard.variantDefs = cardJson["variants"];
		newCard.hpDerivedFromUnitType = cardJson.value("hpDerivedFromUnitType", std::string(""));
		newCard.hpDerivedAdd = cardJson.value("hpDerivedAdd", 0);
		newCard.baseDamage = cardJson.value("baseDamage", 0);
		newCard.damageDiceNum = cardJson.value("damageDiceNum", 0);
		newCard.damageDiceSides = cardJson.value("damageDiceSides", 0);
		newCard.aoeRadiusDiceNum = cardJson.value("aoeRadiusDiceNum", 0);
		newCard.aoeRadiusDiceSides = cardJson.value("aoeRadiusDiceSides", 0);
		newCard.applyStatus = stringToStatusType(cardJson.value("applyStatus", "STATUS_NONE"));
		newCard.statusDuration = cardJson.value("statusDuration", 0);
		// Healing: support both legacy `healAmount` and new `baseHeal` + `healDice` fields
		newCard.healAmount = cardJson.value("healAmount", 0);
		newCard.baseHeal = cardJson.value("baseHeal", newCard.healAmount);
		newCard.healDiceNum = cardJson.value("healDiceNum", 0);
		newCard.healDiceSides = cardJson.value("healDiceSides", 0);

		// AP gains: support immediate/next-turn variants
		newCard.apGain = cardJson.value("apGain", 0);
		newCard.apGainThisTurn = cardJson.value("apGainThisTurn", newCard.apGain);
		newCard.apGainNextTurn = cardJson.value("apGainNextTurn", 0);
		newCard.drawCount = cardJson.value("drawCount", 0);
		newCard.discardHandCount = cardJson.value("discardHandCount", 0);
		newCard.discardDeckCount = cardJson.value("discardDeckCount", 0);
		// destroyDeckTargetCount is an alternate name for discardDeckCount
		newCard.destroyDeckTargetCount = cardJson.value("destroyDeckTargetCount", newCard.discardDeckCount);
		newCard.isAoe = cardJson.value("isAoe", false);
		newCard.isHandRelated = cardJson.value("isHandRelated", false);

		// Defensive amounts
		// Defensive amounts: support both legacy names and the new *Gain names
		newCard.blockAmount = cardJson.value("blockAmount", 0);
		newCard.blockGain = cardJson.value("blockGain", newCard.blockAmount);
		newCard.blockAmount = newCard.blockGain;

		newCard.wardAmount = cardJson.value("wardAmount", 0);
		newCard.wardGain = cardJson.value("wardGain", newCard.wardAmount);
		newCard.wardAmount = newCard.wardGain;

		newCard.barrierAmount = cardJson.value("barrierAmount", 0);
		newCard.barrierGain = cardJson.value("barrierGain", newCard.barrierAmount);
		newCard.barrierAmount = newCard.barrierGain;

		newCard.holyBlockAmount = cardJson.value("holyBlockAmount", 0);
		newCard.holyBlockGain = cardJson.value("holyBlockGain", newCard.holyBlockAmount);
		newCard.holyBlockAmount = newCard.holyBlockGain;

		// Fortify can be expressed as either 'fortifyAmount' or 'fortificationAmount' in JSON
		newCard.fortifyAmount = cardJson.value("fortifyAmount", cardJson.value("fortificationAmount", 0));
		newCard.fortificationGain = cardJson.value("fortificationGain", newCard.fortifyAmount);
		newCard.fortifyAmount = newCard.fortificationGain;

		newCard.maxHealthGain = cardJson.value("maxHealthGain", cardJson.value("hpDerivedAdd", 0));
		newCard.hpDerivedAdd = newCard.maxHealthGain;

		newCard.luckGain = cardJson.value("luckGain", 0);

		// Parse Class (Default to 1 if missing)
		newCard.cardClass = cardJson.value("class", 1);

		// Calculate texture coordinates from the sprite sheet based on ID
		int index = cardId - 1;
		int row = index / numCols;
		int col = index % numCols;
		newCard.textureRect = ofRectangle(col * cardPixelWidth, row * cardPixelHeight, cardPixelWidth, cardPixelHeight);

		allCards.push_back(newCard);

		// Sort into Class Buckets
		if (newCard.cardClass == 1)
			class1Cards.push_back(newCard);
		else if (newCard.cardClass == 2)
			class2Cards.push_back(newCard);
		else if (newCard.cardClass == 3)
			class3Cards.push_back(newCard);
	}
	ofLogNotice("ofApp::loadCardData") << "Loaded " << allCards.size() << " cards from JSON.";
	ofLogNotice("ofApp::loadCardData") << "Class Distribution - C1: " << class1Cards.size() << ", C2: " << class2Cards.size() << ", C3: " << class3Cards.size();

	// Optional runtime card rendering path:
	// - template image: whichever file is present in UI/ (see `findCardTemplatePath()`)
	// - content source: UI/cards.md
	// - field layout/scales are configured directly in CardTemplateLayout (this .cpp)
	// Keeps template base image if markdown build fails.
	// FIX: Skip generating this 10,500x10,500 image atlas in headless mode to save 440MB of RAM per instance!
	if (!headless) {
		const std::string cardTemplatePath = findCardTemplatePath();
		if (rebuildCardSpriteSheetFromTemplate(cardTemplatePath, "UI/cards.md", allCards, titleFont, cardEffectFont, cardSpriteSheet)) {
			cardSpriteSheet.getTexture().setTextureMinMagFilter(GL_NEAREST, GL_NEAREST);
			cardSpriteSheet.getTexture().setTextureWrap(GL_CLAMP_TO_EDGE, GL_CLAMP_TO_EDGE);
			ofLogNotice("Cards") << "Using runtime template-generated card sheet from " << cardTemplatePath << " + UI/cards.md";
		} else {
			ofLogWarning("Cards") << "Template text generation failed; keeping base template image " << cardTemplatePath;
		}
	}
}

// --------------------------------------------------------------
// Settings persistence
// --------------------------------------------------------------

void ofApp::saveSettings() {
	ofJson json;
	json["masterVolume"] = settingsMasterVolume;
	json["menuVolume"] = settingsMenuVolume;
	json["sfxVolume"] = settingsSfxVolume;
	// Removed musicMuted/musicLoop from settings persistence
	json["showFPS"] = settingsShowFPS;
	json["cameraSensitivity"] = settingsCameraSensitivity;
	json["invertCameraY"] = settingsInvertCameraY;
	json["uiScale"] = settingsUIScale;
	json["useVSync"] = settingsUseVSync;
	json["showHints"] = settingsShowHints;
	json["framerateSliderValue"] = settingsFramerateSliderValue;
	json["currentResolutionIndex"] = currentResolutionIndex;
	json["windowModeState"] = g_windowModeState;

	// Key bindings
	ofJson kb = ofJson::array();
	for (const auto & p : settingsKeyBindings) {
		ofJson obj;
		obj["action"] = p.first;
		obj["key"] = p.second;
		kb.push_back(obj);
	}
	json["keyBindings"] = kb;

	std::string path = "Config/settings.json";
	try {
		ofSaveJson(path, json);
		ofLogNotice("Settings") << "Saved settings to " << path;
	} catch (...) {
		ofLogError("Settings") << "Failed to save settings to " << path;
	}
}

void ofApp::loadSettings() {
	std::string path = "Config/settings.json";
	if (!ofFile(path).exists()) {
		ofLogNotice("Settings") << "No settings file found; using defaults.";
		return;
	}
	try {
		ofJson json = ofLoadJson(path);
		settingsMasterVolume = json.value("masterVolume", settingsMasterVolume);
		settingsMenuVolume = json.value("menuVolume", settingsMenuVolume);
		settingsSfxVolume = json.value("sfxVolume", settingsSfxVolume);
		// Removed musicMuted/musicLoop from settings load
		settingsShowFPS = json.value("showFPS", settingsShowFPS);
		settingsCameraSensitivity = json.value("cameraSensitivity", settingsCameraSensitivity);
		settingsInvertCameraY = json.value("invertCameraY", settingsInvertCameraY);
		settingsUIScale = json.value("uiScale", settingsUIScale);
		settingsUseVSync = json.value("useVSync", settingsUseVSync);
		settingsShowHints = json.value("showHints", settingsShowHints);

		settingsFramerateSliderValue = json.value("framerateSliderValue", settingsFramerateSliderValue);
		currentResolutionIndex = json.value("currentResolutionIndex", currentResolutionIndex);
		g_windowModeState = json.value("windowModeState", g_windowModeState);

		// Key bindings
		if (json.contains("keyBindings") && json["keyBindings"].is_array()) {
			settingsKeyBindings.clear();
			for (const auto & obj : json["keyBindings"]) {
				std::string action = obj.value("action", std::string(""));
				int key = obj.value("key", 0);
				settingsKeyBindings.push_back({ action, key });
			}
		}

		// Apply audio immediately
		if (mainMenuMusic.isLoaded()) {
			mainMenuMusic.setVolume(settingsMasterVolume * settingsMenuVolume);
		}
		if (g_gameMusic.isLoaded()) {
			g_gameMusic.setVolume(settingsMasterVolume * settingsMenuVolume);
		}

		// Apply v-sync/framerate
		if (settingsUseVSync)
			ofSetVerticalSync(true);
		else
			ofSetVerticalSync(false);

		if (settingsFramerateSliderValue >= 0.999f) {
			ofSetFrameRate(0);
		} else {
			int targetFPS = 15 + (int)std::round(settingsFramerateSliderValue * (300 - 15));
			ofSetFrameRate(std::min(targetFPS, 300));
		}

		ofLogNotice("Settings") << "Loaded settings from " << path;
	} catch (...) {
		ofLogError("Settings") << "Failed to load settings from " << path;
	}
}

