//--------------------------------------------------------------
void ofApp::drawMinionStatusBars(Player & minion, const std::string & name, float x, float y, float totalWidth, float preferredHpWidth, bool alignRight) {
	float scale = getUIScaleFromHeight(ofGetHeight());
	float fontScale = 1.15f; // Increased font scale for readability

	// 1. Main Stats Bar
	float barHeight = 24 * scale; // Increased bar height
	ofRectangle nameBounds = uiFont.getStringBoundingBox(name, 0, 0);
	float barY = y + (nameBounds.height * fontScale) + (4 * scale);

	float statW = totalWidth * 0.20f;
	float usedWidth = 0;

	// --- FIX: Add holyBlock to width calculation ---
	if (minion.block > 0) usedWidth += statW;
	if (minion.fortification > 0) usedWidth += statW;
	if (minion.barrier > 0) usedWidth += statW;
	if (minion.holyBlock > 0) usedWidth += statW; // <--- ADDED
	if (minion.ward > 0) usedWidth += statW;

	// Prefer the requested HP width (e.g. match the player HP bar length),
	// but clamp so bars never overflow the available totalWidth.
	float hpW = std::min(std::max(0.0f, totalWidth - usedWidth), preferredHpWidth);
	float totalBarW = hpW + usedWidth;
	float barStartX = alignRight ? (x + std::max(0.0f, totalWidth - totalBarW)) : x;
	float currentX = barStartX;

	// --- HEALTH ---
	ofSetColor(40, 0, 0);
	ofDrawRectangle(currentX, barY, hpW, barHeight);
	float hpPct = (float)minion.health / minion.maxHealth;
	ofSetColor(ofColor::red);
	ofDrawRectangle(currentX, barY, hpW * hpPct, barHeight);
	string hpText = ofToString(minion.health) + "/" + ofToString(minion.maxHealth);
	// Make HP text larger for readability by using the local fontScale
	drawStatText(uiFont, hpText, currentX, barY, hpW, barHeight, ofColor::white, fontScale);
	currentX += hpW;

	// --- SHIELDS (With Tooltips) ---
	auto drawMinionSeg = [&](int val, ofColor c, string label) {
		if (val > 0) {
			ofSetColor(c);
			ofDrawRectangle(currentX, barY, statW, barHeight);
			drawStatText(uiFont, ofToString(val), currentX, barY, statW, barHeight, (c.getBrightness() > 200 ? ofColor::black : ofColor::white));

			// Tooltip Check
			if (ofRectangle(currentX, barY, statW, barHeight).inside(ofGetMouseX(), ofGetMouseY())) {
				isShowingTooltip = true;
				tooltipPos = { (float)ofGetMouseX(), (float)ofGetMouseY() };
				tooltipText = label;
			}
			currentX += statW;
		}
	};

	drawMinionSeg(minion.block, ofColor::gray, "Block (Physical)");
	drawMinionSeg(minion.fortification, ofColor(50, 50, 50), "Fortification (Phys/Pierce)");
	drawMinionSeg(minion.barrier, ofColor::hotPink, "Barrier (Non-Physical)");

	// --- FIX: Add Holy Block Drawing ---
	drawMinionSeg(minion.holyBlock, ofColor::yellow, "Holy Block (Holy)"); // <--- ADDED

	drawMinionSeg(minion.ward, ofColor::black, "Ward (All Damage)");

	// --- FORM BARS ---
	if (minion.inTortoiseForm || minion.inGhostForm) {
		float formY = barY + barHeight + (2 * scale);
		float formHeight = 18 * scale; // Increased form bar height
		float formStartX = alignRight ? (x + std::max(0.0f, totalWidth - totalBarW)) : x;

		if (minion.inTortoiseForm) {
			int rem = 5 - minion.tortoiseDamageTaken;
			ofSetColor(20, 40, 20);
			ofDrawRectangle(formStartX, formY, totalBarW, formHeight);
			ofSetColor(ofColor::darkGreen);
			ofDrawRectangle(formStartX, formY, totalBarW * (rem / 5.0f), formHeight);
			drawStatText(uiFont, "Tortoise: " + ofToString(rem) + "/5", formStartX, formY, totalBarW, formHeight, ofColor::white);

			// Tooltip
			if (ofRectangle(formStartX, formY, totalBarW, formHeight).inside(ofGetMouseX(), ofGetMouseY())) {
				isShowingTooltip = true;
				tooltipPos = { (float)ofGetMouseX(), (float)ofGetMouseY() };
				tooltipText = "Tortoise Form: Buffer HP";
			}

			// Stack next bar if needed
			formY += formHeight + (2 * scale);
		}

		if (minion.inGhostForm) {
			int rem = 4 - minion.ghostDamageTaken;
			ofSetColor(30, 30, 50);
			ofDrawRectangle(formStartX, formY, totalBarW, formHeight);
			ofSetColor(150, 150, 255);
			ofDrawRectangle(formStartX, formY, totalBarW * (rem / 4.0f), formHeight);
			drawStatText(uiFont, "Ghost: " + ofToString(rem) + "/4", formStartX, formY, totalBarW, formHeight, ofColor::black);

			// Tooltip
			if (ofRectangle(formStartX, formY, totalBarW, formHeight).inside(ofGetMouseX(), ofGetMouseY())) {
				isShowingTooltip = true;
				tooltipPos = { (float)ofGetMouseX(), (float)ofGetMouseY() };
				tooltipText = "Ghost Form: Immune to Physical/Piercing";
			}
		}
	}
}
//--------------------------------------------------------------
void ofApp::drawMinionManagerUI() {
	if (activeMinionUIs.empty()) return;

	float scale = getUIScaleFromHeight(ofGetHeight());
	float sfX = (float)ofGetViewportWidth() / ofGetWidth();
	float sfY = (float)ofGetViewportHeight() / ofGetHeight();

	for (size_t i = 0; i < activeMinionUIs.size(); i++) {
		auto & ui = activeMinionUIs[i];
		Player & minion = players[ui.playerIndex];

		bool isLeft = ui.bounds.x < ofGetWidth() / 2.0f;
		float topY = isLeft ? p0_minionTop : p1_minionTop;
		float viewH = isLeft ? p0_minionViewH : p1_minionViewH;

		// Skip if completely out of view bounds vertically
		if (ui.bounds.getBottom() < topY || ui.bounds.y > topY + viewH) continue;

		// Setup Scissor clipping to hide overflowing elements
		glEnable(GL_SCISSOR_TEST);
		int scX = (int)((isLeft ? p0_minionLeft - 40 : p1_minionLeft - 40) * sfX);
		int scW = (int)((minionPanelW + 80) * sfX);

		// Add a safe bleed padding for the 3px stroke so it doesn't get sliced
		int bleed = (int)(4.0f * scale * sfY);
		int scY = (int)((ofGetHeight() - (topY + viewH)) * sfY) - bleed;
		int scH = (int)(viewH * sfY) + (bleed * 2);

		glScissor(scX, scY, scW, scH);

		// --- Draw UI Panel ---
		ofPushStyle();
		ofEnableAlphaBlending();
		ofSetColor(0, 0, 0, 150);
		ofDrawRectRounded(ui.bounds, 10 * scale);
		ofPopStyle();

		// New Visual Outlines for Active and Hovered states
		bool isActive = (currentPlayerIndex == ui.playerIndex);
		bool isHovered = (hoveredUnitIndex == ui.playerIndex);

		if (isActive) {
			ofColor outlineColor = players[ui.playerIndex].isMinion ? ofColor::yellow : ofColor::white;
			ofPath p;
			p.rectRounded(ui.bounds, 10 * scale);
			p.setFilled(false);
			p.setStrokeWidth(3 * scale);
			p.setStrokeColor(outlineColor);
			p.draw();
		}

		if (isHovered && !isActive) {
			ofPath p;
			p.rectRounded(ui.bounds, 10 * scale);
			p.setFilled(false);
			p.setStrokeWidth(3 * scale);
			p.setStrokeColor(ofColor::white);
			p.draw();
		}

		// --- DETERMINE NAME ---
		string name = "";
		if (minion.isGolem) {
			if (minion.minionTexture == &golemTexElectric)
				name = "Electric Golem ";
			else if (minion.minionTexture == &golemTexFire)
				name = "Fire Golem ";
			else if (minion.minionTexture == &golemTexRock)
				name = "Rock Golem ";
			else
				name = "Golem ";
		} else if (minion.isWolf) {
			name = "Wolf ";
		} else if (minion.isHellhound) {
			name = "Hellhound ";
		} else if (minion.isDemon) {
			name = "Demon ";
		} else if (minion.isKoboldKing) {
			name = "Kobold King ";
		} else if (minion.isKobold) {
			name = "Kobold ";
		} else if (minion.isWallUnit) {
			if (minion.isMagicWallUnit)
				name = "Magic Wall ";
			else
				name = "Wall ";
		} else if (minion.isAssistant) {
			name = "Assistant ";
		} else if (minion.isFaerie) {
			name = "Faerie ";
		} else {
			name = "Skeleton ";
		}
		name += ofToString(ui.displayNumber);

		// --- Draw Name Text ---
		constexpr float kMinionUINameScale = 1.35f;
		float fontScale = kMinionUINameScale;
		float textBlockY = ui.bounds.y + 5 * scale;

		// --- Draw Icons (mirror per side) ---
		const UILayoutSpacing layoutSpacing = buildUILayoutSpacing(scale, turnTimerEnabled);
		float iconMargin = layoutSpacing.minionIconGap;
		constexpr float kMinionUIIconHeightPct = 0.80f;
		float iconHeight = ui.bounds.height * kMinionUIIconHeightPct;
		float cardAspectRatio = cardBackImage.getWidth() / cardBackImage.getHeight();
		float iconWidth = iconHeight * cardAspectRatio;
		float iconsY = ui.bounds.y + (ui.bounds.height - iconHeight) * 0.5f;

		if (isLeft) {
			ui.discardRect.set(ui.bounds.getRight() - (iconWidth + iconMargin), iconsY, iconWidth, iconHeight);
			ui.deckRect.set(ui.bounds.getRight() - (iconWidth * 2 + iconMargin * 2), iconsY, iconWidth, iconHeight);
		} else {
			ui.discardRect.set(ui.bounds.x + iconMargin, iconsY, iconWidth, iconHeight);
			ui.deckRect.set(ui.discardRect.getRight() + iconMargin, iconsY, iconWidth, iconHeight);
		}

		float contentLeftX = isLeft ? (ui.bounds.x + 10 * scale) : (ui.deckRect.getRight() + 16 * scale);
		float contentRightX = isLeft ? (ui.deckRect.x - 15 * scale) : (ui.bounds.getRight() - 15 * scale);
		ofRectangle nameBounds = uiFont.getStringBoundingBox(name, 0, 0);

		ofPushMatrix();
		if (isLeft)
			ofTranslate(contentLeftX, textBlockY + nameBounds.height * fontScale);
		else
			ofTranslate(contentRightX - nameBounds.width * fontScale, textBlockY + nameBounds.height * fontScale);
		ofScale(fontScale, fontScale);
		ofSetColor(ofColor::white);
		uiFont.drawString(name, 0, 0);
		ofPopMatrix();

		// --- Compute Model Positioning ---
		float modelSafetyPad = 10.0f * scale;
		float statusBlockHeight = (nameBounds.height * fontScale) + (24.0f * scale);
		if (minion.inTortoiseForm) statusBlockHeight += (17.0f * scale) + (2.0f * scale);
		if (minion.inGhostForm) statusBlockHeight += (17.0f * scale) + (2.0f * scale);
		float modelTopY = textBlockY + statusBlockHeight + (6.0f * scale);
		float statsTopY = textBlockY;
		float modelAreaHeight = std::max(28.0f * scale, ui.bounds.getBottom() - modelTopY - modelSafetyPad);
		float availableModelWidth = std::max(48.0f, contentRightX - contentLeftX - (2.0f * modelSafetyPad));
		float modelW = std::min(modelAreaHeight, availableModelWidth);
		float modelX = contentLeftX + ((contentRightX - contentLeftX) - modelW) * 0.5f;
		float maxModelTop = ui.bounds.getBottom() - modelSafetyPad - modelW;
		float modelY = std::clamp(modelTopY, ui.bounds.y + modelSafetyPad, maxModelTop);
		ui.modelViewport.set(modelX, modelY, modelW, modelW);

		// =========================================================
		// --- RENDER 3D MODEL DIRECTLY OVER UI ---
		// =========================================================
		ofEnableDepthTest();
		glClear(GL_DEPTH_BUFFER_BIT); // Clear depth buffer so model draws perfectly over 2D UI
		ofDisableLighting();
		uiLight.disable();

		ofColor unitTint = ofColor::white;
		int effectiveOwner = minion.isMinion ? minion.ownerID : minion.playerID;
		if (effectiveOwner == 0)
			unitTint = ofColor(255, 60, 60);
		else if (effectiveOwner == 1)
			unitTint = ofColor(60, 255, 60);

		ofSetColor(255);

		ofPushMatrix();
		// Position natively inside the computed viewport rect
		ofTranslate(modelX + modelW / 2.0f, modelY + modelW * 0.85f);
		float uScale = (modelW / 512.0f) * 90.0f * 0.02f; // Scale relative to viewport

		// Apply Z-flip FIRST to invert the 3D space, then tilt and spin
		ofScale(uScale, uScale, uScale);
		ofRotateZDeg(180);
		ofRotateXDeg(15);
		ofRotateYDeg(180 + ofGetElapsedTimef() * -30);
		ofRotateZDeg(180); // Flip model upright for 2D UI coordinates

		glDisable(GL_CULL_FACE);
		glEnable(GL_NORMALIZE);

		ofxAssimpModelLoader * currentModel = &playerModel;
		if (minion.inTortoiseForm)
			currentModel = &tortoiseModel;
		else if (minion.inGhostForm)
			currentModel = &ghostModel;
		else if (minion.isSkeleton)
			currentModel = &skeletonModel;
		else if (minion.isGolem)
			currentModel = &golemModel;
		else if (minion.isWolf)
			currentModel = &wolfModel;
		else if (minion.isHellhound)
			currentModel = &hellhoundModel;
		else if (minion.isDemon)
			currentModel = &demonModel;
		else if (minion.isKobold)
			currentModel = &koboldModel;
		else if (minion.isKoboldKing)
			currentModel = &koboldKingModel;
		else if (minion.isFaerie)
			currentModel = &faerieModel;
		else if (minion.isWallUnit)
			currentModel = &wallUnitModel;
		else if (minion.isAssistant)
			currentModel = &assistantModel;

		if (minion.inGhostForm) {
			ofEnableBlendMode(OF_BLENDMODE_ALPHA);
			ofSetColor(unitTint.r, unitTint.g, unitTint.b, 150);
			ofPushMatrix();
			ofMultMatrix(currentModel->getModelMatrix());
			for (unsigned int mi = 0; mi < currentModel->getMeshCount(); ++mi) {
				ofPushMatrix();
				ofMultMatrix(currentModel->getMeshHelper(mi).matrix);
				currentModel->getMeshHelper(mi).cachedMesh.drawFaces();
				ofPopMatrix();
			}
			ofPopMatrix();
			ofDisableBlendMode();
			ofSetColor(255);
		} else {
			if (pbrShaderLoaded && enableShaders) {
				glm::mat4 modelMat = ofGetCurrentMatrix(OF_MATRIX_MODELVIEW);
				glm::mat4 baseModelMat = modelMat * glm::mat4(currentModel->getModelMatrix());
				glm::mat4 viewMat = glm::mat4(1.0f);
				glm::mat4 projMat = ofGetCurrentMatrix(OF_MATRIX_PROJECTION);
				glm::mat4 viewProj = projMat * viewMat;

				pbrShader.begin();
				pbrShader.setUniform4f("uTintColor", unitTint.r / 255.0f, unitTint.g / 255.0f, unitTint.b / 255.0f, 1.0f);
				pbrShader.setUniformMatrix4f("uViewProj", viewProj);
				pbrShader.setUniformMatrix4f("uLightVP", viewProj);
				pbrShader.setUniform3f("lightDir", -0.4f, -1.0f, -0.6f);
				pbrShader.setUniform3f("lightColor", 1.0f, 1.0f, 1.0f);
				pbrShader.setUniform3f("uViewPos", 0.0f, 0.0f, 0.0f);
				pbrShader.setUniform1i("useNormalTex", 0);

				for (unsigned int mi = 0; mi < currentModel->getMeshCount(); ++mi) {
					glm::mat4 meshMat = glm::mat4(currentModel->getMeshHelper(mi).matrix);
					glm::mat4 finalModelMat = baseModelMat * meshMat;
					pbrShader.setUniformMatrix4f("uModel", finalModelMat);

					glm::mat4 normalMat = glm::transpose(glm::inverse(viewMat * finalModelMat));
					pbrShader.setUniformMatrix4f("uNormalMatrix", normalMat);

					if (minion.isGolem && minion.minionTexture && minion.minionTexture->isAllocated()) {
						pbrShader.setUniformTexture("albedoTex", *minion.minionTexture, 0);
						pbrShader.setUniform1i("useAlbedoTex", 1);
					} else if (currentModel->getMeshHelper(mi).hasTexture()) {
						pbrShader.setUniformTexture("albedoTex", currentModel->getMeshHelper(mi).getTextureRef(), 0);
						pbrShader.setUniform1i("useAlbedoTex", 1);
					} else {
						pbrShader.setUniform1i("useAlbedoTex", 0);
					}
					currentModel->getMeshHelper(mi).cachedMesh.drawFaces();
				}
				pbrShader.end();
			} else {
				ofPushMatrix();
				ofMultMatrix(currentModel->getModelMatrix());
				for (unsigned int mi = 0; mi < currentModel->getMeshCount(); ++mi) {
					ofPushMatrix();
					ofMultMatrix(currentModel->getMeshHelper(mi).matrix);
					bool hasTex = false;
					if (minion.isGolem && minion.minionTexture && minion.minionTexture->isAllocated()) {
						minion.minionTexture->bind();
						hasTex = true;
					} else if (currentModel->getMeshHelper(mi).hasTexture()) {
						currentModel->getMeshHelper(mi).getTextureRef().bind();
						hasTex = true;
					} else {
						glBindTexture(GL_TEXTURE_2D, 0);
					}
					currentModel->getMeshHelper(mi).cachedMesh.drawFaces();
					if (hasTex) {
						if (minion.isGolem && minion.minionTexture)
							minion.minionTexture->unbind();
						else
							currentModel->getMeshHelper(mi).getTextureRef().unbind();
					}
					ofPopMatrix();
				}
				ofPopMatrix();
			}

			if (minion.isMagicWallUnit) {
				float pulseAlpha = 90.0f + 60.0f * sin(ofGetElapsedTimef() * 2.0f);
				int alpha = static_cast<int>(ofClamp(pulseAlpha, 0.0f, 255.0f));
				ofEnableBlendMode(OF_BLENDMODE_ADD);
				ofSetColor(148, 0, 211, alpha);
				glEnable(GL_POLYGON_OFFSET_FILL);
				glPolygonOffset(-1.0f, -1.0f);
				ofPushMatrix();
				ofMultMatrix(currentModel->getModelMatrix());
				for (unsigned int mi = 0; mi < currentModel->getMeshCount(); ++mi) {
					ofPushMatrix();
					ofMultMatrix(currentModel->getMeshHelper(mi).matrix);
					currentModel->getMeshHelper(mi).cachedMesh.drawFaces();
					ofPopMatrix();
				}
				ofPopMatrix();
				glDisable(GL_POLYGON_OFFSET_FILL);
				ofSetColor(unitTint);
				ofEnableAlphaBlending();
			}
		}

		glDisable(GL_NORMALIZE);
		ofPopMatrix();

		// Clean up 3D State so UI rendering can resume
		ofDisableDepthTest();
		ofSetColor(255, 255, 255, 255);
		glDisable(GL_COLOR_MATERIAL);
		glDisable(GL_LIGHTING);
		float defaultAmbient[] = { 0.2f, 0.2f, 0.2f, 1.0f };
		float defaultDiffuse[] = { 0.8f, 0.8f, 0.8f, 1.0f };
		glMaterialfv(GL_FRONT_AND_BACK, GL_AMBIENT, defaultAmbient);
		glMaterialfv(GL_FRONT_AND_BACK, GL_DIFFUSE, defaultDiffuse);

		// =========================================================
		// --- RESUME 2D UI RENDERING ---
		// =========================================================

		// --- Status Bars ---
		float availableWidth = std::max(24.0f * scale, contentRightX - contentLeftX);
		float iconGap = ui.discardRect.x - (ui.deckRect.x + ui.deckRect.width);
		if (iconGap < 0.0f) iconGap = (ui.deckRect.x - (ui.discardRect.x + ui.discardRect.width));
		float preferredHpWidth = ui.deckRect.width + ui.discardRect.width + std::abs(iconGap);
		float statusTextY = statsTopY;
		drawMinionStatusBars(minion, name, contentLeftX, statusTextY, availableWidth, preferredHpWidth, !isLeft);

		// Deck
		ofSetColor(255);
		if (!minion.deck.empty()) {
			cardBackImage.draw(ui.deckRect);
		} else {
			ofSetColor(20, 20, 20, 200);
			ofDrawRectRounded(ui.deckRect, 3);
		}
		if (ui.playerIndex == currentPlayerIndex && !players[ui.playerIndex].hasDrawnThisTurn) {
			ofPushStyle();
			ofNoFill();
			ofSetColor(ofColor::yellow);
			ofSetLineWidth(3 * scale);
			ofDrawRectRounded(ui.deckRect, 5);
			ofPopStyle();
		}

		// Discard
		if (!minion.discardPile.empty()) {
			drawCardFaceDynamic(cardSpriteSheet, cardEffectFont, titleFont, minion.discardPile.back(), ui.discardRect.x, ui.discardRect.y, ui.discardRect.width, ui.discardRect.height, &minion);
		} else {
			ofSetColor(20, 20, 20, 200);
			ofDrawRectRounded(ui.discardRect, 3);
		}

		glDisable(GL_SCISSOR_TEST);
	} // End of loop

	// Draw list scrollbars when minion content exceeds visible height.
	{
		float barW = 8.0f * scale;
		float inset = 3.0f * scale;

		if (p0_minionTotalH > p0_minionViewH && p0_minionViewH > 1.0f) {
			float maxScroll = std::max(0.0f, p0_minionTotalH - p0_minionViewH);
			float thumbH = p0_minionViewH * (p0_minionViewH / p0_minionTotalH);
			thumbH = std::max(28.0f * scale, thumbH);
			float thumbY = p0_minionTop;
			if (maxScroll > 0.0f) {
				thumbY += (p0_minionScroll / maxScroll) * (p0_minionViewH - thumbH);
			}
			float barX = p0_minionLeft + minionPanelW - barW - inset; // board-facing edge for left panel

			ofSetColor(255, 255, 255, 35);
			ofDrawRectRounded(barX, p0_minionTop + inset, barW, p0_minionViewH - 2.0f * inset, 4.0f * scale);
			ofSetColor(255, 255, 255, 170);
			ofDrawRectRounded(barX, thumbY, barW, thumbH, 4.0f * scale);
		}

		if (p1_minionTotalH > p1_minionViewH && p1_minionViewH > 1.0f) {
			float maxScroll = std::max(0.0f, p1_minionTotalH - p1_minionViewH);
			float thumbH = p1_minionViewH * (p1_minionViewH / p1_minionTotalH);
			thumbH = std::max(28.0f * scale, thumbH);
			float thumbY = p1_minionTop;
			if (maxScroll > 0.0f) {
				thumbY += (p1_minionScroll / maxScroll) * (p1_minionViewH - thumbH);
			}
			float barX = p1_minionLeft + inset; // board-facing edge for right panel

			ofSetColor(255, 255, 255, 35);
			ofDrawRectRounded(barX, p1_minionTop + inset, barW, p1_minionViewH - 2.0f * inset, 4.0f * scale);
			ofSetColor(255, 255, 255, 170);
			ofDrawRectRounded(barX, thumbY, barW, thumbH, 4.0f * scale);
		}
	}
}
//--------------------------------------------------------------
void ofApp::cancelMagicHand() {
	updateCardInteractionState(CARD_INTERACTION_STATE_IDLE, -1, CARD_NONE);
	interactingCardIndex = -1;
}

// resolveMagicHandPull and resolveMagicHandPush have been inlined at their call sites
// in CARD_GIANT_MAGIC_HAND handling. Legacy helpers removed.
//--------------------------------------------------------------
void ofApp::generateDraftOptions(int classTier, const std::vector<int> * forcedIndices) {
	ofLogNotice("Draft") << "generateDraftOptions called: classTier=" << classTier << " draftPlayerIndex=" << draftPlayerIndex << " draftStage=" << draftStage << " draftGenerationCounter=" << draftGenerationCounter;
	int previousDraftPlayer = lastDraftOptionsPlayer;
	draftAcceptLocked = false;
	draftAcceptApplied = false;

	draftAcceptLocked = false;
	draftAcceptApplied = false;

	draftOptions.clear();
	currentDraftClassTier = classTier;
	currentDraftOptionPoolIndices = { -1, -1, -1 };

	// Guard: if we're already actively drafting the same class tier for the
	// same player and options are present, avoid regenerating (prevents
	// accidental re-entry/oscillation between players when visuals overlap).
	if (currentState == STATE_DRAFTING && !draftOptions.empty() && currentDraftClassTier == classTier && lastDraftOptionsPlayer == draftPlayerIndex) {
		ofLogNotice("Draft") << "generateDraftOptions: already drafting class " << classTier << " for player " << draftPlayerIndex << " - skipping regen.";
		return;
	}
	const std::vector<Card> * pool = &class1Cards;
	if (classTier == 2) pool = &class2Cards;
	if (classTier == 3) pool = &class3Cards;

	if (pool->empty()) return;

	std::vector<int> indices(pool->size());
	std::iota(indices.begin(), indices.end(), 0);

	if (forcedIndices && !forcedIndices->empty()) {
		int slot = 0;
		for (int idx : *forcedIndices) {
			if (idx >= 0 && idx < (int)pool->size()) {
				draftOptions.push_back((*pool)[idx]);
				if (slot < 3) currentDraftOptionPoolIndices[slot] = idx;
				slot++;
			}
		}
	} else {
		draftGenerationCounter++;
		uint32_t derivedSeed = currentMapSeed;
		derivedSeed ^= (uint32_t)classTier * 2654435761u;
		derivedSeed ^= ((uint32_t)draftPlayerIndex << 16);
		derivedSeed ^= ((uint32_t)draftStage << 24);
		derivedSeed ^= draftGenerationCounter * 1103515245u;

		std::mt19937 draftRng(derivedSeed);
		robust_deterministic_shuffle(indices, draftRng);

		for (int i = 0; i < 3 && i < (int)indices.size(); ++i) {
			draftOptions.push_back((*pool)[indices[i]]);
			currentDraftOptionPoolIndices[i] = indices[i];
		}
	}

	// Diagnostic log: report which pool indices and card names were generated
	{
		std::string idxs = "";
		std::string names = "";
		for (size_t i = 0; i < currentDraftOptionPoolIndices.size(); ++i) {
			if (i) idxs += ", ";
			idxs += std::to_string(currentDraftOptionPoolIndices[i]);
		}
		for (size_t i = 0; i < draftOptions.size(); ++i) {
			if (i) names += ", ";
			names += draftOptions[i].name;
		}
		ofLogNotice("Draft") << "generateDraftOptions: class=" << classTier << " chosenPoolIdx=[" << idxs << "] names=[" << names << "]";
		if (isMultiplayer) {
			writeLockstepTrace(steamManager.isHost(), globalTurnCounter, "GENERATE_DRAFT_OPTIONS: Class=" + std::to_string(classTier) + " PoolIdx=[" + idxs + "] Cards=[" + names + "]");
		}
	}

	if (classTier == 1)
		draftPicksRemaining = 2;
	else
		draftPicksRemaining = 1;

	selectedDraftIndices.clear();
	currentState = STATE_DRAFTING;
	if (!isInGameDraft) { // Only reset timer for regular drafts, not in-game drafts
		// For initial draft, only reset timer when starting Class 1 (stage 0)
		// When advancing from stage 0 to stage 1, preserve the shared timer
		bool isTransitioningStage0To1 = (previousDraftPlayer == draftPlayerIndex && draftStage == 1 && classTier == 2);
		if (!isTransitioningStage0To1) {
			resetDraftPhaseTimerWindow();
		}
	}
	waitingForDraftOptionsStartTime = 0.0f; // Client no longer waits

	// Initialize per-option visual animation state
	draftOptionUI.clear();
	draftOptionUI.resize(draftOptions.size());
	for (size_t ai = 0; ai < draftOptionUI.size(); ++ai) {
		draftOptionUI[ai].startScale = 0.0f; // start fully shrunk
		draftOptionUI[ai].currentScale = draftOptionUI[ai].startScale;
		draftOptionUI[ai].targetScale = 1.0f;
		draftOptionUI[ai].startFrame = (int)simulationFrame;
		draftOptionUI[ai].state = DRAFT_ANIM_APPEARING;
		draftOptionUI[ai].hidden = false;
	}

	// Remember which player these options belong to
	lastDraftOptionsPlayer = draftPlayerIndex;
	// Separate draft timers per drafting player.

	// Initialize Accept button animation to match cards (frame-based)
	draftAcceptUI.startScale = 0.0f;
	draftAcceptUI.currentScale = draftAcceptUI.startScale;
	draftAcceptUI.targetScale = 1.0f;
	draftAcceptUI.startFrame = (int)simulationFrame;
	draftAcceptUI.state = DRAFT_ANIM_APPEARING;
	draftAcceptUI.hidden = false;

	// Host no longer needs to send PKT_DRAFT_OPTIONS / PKT_DRAFT_STATE
	// because both peers deterministically generate the same options
	// using `generateDraftOptions()` and the shared `currentMapSeed`.
}

// Apply authoritative option indices sent by host (clients call this when receiving DraftOptionsPacket)
void ofApp::applyDraftOptionsFromPool(int classTier, const std::vector<int> & indices, int picksRemaining, int draftingPlayerIdx) {
	int previousDraftPlayer = draftPlayerIndex;
	draftOptions.clear();
	currentDraftClassTier = classTier;
	// --- FIX: Correct vector initialization syntax ---
	currentDraftOptionPoolIndices = { -1, -1, -1 };
	const std::vector<Card> * pool = &class1Cards;
	if (classTier == 2) pool = &class2Cards;
	if (classTier == 3) pool = &class3Cards;

	// --- FIX: Logic Safety Check ---
	if (pool->empty()) {
		ofLogError("Draft") << "CRITICAL: Card pool for Class " << classTier << " is empty on Client! Check cards.json.";
		return; // Avoid crashing or applying invalid indices
	}

	// If we've already completed the initial draft and are in gameplay (and
	// this isn't an in-game draft), ignore late DraftOptions so we don't
	// re-enter drafting on the client. However, if the packet carries a
	// non-zero classTier, it represents a new drafting phase (e.g. Class 2
	// or an in-game key draft) and must be applied.
	if (initialDraftComplete && currentState == STATE_GAMEPLAY && !isInGameDraft && classTier == 0) {
		ofLogNotice("Draft") << "applyDraftOptionsFromPool: ignoring late DraftOptions (gameplay active, no tier).";
		return;
	}

	int slot = 0;
	for (int idx : indices) {
		if (idx >= 0 && idx < (int)pool->size()) {
			draftOptions.push_back((*pool)[idx]);
			if (slot < 3) currentDraftOptionPoolIndices[slot] = idx;
			slot++;
		}
	}

	// --- FIX: Authoritatively apply ALL state from the packet ---
	draftPicksRemaining = picksRemaining;
	draftPlayerIndex = draftingPlayerIdx;
	lastDraftOptionsPlayer = draftingPlayerIdx;
	const bool isFirstInitialDraftReveal = (!initialDraftComplete && classTier == 1 && draftStage == 0);
	if (turnTimerEnabled && (previousDraftPlayer != draftingPlayerIdx || isFirstInitialDraftReveal)) {
		if (!isInGameDraft) { // Only reset timer for regular drafts, not in-game drafts
			turnStartFrame = (int)simulationFrame;
		}
	}
	selectedDraftIndices.clear();
	currentState = STATE_DRAFTING; // Force state transition
	if (!isInGameDraft) { // Only reset timer for regular drafts, not in-game drafts
		resetDraftPhaseTimerWindow();
	}
	waitingForDraftOptionsStartTime = 0.0f; // We have the options now
	draftAcceptLocked = false;
	draftAcceptApplied = false;
	// -------------------------------------------------------------

	// Log applied options for debugging (helps determine whether Windows client actually applied options)
	if ((int)draftOptions.size() != lastLoggedDraftOptionsCount) {
		lastLoggedDraftOptionsCount = (int)draftOptions.size();
		std::string names = "";
		for (size_t i = 0; i < draftOptions.size(); ++i) {
			if (i) names += ", ";
			names += draftOptions[i].name;
		}
		ofLogNotice("Draft") << "applyDraftOptionsFromPool: applied " << draftOptions.size() << " options for player=" << draftPlayerIndex << " stage=" << draftStage << " names=" << names;
	}
}

void ofApp::onCardPicked(int optionIndex) {
	if (optionIndex < 0 || optionIndex >= (int)draftOptions.size()) return;

	// Diagnostic: log which actor index is being used for this pick
	if (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) {
		ofLogNotice("Draft") << "onCardPicked: draftPlayerIndex=" << draftPlayerIndex
							 << " isMinion=" << players[draftPlayerIndex].isMinion
							 << " ownerID=" << players[draftPlayerIndex].ownerID
							 << " playerID=" << players[draftPlayerIndex].playerID
							 << " deckSize=" << players[draftPlayerIndex].deck.size();
	} else {
		ofLogNotice("Draft") << "onCardPicked: draftPlayerIndex=" << draftPlayerIndex << " (out of range)";
	}

	Player & p = players[draftPlayerIndex];
	Card picked = draftOptions[optionIndex];

	// IN-GAME DRAFT LOGIC
	if (isInGameDraft) {
		// Keep game logic immediate (card is added and deck shuffled),
		// but also spawn the picked-card visual move so the player sees the card fly into the deck.
		p.deck.push_back(picked);

		// Check if this pick belongs to a minion actor
		bool targetIsMinion = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size() && players[draftPlayerIndex].isMinion);

		// Shuffle deck to include new card (host-authoritative will also send PKT_SHUFFLE)
		shuffleGameVector(p.deck, draftPlayerIndex);

		// Create visual move using the same layout math as drawDraftScreen so startPos matches the slot.
		float cardW, cardH, spacing, startX, startY;
		getDraftCardMetrics(false, cardW, cardH, spacing, startX, startY);
		// Compute slot center for the picked optionIndex
		int i = optionIndex;
		if (i < 0) i = 0;
		float cx = startX + static_cast<float>(i) * (cardW + spacing);
		glm::vec2 center(cx + cardW / 2.0f, startY + cardH / 2.0f);

		DraftPickedMove mv;
		mv.card = picked;
		mv.startFrame = (int)simulationFrame;
		mv.delayFrames = draftAnimHoldFrames;
		mv.durationFrames = (int)(0.35f * (float)turnTimerFramesPerSecond + 0.5f);
		mv.startPos = center;
		mv.endScale = 1.0f; // Default to full size

		// Determine end position and prepare shuffle animation timing
		float shuffleAnimStartDelay = 0.0f; // When to start the shuffle animation

		// If the drafting actor is a minion, target its MinionUI deck rect
		if (targetIsMinion) {
			bool found = false;
			for (const auto & mui : activeMinionUIs) {
				if (mui.playerIndex == draftPlayerIndex) {
					mv.endPos = glm::vec2(mui.deckRect.x + mui.deckRect.width / 2.0f, mui.deckRect.y + mui.deckRect.height / 2.0f);
					// Scale down to fit minion UI deck
					float uiScale = std::min(ofGetWidth() / 1920.0f, getUIScaleFromHeight(ofGetHeight()));
					float cardW = kCardPixelWidth * uiScale;
					float cardH = kCardPixelHeight * uiScale;
					mv.endScale = std::min(mui.deckRect.width, mui.deckRect.height) / std::max(cardW, cardH);
					found = true;
					break;
				}
			}
			if (!found) {
				mv.endPos = glm::vec2(-100, -100);
			}
			mv.finished = false;
			// mark ownerIndex as the minion actor so we can avoid flashing main decks
			mv.ownerIndex = draftPlayerIndex;

			// Schedule shuffle animation to start after card animation completes (seconds)
			shuffleAnimStartDelay = ((float)mv.delayFrames / (float)turnTimerFramesPerSecond) + ((float)mv.durationFrames / (float)turnTimerFramesPerSecond);
		} else if (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) {
			int ownerID = players[draftPlayerIndex].playerID;
			ofRectangle deckRect = (ownerID == myLocalPlayerID) ? p0_deckRect : p1_deckRect;
			if (!isMultiplayer) deckRect = (ownerID == 0) ? p0_deckRect : p1_deckRect;
			mv.endPos = glm::vec2(deckRect.x + deckRect.width / 2.0f, deckRect.y + deckRect.height / 2.0f);
			// Scale down to fit player deck
			float uiScale = std::min(ofGetWidth() / 1920.0f, getUIScaleFromHeight(ofGetHeight()));
			float cardW = kCardPixelWidth * uiScale;
			float cardH = kCardPixelHeight * uiScale;
			mv.endScale = std::min(deckRect.width, deckRect.height) / std::max(cardW, cardH);
			mv.finished = false;
			mv.ownerIndex = draftPlayerIndex;
		} else {
			mv.endPos = glm::vec2(-100, -100);
			mv.finished = false;
			mv.ownerIndex = draftPlayerIndex;
		}
		scheduleDraftPickedMove(mv);

		// Create shuffle animation for minion, scheduled to start after card animation
		if (targetIsMinion) {
			ShuffleAnimation s;
			s.playerIndex = draftPlayerIndex;
			bool assignedRect = false;
			for (const auto & mui : activeMinionUIs) {
				if (mui.playerIndex == draftPlayerIndex) {
					s.deckRect = mui.deckRect;
					assignedRect = true;
					break;
				}
			}
			if (!assignedRect) {
				int ownerSlot = findPlayerIndexByID(players[draftPlayerIndex].ownerID);
				int ownerID = (ownerSlot >= 0) ? players[ownerSlot].playerID : players[draftPlayerIndex].ownerID;
				if (isMultiplayer) {
					s.deckRect = (ownerID == myLocalPlayerID) ? p0_deckRect : p1_deckRect;
				} else {
					s.deckRect = (ownerID == 0) ? p0_deckRect : p1_deckRect;
				}
			}
			s.startTime = ofGetElapsedTimef() + shuffleAnimStartDelay;
			s.duration = 0.9f;
			s.currentAlpha = 255.0f;
			s.currentScale = 1.0f;
			s.rotation = 0.0f;
			activeShuffleAnimations.push_back(s);
		}
		// Return to game (only for in-game drafts)
		if (isInGameDraft) {
			currentState = STATE_GAMEPLAY;
			// Defer authoritative turn-start to the deterministic tick
			requestStartNewTurn();
			return;
		}
	}
	// Remove picked card from options so it can't be picked again this round
	draftOptions.erase(draftOptions.begin() + optionIndex);

	draftPicksRemaining--;

	if (draftPicksRemaining <= 0) {
		// Stage Complete
		draftStage++;
		// allow visuals to complete before showing next draft
		float delay = ((float)draftAnimHoldFrames / (float)turnTimerFramesPerSecond) + 0.35f + 0.9f + 0.1f;
		if (draftStage == 1) {
			// Move to Class 2
			scheduleGenerateDraftOptions(2, delay);
		} else {
			// Player Finished Drafting
			// Check if both players drafted
			// The logic: Winner goes first. If P1 went, check if P2 deck empty.
			int otherPlayer = (draftPlayerIndex + 1) % 2;
			if (players[otherPlayer].deck.empty()) {
				// Switch to other player
				draftPlayerIndex = otherPlayer;
				draftStage = 0;
				scheduleGenerateDraftOptions(1, delay);
			} else {
				// Both done! Start Game.

				// Defer final shuffling and transition until pick animations finish.
				// We'll perform shuffles when `networkPending.draftFinalize` resolves in `update()`.
				networkPending.draftFinalize = true;
				networkPending.draftShuffleNeeded = true;
				// Remember which player should start next when finalizing the draft
				// (keeps behavior consistent with the command-path which sets
				// `draftEndNextPlayerIndex` before scheduling a draft end).
				draftEndNextPlayerIndex = otherPlayer;
			}
		}
	}
}
//--------------------------------------------------------------
void ofApp::drawInitiativeRoll() {
	static int lastDrawFrame = -1;
	const int currentDrawFrame = ofGetFrameNum();
	if (lastDrawFrame == currentDrawFrame) return;
	lastDrawFrame = currentDrawFrame;

	if (activeDiceRolls.size() >= 2) {

		// Position labels so that the local player is always on the left
		glm::vec3 leftPos(-6.0f, 11.0f, 0.0f);
		glm::vec3 rightPos(6.0f, 11.0f, 0.0f);

		// Player 0 is die index 0, player 1 is die index 1
		bool player0OnLeft = (myLocalPlayerID == 0);
		glm::vec3 player0Pos = player0OnLeft ? leftPos : rightPos;
		glm::vec3 player1Pos = player0OnLeft ? rightPos : leftPos;

		glm::vec2 localScreen = getActiveCamera().worldToScreen((myLocalPlayerID == 0) ? player0Pos : player1Pos);
		glm::vec2 opponentScreen = getActiveCamera().worldToScreen((myLocalPlayerID == 0) ? player1Pos : player0Pos);

		// Standardized Text Drawer (Smaller scale)
		auto drawLabel = [&](string text, float x, float y, ofColor col) {
			float fontScale = 0.7f; // Smaller size
			drawPixelTextCentered(titleFont, text, x, y, fontScale, col, 1, ofColor(0, 0, 0, 255));
		};

		// Draw local player on left, opponent on right
		ofColor localPlayerColor = (myLocalPlayerID == 0) ? ofColor(70, 160, 255) : ofColor(255, 80, 80);
		ofColor opponentColor = (myLocalPlayerID == 0) ? ofColor(255, 80, 80) : ofColor(70, 160, 255);
		string localPlayerName = (myLocalPlayerID == 0) ? getPlayerSteamName(0) : getPlayerSteamName(1);
		string opponentPlayerName = (myLocalPlayerID == 0) ? getPlayerSteamName(1) : getPlayerSteamName(0);

		drawLabel(localPlayerName, localScreen.x, localScreen.y, localPlayerColor);
		drawLabel(opponentPlayerName, opponentScreen.x, opponentScreen.y, opponentColor);

		// Draw Result Message
		if (activeDiceRolls[0].isFinishedVisual && activeDiceRolls[1].isFinishedVisual) {
			string msg = "";

			if (activeDiceRolls[0].result > activeDiceRolls[1].result)
				msg = getPlayerSteamName(0) + " goes first.";
			else if (activeDiceRolls[1].result > activeDiceRolls[0].result)
				msg = getPlayerSteamName(1) + " goes first.";
			else
				msg = "Tie! Rerolling...";

			// Draw in Instruction Area (Top Center)
			ofRectangle mBox = titleFont.getStringBoundingBox(msg, 0, 0);
			float tx = (ofGetWidth() / 2.0f) - (mBox.width / 2.0f);

			// FIX: Push this text down slightly so it doesn't overlap the Dice result text!
			float ty = ofGetHeight() * 0.35f;

			ofSetColor(0, 0, 0, 255);
			titleFont.drawString(msg, tx + 2, ty + 2);
			ofSetColor(ofColor::gold);
			titleFont.drawString(msg, tx, ty);
		}
	}
}
//--------------------------------------------------------------
void ofApp::drawDraftScreen() {
	ofPushStyle();
	// Isolate UI drawing state so other render paths aren't affected.
	// Disable depth and lighting for 2D UI; enable alpha blend explicitly.
	ofDisableLighting();
	ofDisableDepthTest();
	ofEnableBlendMode(OF_BLENDMODE_ALPHA);
	ofSetColor(255, 255, 255, 255);
	// Dim the world behind draft cards (modal overlay)
	ofSetColor(0, 0, 0, 180);
	ofDrawRectangle(0, 0, ofGetWidth(), ofGetHeight());

	if (draftOptions.empty()) {
		ofPushStyle();
		ofEnableBlendMode(OF_BLENDMODE_ALPHA);
		ofSetColor(0, 0, 0, 180);
		float boxW = std::min(540.0f, ofGetWidth() * 0.72f);
		float boxH = 96.0f;
		float boxX = ofGetWidth() * 0.5f - boxW * 0.5f;
		float boxY = ofGetHeight() * 0.5f - boxH * 0.5f;
		ofDrawRectRounded(boxX, boxY, boxW, boxH, 12.0f);
		ofSetColor(ofColor::white);
		std::string msg = (waitingForDraftOptionsStartTime > 0.0f) ? "Waiting for draft options..." : "Preparing draft...";
		ofRectangle msgBox = titleFont.getStringBoundingBox(msg, 0, 0);
		float tx = std::round(ofGetWidth() * 0.5f - msgBox.width * 0.5f);
		float ty = std::round(ofGetHeight() * 0.5f);
		titleFont.drawString(msg, tx, ty);

		// Immediate diagnostic dump to help trace empty-draft root cause
		ofLogNotice("DraftDebug") << "drawDraftScreen: EMPTY overlay - state=" << currentState
								  << " draftPlayerIndex=" << draftPlayerIndex
								  << " draftStage=" << draftStage
								  << " currentDraftClassTier=" << currentDraftClassTier
								  << " lastDraftOptionsPlayer=" << lastDraftOptionsPlayer
								  << " isInGameDraft=" << (isInGameDraft ? 1 : 0)
								  << " waitingForDraftOptionsStartTime=" << waitingForDraftOptionsStartTime
								  << " draftGenerationCounter=" << draftGenerationCounter
								  << " class1Cards=" << class1Cards.size()
								  << " class2Cards=" << class2Cards.size()
								  << " class3Cards=" << class3Cards.size();
		ofDisableBlendMode();
		ofPopStyle();
		ofDisableBlendMode();
		ofPopStyle();
		return;
	}

	// 1. Construct Specific Instruction Text
	string pName = "";
	if (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) {
		if (isInGameDraft && players[draftPlayerIndex].isMinion) {
			pName = getPlayerDisplayName(draftPlayerIndex);
		} else {
			pName = getPlayerSteamName(draftPlayerIndex);
		}
	} else {
		pName = (draftPlayerIndex == 0) ? player0SteamName : player1SteamName;
	}
	string header = "";
	string instr = "";

	if (isInGameDraft) {
		header = pName + ": Key Found!";
		instr = "Choose 1 Card (Get 1 Copy)";
	} else {
		// Header shows which draft this is for the player whose draft it is.
		// If it's the local player's draft, display "Your first/second draft" instead of their Steam name.
		bool isMyTurnToDraft = isLocalDraftingPlayer(draftPlayerIndex);
		if (draftStage == 0) {
			header = isMyTurnToDraft ? "Your first draft" : (pName + "'s first draft");
			instr = isMyTurnToDraft ? "Choose 2 (Get 2 Copies)" : "Choosing 2 (Gets 2 Copies)";
		} else {
			header = isMyTurnToDraft ? "Your second draft" : (pName + "'s second draft");
			instr = isMyTurnToDraft ? "Choose 1 (Get 1 Copy)" : "Choosing 1 (Gets 1 Copy)";
		}
	}

	// Prepare UI scale and card sizing so header/instruction can be positioned
	// relative to the card area (we want header above cards and accept below).
	float cardW, cardH, spacing, startX, startY;
	getDraftCardMetrics(false, cardW, cardH, spacing, startX, startY);

	// 2. Header & instruction: snappy pop-in that scales and fades as cards appear
	// Continuous fractional frame keeps the draft UI smooth at 144Hz.
	float continuousFrame = (float)simulationFrame + (simulationAccumulator / SIMULATION_TIMESTEP);
	// Compute uiScale (kept in sync with getDraftCardMetrics)
	float uiScale = std::min(ofGetWidth() / 1920.0f, getUIScaleFromHeight(ofGetHeight()));
	uiScale = std::clamp(uiScale * settingsUIScale, 0.75f, 1.25f);
	float appearT = 0.0f;
	if (!draftOptionUI.empty()) {
		for (size_t ai = 0; ai < draftOptionUI.size(); ++ai) {
			float elapsedFrames = continuousFrame - (float)draftOptionUI[ai].startFrame;
			float t = (draftAnimAppearFrames > 0) ? (elapsedFrames / (float)draftAnimAppearFrames) : 1.0f;
			if (t > appearT) appearT = t;
		}
		appearT = std::clamp(appearT, 0.0f, 1.0f);
	}

	// Ease-out cubic for a snappy feel, add a small overshoot for pop
	float t = appearT;
	float easeOutCubic = 1.0f - powf(1.0f - t, 3);
	float scale = 0.8f + 0.28f * easeOutCubic; // starts smaller, overshoots to ~1.08
	float alpha = appearT;

	if (alpha > 0.001f && !draftAcceptApplied) {
		int shadowA = (int)(255.0f * alpha);
		int fgA = (int)(255.0f * alpha);

		// Determine class tier text
		std::string classTierText = "";
		ofColor classTierColor = ofColor::white;
		if (!isInGameDraft) {
			if (draftStage == 0) {
				classTierText = "Class 1";
				classTierColor = ofColor(205, 127, 50); // Bronze
			} else if (draftStage == 1) {
				classTierText = "Class 2";
				classTierColor = ofColor(192, 192, 192); // Silver
			}
		}

		// Calculate Y positions from the bottom up so they cannot overlap.
		float lineHeight = titleFont.getLineHeight() * scale;
		float textSpacing = 15.0f * uiScale;
		float currentY = startY - std::clamp(20.0f * uiScale, 15.0f, 40.0f) - lineHeight;

		// --- MINI DECISION TIMER FOR OPPONENT DRAFTS ---
		if (opponentDecisionTimerActive) {
			float elapsed = (float)((int)(simulationFrame - opponentDecisionStartFrame));
			float remaining = std::max(0.0f, (float)opponentDecisionDurationFrames - elapsed);
			float pct = (opponentDecisionDurationFrames > 0) ? (remaining / (float)opponentDecisionDurationFrames) : 0.0f;
			float barW = 240.0f * uiScale;
			float barH = 14.0f * uiScale;
			float barX = ofGetWidth() * 0.5f - barW * 0.5f;

			// Draw timer bar
			ofSetColor(20, 20, 30, 220 * g_menuAlphaMult);
			ofDrawRectRounded(barX - 4.0f, currentY - 4.0f, barW + 8.0f, barH + 8.0f, 6.0f);
			ofSetColor(60, 60, 70, 255 * g_menuAlphaMult);
			ofDrawRectRounded(barX, currentY, barW, barH, 4.0f);
			ofColor fillC = ofColor::fromHsb(120 * pct, 200, 220);
			ofSetColor(fillC.r, fillC.g, fillC.b, 255 * g_menuAlphaMult);
			ofDrawRectRounded(barX, currentY, barW * pct, barH, 4.0f);

			int secs = (int)std::ceil(remaining / turnTimerFramesPerSecond);
			std::string secsText = "Decision " + ofToString(secs) + "s";
			ofSetColor(255, 255, 255, 255 * g_menuAlphaMult);
			ofRectangle tb = uiFont.getStringBoundingBox(secsText, 0, 0);
			uiFont.drawString(secsText, barX + barW / 2.0f - tb.getWidth() / 2.0f, currentY - 6.0f);

			currentY -= (barH + textSpacing + 12.0f * uiScale); // shift text up
		}

		float classTy = 0.0f;
		if (!classTierText.empty()) {
			classTy = currentY;
			currentY -= (lineHeight + textSpacing);
		}

		float instrTy = currentY;
		currentY -= (lineHeight + textSpacing);

		float ty = currentY;

		ofRectangle headerBox = titleFont.getStringBoundingBox(header, 0, 0);
		float scaledW = headerBox.width * scale;
		float tx = (ofGetWidth() / 2.0f) - (scaledW / 2.0f);

		ofPushMatrix();
		ofTranslate(tx, ty);
		ofScale(scale, scale);
		ofSetColor(0, 0, 0, shadowA);
		// Shadow offset must be scaled back to pixel units
		titleFont.drawString(header, 2.0f / scale, 2.0f / scale);
		ofSetColor(ofColor(255, 255, 255, fgA));
		titleFont.drawString(header, 0, 0);
		ofPopMatrix();

		// Instruction line below header: place just above the cards with a small gap
		ofRectangle instrBox = titleFont.getStringBoundingBox(instr, 0, 0);
		float instrTx = (ofGetWidth() / 2.0f) - (instrBox.width * scale / 2.0f);
		ofPushMatrix();
		ofTranslate(instrTx, instrTy);
		ofScale(scale, scale);
		ofSetColor(0, 0, 0, shadowA);
		titleFont.drawString(instr, 2.0f / scale, 2.0f / scale);
		ofSetColor(ofColor(255, 255, 255, fgA));
		titleFont.drawString(instr, 0, 0);
		ofPopMatrix();

		if (!classTierText.empty()) {
			ofRectangle classBox = titleFont.getStringBoundingBox(classTierText, 0, 0);
			float classTx = (ofGetWidth() / 2.0f) - (classBox.width * scale / 2.0f);
			ofSetColor(0, 0, 0, shadowA);
			ofPushMatrix();
			ofTranslate(classTx, classTy);
			ofScale(scale, scale);
			titleFont.drawString(classTierText, 2.0f / scale, 2.0f / scale);
			ofSetColor(ofColor(classTierColor.r, classTierColor.g, classTierColor.b, fgA));
			titleFont.drawString(classTierText, 0, 0);
			ofPopMatrix();
		}
	}

	// 3. Draw Cards
	// Keep the same uiScale/cardW/cardH computed above (with draft size reduction)
	// Note: spacing/startX/startY are already provided by getDraftCardMetrics

	// Throttled debug: if we're in draft state but have no options, log mapping once per second
	float nowDbg = ofGetElapsedTimef();
	if (draftOptions.empty() && currentState == STATE_DRAFTING && (nowDbg - lastDraftDrawLogTime) > 1.0f) {
		lastDraftDrawLogTime = nowDbg;
		ofLogNotice("DraftDebug") << "drawDraftScreen: called but draftOptions.empty() currentState=" << currentState << " draftPlayerIndex=" << draftPlayerIndex << " localIdx=" << getLocalPlayerIndex() << " myLocalPlayerID=" << myLocalPlayerID << " waitingForDraftOptions=" << (waitingForDraftOptionsStartTime > 0.0f ? 1 : 0);
	}

	// Animate per-slot UI and draw scaled cards (frame-based)
	for (size_t i = 0; i < draftOptions.size(); ++i) {
		float x = startX + i * (cardW + spacing);
		ofRectangle cardRect(x, startY, cardW, cardH);

		// Update animation state for this slot
		if (i < draftOptionUI.size()) {
			auto & ui = draftOptionUI[i];
			float elapsedFrames = continuousFrame - (float)ui.startFrame;
			if (ui.state == DRAFT_ANIM_APPEARING) {
				float t = (draftAnimAppearFrames > 0) ? (elapsedFrames / (float)draftAnimAppearFrames) : 1.0f;
				t = std::clamp(t, 0.0f, 1.0f);
				t = t * t * (3.0f - 2.0f * t);
				if (t >= 1.0f) {
					ui.currentScale = ui.targetScale;
					ui.state = DRAFT_ANIM_IDLE;
				} else {
					ui.currentScale = ui.startScale + t * (ui.targetScale - ui.startScale);
				}
			} else if (ui.state == DRAFT_ANIM_VANISHING) {
				float t = (draftAnimVanishFrames > 0) ? (elapsedFrames / (float)draftAnimVanishFrames) : 1.0f;
				t = std::clamp(t, 0.0f, 1.0f);
				t = t * t * (3.0f - 2.0f * t);
				if (t >= 1.0f) {
					ui.currentScale = ui.targetScale;
					ui.hidden = true;
					ui.state = DRAFT_ANIM_IDLE;
				} else {
					ui.currentScale = ui.startScale + t * (ui.targetScale - ui.startScale);
				}
			}
		}

		// Compute scaled rect
		float scale = 1.0f;
		if (i < draftOptionUI.size()) scale = draftOptionUI[i].currentScale;
		float w = cardW * scale;
		float h = cardH * scale;
		float drawX = x + (cardW - w) / 2.0f;
		float drawY = startY + (cardH - h) / 2.0f;

		// Check Selection: compare against authoritative pool index for this slot
		int slotPoolIdx = (i < currentDraftOptionPoolIndices.size()) ? currentDraftOptionPoolIndices[i] : -1;
		bool isSelected = false;
		if (slotPoolIdx >= 0) {
			for (int sel : selectedDraftIndices) {
				if (sel == slotPoolIdx) {
					isSelected = true;
					break;
				}
			}
		}

		// Use solid fills rendered BEFORE the card graphic to ensure thick borders
		if (isSelected) {
			ofPushStyle();
			ofFill();
			// Reverse loop so largest polygons are drawn first behind the smaller ones
			for (int g = 6; g >= 1; --g) {
				ofSetColor(255, 255, 0, 90 - (g * 14));
				drawCardOutlineOutside(drawX, drawY, w, h, 0.0f, g * 2.0f + 2.0f);
			}
			ofSetColor(ofColor::yellow);
			drawCardOutlineOutside(drawX, drawY, w, h, 0.0f, 5.0f);
			ofPopStyle();
		}

		bool isLocallyHovered = (!draftAcceptApplied && (i >= draftOptionUI.size() || !draftOptionUI[i].hidden) && cardRect.inside(ofGetMouseX(), ofGetMouseY()));
		bool isOpponentHovered = (!isLocalDraftingPlayer(draftPlayerIndex) && static_cast<int>(opponentHoverType) == 5 && opponentHoverCardIndex == (int)i);

		if (isLocallyHovered || isOpponentHovered) {
			ofPushStyle();
			ofFill();
			for (int g = 5; g >= 1; --g) {
				ofSetColor(255, 255, 255, 60 - (g * 10));
				drawCardOutlineOutside(drawX, drawY, w, h, 0.0f, g * 2.0f + 1.0f);
			}
			ofSetColor(ofColor::white);
			drawCardOutlineOutside(drawX, drawY, w, h, 0.0f, 4.0f);
			ofPopStyle();
		}

		// Skip hidden slots
		if (i < draftOptionUI.size() && draftOptionUI[i].hidden) continue;

		// Draw Card Sprite scaled
		ofSetColor(255);

		Player * pPtr = nullptr;
		if (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) pPtr = &players[draftPlayerIndex];

		drawCardFaceDynamic(cardSpriteSheet, cardEffectFont, titleFont, draftOptions[i], drawX, drawY, w, h, pPtr);
	}

	// Throttled draw-time debug: log if we are drawing non-empty options but haven't logged recently
	float now = ofGetElapsedTimef();
	if (!draftOptions.empty() && (now - lastDraftDrawLogTime) > 1.0f) {
		lastDraftDrawLogTime = now;
		std::string names = "";
		for (size_t i = 0; i < draftOptions.size(); ++i) {
			if (i) names += ", ";
			names += draftOptions[i].name;
		}
		ofLogNotice("Draft") << "drawDraftScreen: drawing " << draftOptions.size() << " options (player=" << draftPlayerIndex << " stage=" << draftStage << ") names=" << names;
	}

	// 4. Draw Accept Button
	int required = 1;
	if (!isInGameDraft && draftStage == 0) required = 2;

	bool canAccept = ((int)selectedDraftIndices.size() == required);

	// Only show the Accept button to the drafting player (or in singleplayer)
	bool showAccept = true;
	if (isMultiplayer) {
		if (!players.empty() && !isLocalDraftingPlayer(draftPlayerIndex)) showAccept = false;
	}
	// Hide accept if we've already applied it locally (it should vanish)

	if (draftAcceptApplied) showAccept = false;

	if (showAccept && !draftOptions.empty()) {
		float btnW = std::clamp(220.0f * uiScale, 140.0f, 320.0f);
		float btnH = std::clamp(60.0f * uiScale, 40.0f, 96.0f);
		float btnX = (ofGetWidth() - btnW) / 2.0f;
		// Ensure a generous gap so the cards never touch the button
		float gapBelowCards = 40.0f * uiScale;
		float btnY = startY + cardH + gapBelowCards;

		// Allow the button to move much further down the screen
		float maxAllowedBtnY = ofGetHeight() - btnH - (20.0f * uiScale);
		if (btnY > maxAllowedBtnY) btnY = maxAllowedBtnY;

		// Animate Accept button with its UI state
		float acceptScale = 1.0f;
		float acceptAlpha = 1.0f;
		if (draftAcceptUI.state == DRAFT_ANIM_APPEARING) {
			float elapsedFrames = continuousFrame - (float)draftAcceptUI.startFrame;
			float at = (draftAnimAppearFrames > 0) ? (elapsedFrames / (float)draftAnimAppearFrames) : 1.0f;
			at = std::clamp(at, 0.0f, 1.0f);
			if (at >= 1.0f) {
				draftAcceptUI.currentScale = draftAcceptUI.targetScale;
				draftAcceptUI.state = DRAFT_ANIM_IDLE;
			} else {
				draftAcceptUI.currentScale = draftAcceptUI.startScale + at * (draftAcceptUI.targetScale - draftAcceptUI.startScale);
			}
		}
		if (draftAcceptUI.state == DRAFT_ANIM_VANISHING) {
			float elapsedFrames = continuousFrame - (float)draftAcceptUI.startFrame;
			float vt = (draftAnimVanishFrames > 0) ? (elapsedFrames / (float)draftAnimVanishFrames) : 1.0f;
			vt = std::clamp(vt, 0.0f, 1.0f);
			if (vt >= 1.0f) {
				draftAcceptUI.currentScale = draftAcceptUI.targetScale;
				draftAcceptUI.hidden = true;
				draftAcceptUI.state = DRAFT_ANIM_IDLE;
			} else {
				draftAcceptUI.currentScale = draftAcceptUI.startScale + vt * (draftAcceptUI.targetScale - draftAcceptUI.startScale);
			}
		}
		acceptScale = draftAcceptUI.currentScale;
		acceptAlpha = acceptScale; // simple alpha linked to scale for pop-in

		draftAcceptButtonRect.set(btnX, btnY, btnW, btnH);
		if (draftAcceptButtonRect.inside(ofGetMouseX(), ofGetMouseY()) && showAccept && canAccept) g_hoveredButtonId = "draft_accept";
		drawAcceptButtonShared(draftAcceptButtonRect, canAccept, acceptScale, acceptAlpha);
	} else {
		// Hide accept: clear the rect so hits are ignored
		draftAcceptButtonRect.set(0, 0, 0, 0);
	}

	if (isShowingPileView && currentPileViewPlayerIndex != -1) {
		drawPileViewFor(currentPileViewPlayerIndex, currentPileView);
	}

	// Restore blend mode & style before exiting
	ofDisableBlendMode();
	ofPopStyle();
}

// Draw and advance active draft-picked move animations (visual only)
void ofApp::drawActiveDraftPickedMoves() {
	// Use layout math consistent with drawDraftScreen (cardW/cardH computed there)
	float cardW, cardH, spacing, startX, startY;
	getDraftCardMetrics(false, cardW, cardH, spacing, startX, startY);

	float continuousFrame = (float)simulationFrame + (simulationAccumulator / SIMULATION_TIMESTEP);
	for (auto & mv : activeDraftPickedMoves) {
		if (mv.finished) continue;
		float elapsedFrames = continuousFrame - (float)mv.startFrame;
		if (elapsedFrames < mv.delayFrames) {
			float drawW = cardW;
			float drawH = cardH;
			float dx = mv.startPos.x - drawW / 2.0f;
			float dy = mv.startPos.y - drawH / 2.0f;
			ofSetColor(255);

			Player * pPtr = nullptr;
			if (mv.ownerIndex >= 0 && mv.ownerIndex < (int)players.size()) pPtr = &players[mv.ownerIndex];

			drawCardFaceDynamic(cardSpriteSheet, cardEffectFont, titleFont, mv.card, dx, dy, drawW, drawH, pPtr);
		} else {
			float activeFrames = elapsedFrames - (float)mv.delayFrames;
			float t = (mv.durationFrames > 0) ? ((float)activeFrames / (float)mv.durationFrames) : 1.0f;
			t = std::clamp(t, 0.0f, 1.0f);
			float easeT = t * t * (3.0f - 2.0f * t);
			glm::vec2 pos = mv.startPos * (1.0f - easeT) + mv.endPos * easeT;
			float scale = 1.0f * (1.0f - easeT) + mv.endScale * easeT;
			float drawW = cardW * scale;
			float drawH = cardH * scale;
			float dx = pos.x - drawW / 2.0f;
			float dy = pos.y - drawH / 2.0f;
			ofSetColor(255);

			Player * pPtr = nullptr;
			if (mv.ownerIndex >= 0 && mv.ownerIndex < (int)players.size()) pPtr = &players[mv.ownerIndex];

			drawCardFaceDynamic(cardSpriteSheet, cardEffectFont, titleFont, mv.card, dx, dy, drawW, drawH, pPtr);
			if (t >= 1.0f) {
				mv.finished = true;
				// Only flash main player decks; minion targets use their own shuffle visuals
				if (mv.ownerIndex >= 0 && mv.ownerIndex < (int)players.size() && !players[mv.ownerIndex].isMinion) {
					deckFlashStartFrame = (int)simulationFrame;
					deckFlashOwnerIndex = mv.ownerIndex;
				}
			}
		}
	}

	// Remove finished moves
	for (size_t i = activeDraftPickedMoves.size(); i-- > 0;) {
		if (activeDraftPickedMoves[i].finished) activeDraftPickedMoves.erase(activeDraftPickedMoves.begin() + i);
	}

	// Deck flash visual (Moved here so it resolves correctly outside of drafting state)
	if (deckFlashStartFrame > 0 && deckFlashOwnerIndex >= 0 && deckFlashOwnerIndex < (int)players.size()) {
		float startSec = deckFlashStartFrame / (float)turnTimerFramesPerSecond;
		float nowSecLocal = ofGetElapsedTimef();
		float elapsedSec = nowSecLocal - startSec;
		float durationSec = (deckFlashDurationFrames > 0) ? (deckFlashDurationFrames / (float)turnTimerFramesPerSecond) : 0.0001f;
		float t = (durationSec > 0.0f) ? (elapsedSec / durationSec) : 1.0f;
		if (t < 1.0f) {
			int ownerID = players[deckFlashOwnerIndex].playerID;
			ofRectangle deckRect = (ownerID == myLocalPlayerID) ? p0_deckRect : p1_deckRect;
			if (!isMultiplayer) deckRect = (ownerID == 0) ? p0_deckRect : p1_deckRect;
			float a = (1.0f - t) * 200.0f;
			ofPath p;
			p.rectRounded(deckRect.x - 4, deckRect.y - 4, deckRect.width + 8, deckRect.height + 8, 8);
			p.setFilled(false);
			p.setStrokeWidth(6.0f);
			p.setStrokeColor(ofColor(255, 220, 120, (int)a));
			p.draw();
		} else {
			deckFlashStartFrame = 0;
			deckFlashOwnerIndex = -1;
		}
	}
}

// (moved to UI Helpers earlier)
// Draw the pile view panel for a given player and view mode (consolidated helper)
void ofApp::drawPileViewFor(int viewPlayerIndex, PileViewMode viewMode) {
	if (viewPlayerIndex < 0 || viewPlayerIndex >= (int)players.size()) return;
	Player & viewPlayer = players[viewPlayerIndex];
	string viewTitle;
	std::vector<Card> cardsToShow;

	float handBaseCardWidth = kCardPixelWidth;
	float baseCardHeight = kCardPixelHeight;

	if (viewMode == VIEW_DECK) {
		viewTitle = "Deck";
		cardsToShow = viewPlayer.deck;
		std::sort(cardsToShow.begin(), cardsToShow.end(), [](const Card & a, const Card & b) {
			if (a.cost != b.cost) return a.cost < b.cost;
			return a.name < b.name;
		});
	} else {
		viewTitle = "Discard Pile";
		cardsToShow = viewPlayer.discardPile;
		std::reverse(cardsToShow.begin(), cardsToShow.end());
	}

	// Prefer human-friendly names. For minions, prefer the same numbering used in the Minion UI
	if (viewPlayer.isMinion) {
		// Find the matching MinionUI to reuse its displayNumber (ensures Assistant 1/2 match the side UI)
		int foundNumber = 0;
		for (const auto & mui : activeMinionUIs) {
			if (mui.playerIndex == viewPlayerIndex) {
				foundNumber = mui.displayNumber;
				break;
			}
		}
		std::string prefix = "Minion";
		if (viewPlayer.isFaerie)
			prefix = "Faerie";
		else if (viewPlayer.isWallUnit)
			prefix = "Wall";
		else if (viewPlayer.isKobold)
			prefix = "Kobold";
		else if (viewPlayer.isAssistant)
			prefix = "Assistant";
		else if (viewPlayer.isWolf)
			prefix = "Wolf";
		else if (viewPlayer.isHellhound)
			prefix = "Hellhound";
		else if (viewPlayer.isGolem)
			prefix = "Golem";
		else if (viewPlayer.isSkeleton)
			prefix = "Skeleton";
		else if (viewPlayer.isDemon)
			prefix = "Demon";

		if (foundNumber > 0) {
			viewTitle = prefix + " " + ofToString(foundNumber) + "'s " + viewTitle;
		} else {
			// Fallback to existing display-name logic
			viewTitle = getPlayerDisplayName(viewPlayerIndex) + "'s " + viewTitle;
		}
	} else {
		int vpIdx = -1;
		for (int i = 0; i < (int)players.size(); ++i) {
			if (players[i].playerID == viewPlayer.playerID && !players[i].isMinion) {
				vpIdx = i;
				break;
			}
		}
		viewTitle = (vpIdx != -1) ? getPlayerSteamName(vpIdx) : ("Player " + ofToString(viewPlayer.playerID)) + "'s " + viewTitle;
	}

	if (cardsToShow.empty()) {
		isShowingPileView = false;
		return;
	}

	float panelPadding = 20.0f;
	float titleHeight = 40.0f;
	float viewCardScale = 1.0f;
	float availableHeight = ofGetHeight() - (2 * panelPadding) - titleHeight;
	float availableWidth = ofGetWidth() * 0.7f;

	while (viewCardScale > 0.1f) {
		float cardW = handBaseCardWidth * viewCardScale;
		float cardH = baseCardHeight * viewCardScale;
		float padding = 15.0f * viewCardScale;
		int cols = std::max(1, (int)floor((availableWidth - padding) / (cardW + padding)));
		int rows = ceil((float)cardsToShow.size() / (float)cols);
		if (rows * (cardH + padding) - padding <= availableHeight) break;
		viewCardScale -= 0.05f;
	}

	float viewCardWidth = handBaseCardWidth * viewCardScale;
	float viewCardHeight = baseCardHeight * viewCardScale;
	float padding = 15.0f * viewCardScale;
	int gridWidthInCards = std::max(1, (int)floor((availableWidth - padding) / (viewCardWidth + padding)));
	gridWidthInCards = std::min(gridWidthInCards, (int)cardsToShow.size());
	if (gridWidthInCards <= 0) gridWidthInCards = 1;
	int gridHeightInCards = ceil((float)cardsToShow.size() / gridWidthInCards);
	float totalContentWidth = (gridWidthInCards * viewCardWidth) + ((gridWidthInCards - 1) * padding);
	float totalContentHeight = (gridHeightInCards * viewCardHeight) + ((gridHeightInCards - 1) * padding);

	float startX;
	bool anchored = false;
	if (viewPlayer.isMinion) {
		for (const auto & mui : activeMinionUIs) {
			if (mui.playerIndex == viewPlayerIndex) {
				float rightSpace = ofGetWidth() - mui.deckRect.getRight();
				if (rightSpace > totalContentWidth + 60.0f) {
					startX = mui.deckRect.getRight() + 30.0f;
				} else {
					startX = mui.deckRect.getLeft() - totalContentWidth - 30.0f - (2 * panelPadding);
				}
				anchored = true;
				break;
			}
		}
	}
	if (!anchored) {
		bool viewingLocal = (viewPlayer.playerID == myLocalPlayerID);
		if (viewingLocal)
			startX = p0_deckRect.getRight() + 30.0f;
		else
			startX = p1_deckRect.getLeft() - totalContentWidth - 30.0f - (2 * panelPadding);
	}
	float startY = ofGetHeight() / 2.0f - totalContentHeight / 2.0f;

	pileViewRect.set(startX, startY - titleHeight - panelPadding, totalContentWidth + 2 * panelPadding, totalContentHeight + titleHeight + 2 * panelPadding);

	ofSetColor(20, 20, 20, 220);
	ofDrawRectRounded(pileViewRect, 15);
	ofSetColor(ofColor::white);
	uiFont.drawString(viewTitle + " (" + ofToString(cardsToShow.size()) + " cards)", startX + panelPadding, startY - 15);

	for (size_t i = 0; i < cardsToShow.size(); ++i) {
		int row = i / gridWidthInCards;
		int col = i % gridWidthInCards;
		float drawX = startX + panelPadding + col * (viewCardWidth + padding);
		float drawY = startY + row * (viewCardHeight + padding);
		const Card & card = cardsToShow[i];

		Player * pPtr = nullptr;
		if (viewPlayerIndex >= 0 && viewPlayerIndex < (int)players.size()) pPtr = &players[viewPlayerIndex];

		drawCardFaceDynamic(cardSpriteSheet, cardEffectFont, titleFont, card, drawX, drawY, viewCardWidth, viewCardHeight, pPtr);
	}
}

// Simple layout helper for draft card metrics (keeps UI compiling).
void ofApp::getDraftCardMetrics(bool clampTop, float & outCardW, float & outCardH, float & outSpacing, float & outStartX, float & outStartY) {
	float screenScale = std::min(ofGetWidth() / 1920.0f, getUIScaleFromHeight(ofGetHeight()));
	float scale = screenScale * std::clamp(settingsUIScale, 0.75f, 1.25f);

	// Increased from 0.80f to 1.1f to make the cards much larger and prominent
	outCardW = kCardPixelWidth * 1.1f * scale;
	outCardH = kCardPixelHeight * 1.1f * scale;

	// Slightly tighter relative spacing so the 3 larger cards still fit comfortably on screen
	outSpacing = outCardW * 0.10f;

	float totalWidth = outCardW * 3.0f + outSpacing * 2.0f;
	outStartX = (ofGetWidth() - totalWidth) / 2.0f;

	// Perfectly center the cards vertically. (Removed the downward push so they
	// leave plenty of room for the Accept button below and instructions above).
	outStartY = (ofGetHeight() - outCardH) / 2.0f;
}

void ofApp::scheduleDraftPickedMove(const DraftPickedMove & mv) {
	activeDraftPickedMoves.push_back(mv);
}

void ofApp::updateDraftUiAnimations() {
	// Minimal placeholder: allow drawActiveDraftPickedMoves to manage cleanup.
}

void ofApp::drawPauseMenu() {
	ofPushStyle();
	ofEnableBlendMode(OF_BLENDMODE_ALPHA);
	ofSetColor(0, 0, 0, 180);
	ofDrawRectangle(0, 0, ofGetWidth(), ofGetHeight());

	float uiScale = std::clamp(settingsUIScale * std::min(ofGetWidth() / 1920.0f, getUIScaleFromHeight(ofGetHeight())), 0.75f, 1.25f);
	float centerX = ofGetWidth() / 2.0f;

	// --- Draw Background Panel ---
	float panelW = 500.0f * uiScale;
	float panelH = ofGetHeight() * 0.75f;
	float panelY = ofGetHeight() * 0.125f;
	ofRectangle panelRect(centerX - panelW / 2.0f, panelY, panelW, panelH);

	ofSetColor(25, 25, 30, 255);
	ofDrawRectRounded(panelRect, 16.0f);

	ofNoFill();
	ofSetLineWidth(2.0f);
	ofSetColor(80, 80, 90, 255);
	ofDrawRectRounded(panelRect, 16.0f);
	ofFill();

	ofSetColor(ofColor::white);
	std::string title = "PAUSED";
	ofRectangle titleBox = titleFont.getStringBoundingBox(title, 0, 0);
	titleFont.drawString(title, centerX - titleBox.getWidth() / 2.0f, panelY + 60.0f * uiScale);

	auto drawBtn = [&](const ofRectangle & r, const std::string & txt, int index) {
		if (r.width <= 0 || r.height <= 0) return;
		if (pauseMenuHoveredIndex == index || r.inside(ofGetMouseX(), ofGetMouseY())) {
			ofSetColor(ofColor::lightGray);
			g_hoveredButtonId = "pm_" + txt;
		} else {
			ofSetColor(ofColor::white);
		}
		ofDrawRectRounded(r, 12.0f);

		ofSetColor(ofColor::black);
		ofNoFill();
		ofSetLineWidth(2.0f);
		ofDrawRectRounded(r, 12.0f);
		ofFill();

		ofSetColor(ofColor::black);
		ofRectangle tb = uiFont.getStringBoundingBox(txt, 0, 0);
		uiFont.drawString(txt, r.getCenter().x - tb.getWidth() / 2.0f, r.getCenter().y + tb.getHeight() / 2.0f);
	};

	if (!isMultiplayer) {
		drawBtn(pauseMenuResumeButton, "Resume", 0);
		drawBtn(pauseMenuSaveButton, "Save Game", 1);
		drawBtn(pauseMenuLoadButton, "Load Game", 2);
		drawBtn(pauseMenuSettingsButton, "Settings", 3);
		drawBtn(pauseMenuQuitButton, "Quit to Menu", 4);
	} else {
		drawBtn(pauseMenuResumeButton, "Resume", 0);

		// --- DRAW SYSTEM UI ---
		if (g_isGameOver) {
			// Greyed out and disabled if the match is already over
			ofSetColor(80, 80, 90, 255);
			ofDrawRectRounded(g_pauseMenuDrawButton, 12.0f);
			ofSetColor(50, 50, 60, 255);
			ofNoFill();
			ofSetLineWidth(2.0f);
			ofDrawRectRounded(g_pauseMenuDrawButton, 12.0f);
			ofFill();
			ofSetColor(150, 150, 150, 255);
			ofRectangle tb = uiFont.getStringBoundingBox("Request Draw", 0, 0);
			uiFont.drawString("Request Draw", g_pauseMenuDrawButton.getCenter().x - tb.getWidth() / 2.0f, g_pauseMenuDrawButton.getCenter().y + tb.getHeight() / 2.0f);
		} else if (g_drawOfferPlayerID == -1) {
			drawBtn(g_pauseMenuDrawButton, "Request Draw", 5);
		} else if (g_drawOfferPlayerID == myLocalPlayerID) {
			drawBtn(g_pauseMenuDrawButton, "Cancel", 5);
			ofSetColor(200);
			drawPixelTextCentered(uiFont, "Awaiting answer...", g_pauseMenuDrawButton.getCenter().x, g_pauseMenuDrawButton.y - 10, 0.7f, ofColor::white);
		} else {
			// Opponent offered, draw the Accept/Decline UI
			ofSetColor(200);
			drawPixelTextCentered(uiFont, "Accept Draw?", g_pauseMenuDrawButton.getCenter().x, g_pauseMenuDrawButton.y - 10, 0.7f, ofColor::white);

			if (g_pauseMenuDrawYesButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "pm_draw_yes";
			ofSetColor(pauseMenuHoveredIndex == 6 || g_pauseMenuDrawYesButton.inside(ofGetMouseX(), ofGetMouseY()) ? ofColor(100, 255, 100) : ofColor(50, 200, 50));
			ofDrawRectRounded(g_pauseMenuDrawYesButton, 12.0f);
			drawPixelTextCentered(uiFont, "Yes", g_pauseMenuDrawYesButton.getCenter().x, g_pauseMenuDrawYesButton.getCenter().y, 1.0f, ofColor::black);

			if (g_pauseMenuDrawNoButton.inside(ofGetMouseX(), ofGetMouseY())) g_hoveredButtonId = "pm_draw_no";
			ofSetColor(pauseMenuHoveredIndex == 7 || g_pauseMenuDrawNoButton.inside(ofGetMouseX(), ofGetMouseY()) ? ofColor(255, 100, 100) : ofColor(200, 50, 50));
			ofDrawRectRounded(g_pauseMenuDrawNoButton, 12.0f);
			drawPixelTextCentered(uiFont, "No", g_pauseMenuDrawNoButton.getCenter().x, g_pauseMenuDrawNoButton.getCenter().y, 1.0f, ofColor::black);
		}

		drawBtn(pauseMenuSettingsButton, "Settings", 1);
		drawBtn(pauseMenuQuitButton, "Disconnect", 2);
	}

	ofPopStyle();
}
//--------------------------------------------------------------
void ofApp::drawTrainMenuUI() {
	drawMenuOverlay();

	// Title & Desc
	string title = "Train";
	string desc = "Choose your training path:";

	// Colors: Yellow for AP, Bronze/Orange for Class 1 Draft
	ofColor apColor(255, 215, 0);
	ofColor draftColor(205, 127, 50);

	// Ensure buttons are positioned if not already set (safety check)
	if (trainMenuRect.width == 0) {
		float w = 600, h = 300;
		float x = ofGetWidth() / 2 - w / 2, y = ofGetHeight() / 2 - h / 2;
		trainMenuRect.set(x, y, w, h);
		float btnW = 260, btnH = 80, spacing = 30;
		float startX = x + (w - (btnW * 2 + spacing)) / 2;
		float btnY = y + 130;
		trainBtnAP.set(startX, btnY, btnW, btnH);
		trainBtnDraft.set(startX + btnW + spacing, btnY, btnW, btnH);
	}

	drawCardChoicePanel(trainMenuRect, title, desc, trainBtnAP, trainBtnDraft,
		"+3 AP Next Turn", "Draft Class 1",
		apColor, draftColor, true, true);
}
//--------------------------------------------------------------
void ofApp::exit() {
	// 1. Close network sockets first
	if (zmqSocket) {
		zmqSocket->close();
		delete zmqSocket;
	}
	if (zmqContext) {
		delete zmqContext;
	}

	// 2. Save settings and shutdown Steam
	saveSettings();
	steamManager.cleanup();
	// Ensure the Steam API is fully shut down on app exit
	steamManager.shutdownAPI();
}
// --------------------------------------------------------------
void ofApp::updateAndSendHover(HoverType type, int gridX, int gridY, int cardIndex) {
	// Check if hover state changed
	if (type != localHoverType || gridX != localHoverGridX || gridY != localHoverGridY || cardIndex != localHoverCardIndex) {

		// Update local hover state
		localHoverType = type;
		localHoverGridX = gridX;
		localHoverGridY = gridY;
		localHoverCardIndex = cardIndex;

		// Send hover packet to opponent if in multiplayer
		if (isMultiplayer && steamManager.isConnected()) {
			// Only broadcast our active hover if it's our turn!
			if (isMyTurn() || type == HOVER_NONE) {
				HoverPacket pkt = {};
				pkt.type = PKT_HOVER;
				pkt.playerID = myLocalPlayerID;
				pkt.hoverType = static_cast<uint8_t>(type);
				pkt.gridX = static_cast<int8_t>(gridX);
				pkt.gridY = static_cast<int8_t>(gridY);
				pkt.cardIndex = static_cast<int8_t>(cardIndex);
				steamManager.sendPacket(&pkt, sizeof(pkt));
			}
		}
	}
}

// Networking / player helpers
int ofApp::getLocalPlayerIndex() const {
	for (int i = 0; i < (int)players.size(); ++i) {
		if (players[i].playerID == myLocalPlayerID) return i;
	}
	return -1;
}

bool ofApp::isLocalDraftingPlayer(int draftIndex) const {
	if (!isMultiplayer) return true;
	int localIdx = getLocalPlayerIndex();
	// Accept if either the slot index matches or the playerID at the slot matches local ID.
	if (localIdx >= 0 && localIdx == draftIndex) return true;
	if (draftIndex >= 0 && draftIndex < (int)players.size()) {
		const Player & draftActor = players[draftIndex];
		if (draftActor.playerID == myLocalPlayerID) return true;
		// In-game key drafts can target minions: ownership should gate local control.
		if (draftActor.isMinion && draftActor.ownerID == myLocalPlayerID) return true;
	}
	return false;
}

// --------------------------------------------------------------
void ofApp::processNetworkPackets() {
	// Diagnostic: report incoming queue size so we can see if packets are piling up
	if (!steamManager.packetQueue.empty()) {
		ofLogNotice("NetTrace") << "processNetworkPackets: queueSize=" << steamManager.packetQueue.size();
	}
	// Temporary reusable packet used for state syncs (declare when needed)
	while (!steamManager.packetQueue.empty()) {
		std::vector<char> buffer = steamManager.packetQueue.front();
		steamManager.packetQueue.pop();

		if (buffer.size() < sizeof(PacketHeader)) continue;

		PacketHeader * header = (PacketHeader *)buffer.data();

		// CRITICAL FIX: If we are not in a multiplayer match (or we fatal desynced), drop ALL gameplay packets.
		// This prevents lingering snapshots/commands in the Steam network buffer from
		// "resurrecting" a closed game and trapping the player in an empty board!
		// We DO NOT check currentState here because the Client is technically still in
		// STATE_MULTIPLAYER_MENU when it needs to receive the StartMatch command!
		if (!isMultiplayer || currentState == STATE_DESYNC) {
			if (header->type != PKT_HANDSHAKE && header->type != PKT_CLIENT_READY) {
				continue;
			}
		}

		// Mark that we're actively processing a network packet. This allows us to
		// enforce the "Zombie Client" rule: clients must not execute authoritative
		// logic (draws, dice, turn starts) except while handling host packets.
		{
			struct PacketProcessingGuard {
				bool * flag;
				PacketProcessingGuard(bool * f)
					: flag(f) { *flag = true; }
				~PacketProcessingGuard() { *flag = false; }
			} packetGuard(&processingNetworkPacket);

			// PKT_DRAFT_OPTIONS handling removed: draft options are applied deterministically
			// via the canonical input command stream. This legacy fast-path was deleted
			// to avoid UI races and duplicate processing.

			// Verbose packet tracing for debugging desyncs: only log canonical lockstep packets
			if (header->type == PKT_INPUT_COMMAND || header->type == PKT_CHECKSUM_CHECK || header->type == PKT_SNAPSHOT_BEGIN || header->type == PKT_SNAPSHOT_CHUNK || header->type == PKT_SNAPSHOT_END || header->type == PKT_MOVE_UNIT || header->type == PKT_PLACE_SUMMONED_BEGIN) {
				ofLogNotice("NetTrace") << "RECV pkt type=" << (int)header->type << " player=" << header->playerID << " seq=" << header->seq << " size=" << buffer.size();
				if (header->type == PKT_INPUT_COMMAND && buffer.size() >= sizeof(InputCommandPacket)) {
					InputCommandPacket * ic = (InputCommandPacket *)buffer.data();
					ofLogNotice("NetTrace") << "  INPUT_CMD type=" << (int)ic->commandType << " clientActionID=" << ic->clientActionID << " cmdId=" << ic->commandId;
				}
			}
			// ACK handling removed; rely on SteamNetworkingSockets reliability.

			// Only check duplicates for input command style packets (card plays / input commands)
			// STRICT: rely solely on clientActionID for deduplication on the host.
			// Network seq numbers are not used for dedupe because they can be
			// unrelated and much larger than client-local monotonic IDs.
			if (header->type == PKT_INPUT_COMMAND && buffer.size() >= sizeof(InputCommandPacket)) {
				InputCommandPacket * ip = (InputCommandPacket *)buffer.data();
				uint32_t clientActionID = ip->clientActionID;
				int sender = (header->playerID == 0 || header->playerID == 1) ? (int)header->playerID : -1;
				if (sender >= 0 && isHost()) {
					if (clientActionID != 0) {
						if (clientActionID <= lastReceivedSeqByPlayer[sender]) {
							ofLogNotice("Network") << "DROPPED DUPLICATE INPUT COMMAND (clientActionID): clientActionID=" << clientActionID << " lastReceived[" << sender << "]=" << lastReceivedSeqByPlayer[sender];
							// Re-ACK the clientActionID so the originating client stops resending
							AckPacket ack = {};
							ack.type = PKT_ACK;
							ack.playerID = myLocalPlayerID;
							ack.ackSeq = clientActionID; // echo the client ID
							ack.ackType = PKT_INPUT_COMMAND;
							steamManager.sendPacket(&ack, sizeof(ack));
							ofLogNotice("NetTrace") << "Host: re-sent ACK for clientActionID=" << ack.ackSeq;
							continue;
						}
						lastReceivedSeqByPlayer[sender] = clientActionID;
					} else {
						// No clientActionID present: cannot safely dedupe. Accept packet but
						// do not update lastReceivedSeqByPlayer to avoid corrupting the ID timeline.
						ofLogNotice("NetTrace") << "Host: Received input command without clientActionID; skipping dedupe.";
					}
				}
			}

			// Legacy TurnStart handling removed; clients now derive AP/turn-start
			// from deterministic command processing (CMD_END_TURN/CMD_PSEUDO_ACTION).

			if (header->type == PKT_SNAPSHOT_BEGIN) {
				SnapshotBeginPacket * bp = (SnapshotBeginPacket *)header;
				incomingSnapshotId = bp->snapshotId;

				// Clamp snapshot size to 10 MB to prevent memory exhaustion attacks
				uint32_t safeSize = std::min(bp->totalSize, (uint32_t)(10 * 1024 * 1024));

				incomingSnapshotExpectedSize = safeSize;
				incomingSnapshotReceivedSize = 0;
				incomingSnapshotBuffer.assign(safeSize, '\0');
				ofLogNotice("Network") << "Snapshot begin (id=" << incomingSnapshotId << ", bytes=" << incomingSnapshotExpectedSize << ")";
				continue;
			}

			if (header->type == PKT_SNAPSHOT_CHUNK) {
				SnapshotChunkPacket * cp = (SnapshotChunkPacket *)header;
				if (cp->snapshotId == incomingSnapshotId && !incomingSnapshotBuffer.empty()) {
					uint32_t end = cp->offset + cp->chunkSize;
					if (end <= incomingSnapshotBuffer.size()) {
						memcpy(&incomingSnapshotBuffer[cp->offset], cp->data, cp->chunkSize);
						incomingSnapshotReceivedSize += cp->chunkSize;
					}
				}
				continue;
			}

			if (header->type == PKT_SNAPSHOT_END) {
				SnapshotEndPacket * ep = (SnapshotEndPacket *)header;
				if (ep->snapshotId == incomingSnapshotId && incomingSnapshotExpectedSize > 0) {
					ofLogNotice("Network") << "Snapshot end (id=" << incomingSnapshotId << ")";
					applySnapshotString(incomingSnapshotBuffer, true);
					if (waitingForReconnect) {
						if (reconnectTurnTimerPausedByDisconnect) {
							turnTimerPaused = false;
							turnStartFrame = (int)simulationFrame - (turnDurationFrames - reconnectTurnTimerPausedRemainingFrames);
							turnTimerPausedRemainingFrames = 0;
							reconnectTurnTimerPausedByDisconnect = false;
							reconnectTurnTimerPausedRemainingFrames = 0;
						}
						waitingForReconnect = false;
						reconnectForfeitStartTime = -1.0f;
						currentState = STATE_GAMEPLAY;
						// Removed requestStartNewTurn() so we don't accidentally end the loaded turn!
						addGameLog("Reconnect complete. Resuming match.");
					}
					// Clear waiting flag if we had requested this snapshot
					waitingForSnapshotStartTime = 0.0f;
					addGameLog("Recovered game state from host snapshot");
					queueFloatingTextVisual(glm::vec3(0, 5, 0), "Snapshot Applied", ofColor::green);
					incomingSnapshotBuffer.clear();
					incomingSnapshotExpectedSize = 0;
					incomingSnapshotReceivedSize = 0;
				}
				continue;
			}

			if (header->type == PKT_SNAPSHOT_REQUEST) {
				SnapshotRequestPacket * rp = (SnapshotRequestPacket *)header;
				ofLogNotice("Network") << "Snapshot request received from player " << rp->playerID << " requestedTurn=" << rp->requestedTurn;
				if (isHost()) {
					// Just send the current state; no rewinding!
					sendSnapshotToClient(false);
					ofLogNotice("Network") << "Host: Sent authoritative snapshot to client.";
				}
				continue;
			}

			if (header->type == PKT_HANDSHAKE) {
				// FIX: Completely ignore stray/corrupted handshakes if we are already in an active match!
				if (currentState != STATE_MAIN_MENU && currentState != STATE_MULTIPLAYER_MENU) {
					continue;
				}

				HandshakePacket * pkt = (HandshakePacket *)header;

				// --- VERSION CONTROL: Reject outdated players! ---
				if (pkt->seq != 1002) {
					ofLogError("Network") << "VERSION MISMATCH! Expected 1002, got " << pkt->seq;
					addGameLog("ERROR: Version mismatch! You or your opponent must update the game.");
					steamManager.leaveLobby();
					cleanupGame();
					currentState = STATE_MAIN_MENU;
					continue;
				}

				// 1. HOST RECEIVES CLIENT REPLY
				if (steamManager.isHost() && pkt->playerID == 1) {
					if (!hasReceivedHandshake) {
						opponentElo = pkt->elo;
						// FIX: Host natively uses the EXACT seed provided by the Client to ensure zero drift
						currentMapSeed = localSeedComponent ^ pkt->seed;

						ofLogNotice("Network") << "Host received Client Handshake. Final Seed: " << currentMapSeed;

						isMultiplayer = true;
						myLocalPlayerID = 0;
						waitingForClientHandshake = false;
						hasReceivedHandshake = true;

						lastReceivedSeqByPlayer[0] = 0;
						lastReceivedSeqByPlayer[1] = 0;

						// Ensure RNG is seeded BEFORE setupGame runs!
						gameplayRNG.seed(currentMapSeed);
						gameplayRngAdvanceCount = 0;
						seedVisualRng(visualRNG, currentMapSeed);

						setupGame();
					}
				}
				// 2. CLIENT RECEIVES HOST REQUEST
				else if (!steamManager.isHost() && pkt->playerID == 0) {
					opponentElo = pkt->elo;

					if (!hasReceivedHandshake) {
						std::random_device rd;
						localSeedComponent = rd();
						myElo = steamManager.getLocalElo();

						currentMapSeed = pkt->seed ^ localSeedComponent;
						ofLogNotice("Network") << "Client received Host Handshake. Final Seed: " << currentMapSeed;

						isMultiplayer = true;
						if (g_isSpectator)
							myLocalPlayerID = 2;
						else
							myLocalPlayerID = 1;
						hasReceivedHandshake = true;
						gameplaySeededByHost = true;

						std::string p0Name = steamManager.getOpponentName();
						std::string p1Name = steamManager.getLocalPlayerName();
						player0SteamName = p0Name.empty() ? "Player 1" : p0Name;
						player1SteamName = p1Name.empty() ? "Player 2" : p1Name;

						// Ensure RNG is seeded BEFORE setupGame runs!
						gameplayRNG.seed(currentMapSeed);
						gameplayRngAdvanceCount = 0;
						seedVisualRng(visualRNG, currentMapSeed);

						if (currentState == STATE_MAIN_MENU || currentState == STATE_MULTIPLAYER_MENU) {
							setupGame();
						}
					}

					// Send the Handshake ACK back to the Host
					HandshakePacket ack = {};
					ack.type = PKT_HANDSHAKE;
					ack.playerID = 1;
					ack.seq = 1002; // <--- GAME VERSION ID! 1002
					ack.seed = localSeedComponent;
					ack.elo = myElo;
					steamManager.sendPacket(&ack, sizeof(ack));

					// Always send the READY packet immediately so the Host can start the match!
					ClientReadyPacket r = {};
					r.type = PKT_CLIENT_READY;
					r.playerID = myLocalPlayerID;
					r.ready = 1;
					steamManager.sendPacket(&r, sizeof(r));
					clientSentReady = true;
				}
				continue;
			}
			// Handle ClientReady: Host receives client confirmation that it's ready to start
			if (header->type == PKT_CLIENT_READY && buffer.size() >= sizeof(ClientReadyPacket)) {
				ClientReadyPacket * cr = (ClientReadyPacket *)header;
				ofLogNotice("Network") << "ClientReady received from playerID=" << cr->playerID;
				if (isHost() && hostWaitingForClientsReadyStartTime > 0.0f) {
					clientsReady.insert(cr->playerID);
					// For 2-player matches, start when we have any client ready
					if (!clientsReady.empty()) {
						ofLogNotice("Network") << "All clients ready - broadcasting StartMatch command.";
						hostWaitingForClientsReadyStartTime = 0.0f;

						// Broadcast a StartMatch command!
						InputCommandPacket startCmd = {};
						startCmd.type = PKT_INPUT_COMMAND;
						startCmd.playerID = myLocalPlayerID;
						startCmd.commandId = nextCommandId++;
						startCmd.turnNumber = globalTurnCounter;
						startCmd.commandType = CMD_PSEUDO_ACTION;
						strncpy(startCmd.stringData, "StartMatch", sizeof(startCmd.stringData) - 1);
						sendInputCommand(startCmd, true); // True = apply locally too
					}
				}
				continue;
			}
			if (header->type == PKT_INPUT_COMMAND) {
				if (buffer.size() < sizeof(InputCommandPacket)) continue;
				InputCommandPacket * cmd = (InputCommandPacket *)header;

				ofLogNotice("NetTrace") << "RECV PKT_INPUT_COMMAND: cmd=" << (int)cmd->commandType << " cmdId=" << cmd->commandId << " turn=" << cmd->turnNumber;

				if (isHost()) {
					if (cmd->playerID != (uint32_t)myLocalPlayerID) {
						// Host receives client intent. Assign official ID, execute, and echo.
						cmd->commandId = nextCommandId++;
						steamManager.sendPacket(cmd, sizeof(InputCommandPacket)); // CRITICAL FIX: Send BEFORE queuing
						queueInputCommand(*cmd);
					}
				} else {
					// Client receives officially sequenced command from Host.
					if (cmd->playerID == (uint32_t)myLocalPlayerID && cmd->clientActionID != 0) {
						// This is the Host echoing the command we already predicted!
						if (provisionalSnapshots.find(cmd->clientActionID) != provisionalSnapshots.end()) {
							ofLogNotice("Lockstep") << "Dropping echoed optimistic command clientActionID=" << cmd->clientActionID;
							provisionalSnapshots.erase(cmd->clientActionID);
							provisionalCommands.erase(cmd->clientActionID);

							// Stop the resend watchdog
							if (cmd->clientActionID == lastSentActionPacket.clientActionID) {
								lastSentActionValid = false;
							}

							// Sync local command ID counter to match Host's numbering
							if (cmd->commandId >= nextCommandId) {
								nextCommandId = cmd->commandId + 1;
							}
							// FIX 5: Clean up the fake command key from the executed set so it doesn't pollute memory
							uint64_t fakeKey = (uint64_t(cmd->playerID) << 32) | uint64_t(0xFFFFFFFF - cmd->clientActionID);
							executedCommandKeys.erase(fakeKey);

							continue; // We already executed this locally, do not queue it again!
						}
					}
					// It's the opponent's command, or a command we didn't predict. Execute it.
					queueInputCommand(*cmd);
				}
				continue;
			}

			// Handle MenuState visualization from opponents (open/close/hover)
			if (header->type == PKT_MENU_STATE) {
				if (buffer.size() < sizeof(MenuStatePacket)) continue;
				MenuStatePacket * msp = (MenuStatePacket *)header;
				int mappedIdx = -1;
				for (int i = 0; i < (int)players.size(); ++i) {
					if (players[i].playerID == (int)msp->playerID) {
						mappedIdx = i;
						break;
					}
				}
				// Only update visualization for remote players
				if (mappedIdx >= 0 && mappedIdx != getLocalPlayerIndex()) {
					if (msp->menuType == 0) {
						resetCardInteraction(); // FIX: Sync closure exactly!
					} else {
						// Map MenuType back to standard CardType
						CardType cType = CARD_NONE;
						switch (msp->menuType) {
						case 1:
							cType = CARD_WISDOM_BOON;
							break;
						case 2:
							cType = CARD_BURST_OF_LIGHT;
							break;
						case 3:
							cType = CARD_DOUBLE_HANDED;
							break;
						case 4:
							cType = CARD_MAGIC_BLAST;
							break;
						case 5:
							cType = PSEUDO_CARD_GHOST_RELOCATE;
							break;
						case 6:
							cType = CARD_RENEWED_INSPIRATION;
							break;
						case 7:
							cType = CARD_TRAIN;
							break;
						case 8:
							cType = CARD_DISPEL;
							break;
						case 9:
							cType = CARD_GIANT_MAGIC_HAND;
							break;
						case 10:
							cType = CARD_AMNESIA;
							break;
						}

						if (cType != CARD_NONE) {
							// FIX 2: Only trigger the state transition if it's not already open!
							// This prevents the menu from flashing every time the opponent moves their mouse.
							if (cardInteractionState != CARD_INTERACTION_STATE_MENU || interactingCardType != cType) {
								updateCardInteractionState(CARD_INTERACTION_STATE_MENU, msp->cardIndex, cType);
							}
							interactionTargetIndex = msp->targetIndex;

							// FIX: Unpack the wall coordinates for Giant Magic Hand
							if (cType == CARD_GIANT_MAGIC_HAND) {
								magicHandTargetTile.x = (msp->targetIndex >> 16) & 0xFFFF;
								magicHandTargetTile.y = msp->targetIndex & 0xFFFF;
							}

							opponentInteraction.open = true;
							opponentInteraction.type = msp->menuType;
							opponentInteraction.targetIndex = msp->targetIndex;
							opponentInteraction.cardIndex = msp->cardIndex;
							opponentInteraction.hoveredChoice = msp->hoveredChoice;
						}
					}
					ofLogNotice("Network") << "Received MenuState from playerID=" << msp->playerID << " type=" << msp->menuType << " hover=" << msp->hoveredChoice;
				}
				continue;
			}

			if (header->type == PKT_CHECKSUM_CHECK) {
				ChecksumPacket * pkt = (ChecksumPacket *)header;
				if (skipChecksumValidation || pkt->playerID == 2) continue;

				// DO NOT drop checksums from different turns!
				// Visual animations can cause a peer to start a turn slightly later/earlier than the other.
				// Just store it in the map and it will be safely evaluated when the local turn perfectly matches!
				s_pendingRemoteChecksums[pkt->turnNumber] = pkt->checksum;
				continue;
			}
			// PKT_KEY_PICKUP handling removed:
			// will detect key pickups locally. Legacy packet handling deleted to avoid
			// UI races and double-processing.
			else if (header->type == PKT_CHAT_MESSAGE) {
				ChatMessagePacket * pkt = (ChatMessagePacket *)header;

				std::string rawMsg = pkt->message;
				if (rawMsg.rfind("\aSYNC_NAME:", 0) == 0) {
					std::string syncedName = rawMsg.substr(11);
					if (pkt->playerID == 0)
						player0SteamName = syncedName;
					else if (pkt->playerID == 1)
						player1SteamName = syncedName;
					continue; // Hidden system message
				}

				ofLogNotice("Net") << "Received chat message from player " << pkt->playerID;

				ChatMessage msg;
				if (isMultiplayer) {
					if (pkt->playerID == 2) {
						std::string raw = pkt->message;
						size_t delim = raw.find('\a');
						if (delim != std::string::npos) {
							msg.playerName = raw.substr(0, delim) + " [Spectating]";
							msg.message = raw.substr(delim + 1);
						} else {
							msg.playerName = "Spectator";
							msg.message = raw;
						}
					} else {
						msg.playerName = (pkt->playerID == 0) ? player0SteamName : player1SteamName;
						msg.message = pkt->message;
					}
				} else {
					msg.playerName = (pkt->playerID == 0) ? "Player 1" : "Player 2";
					msg.message = pkt->message;
				}
				msg.timestamp = ofGetElapsedTimef();
				chatHistory.push_back(msg);
				if (chatHistory.size() > static_cast<size_t>(maxChatMessages)) {
					chatHistory.erase(chatHistory.begin());
				}
				// Show chat for 5 seconds when message received
				lastChatInteractionTime = ofGetElapsedTimef();
			} else if (header->type == PKT_HOVER) {
				// Ignore hover packets in singleplayer builds
				if (!isMultiplayer) continue;
				HoverPacket * pkt = (HoverPacket *)header;
				int hoverTypeInt = static_cast<int>(pkt->hoverType);
				if (hoverTypeInt >= 0 && hoverTypeInt <= 5) {
					opponentHoverType = static_cast<HoverType>(hoverTypeInt);
				}
				opponentHoverGridX = static_cast<int>(pkt->gridX);
				opponentHoverGridY = static_cast<int>(pkt->gridY);
				opponentHoverCardIndex = static_cast<int>(pkt->cardIndex);

				// If opponent selected a unit for movement, show their movement highlights
				if (opponentHoverType == HOVER_UNIT_SELECTED) {
					// Store current player state to restore after
					int savedPlayerX = -1, savedPlayerY = -1;
					if (currentPlayerIndex >= 0 && currentPlayerIndex < static_cast<int>(players.size())) {
						savedPlayerX = players[currentPlayerIndex].x;
						savedPlayerY = players[currentPlayerIndex].y;
						// Temporarily move current player to opponent's selected position
						players[currentPlayerIndex].x = opponentHoverGridX;
						players[currentPlayerIndex].y = opponentHoverGridY;
						calculateHighlights();
						// Restore position
						players[currentPlayerIndex].x = savedPlayerX;
						players[currentPlayerIndex].y = savedPlayerY;
					}
				}
				// If opponent is hovering a card OR targeting, show their targeting highlights
				else if ((opponentHoverType == HOVER_HAND_CARD || static_cast<int>(opponentHoverType) == 4) && opponentHoverCardIndex >= 0) {
					if (currentPlayerIndex >= 0 && currentPlayerIndex < static_cast<int>(players.size())) {
						Player & currentPlayer = players[currentPlayerIndex];
						if (opponentHoverCardIndex < static_cast<int>(currentPlayer.hand.size())) {
							calculateTargetHighlights(opponentHoverCardIndex);
						}
					}
				}
				// If opponent cleared hover, clear highlights
				else if (opponentHoverType == HOVER_NONE) {
					clearHighlights();
				}
			}

			// Legacy draft packet handlers removed: PKT_DRAFT_ACK, PKT_DRAFT_ACTION and
			// PKT_DRAFT_OPTIONS are no longer processed here. Drafting is driven
			// deterministically through the canonical input command stream.
		}

		// Legacy resend watchdogs removed: lockstep input commands are reliable.

		// Close processNetworkPackets() scope
	}

	// --- EVALUATE PENDING CHECKSUMS ---
	auto localIt = s_pendingLocalChecksums.begin();
	auto remoteIt = s_pendingRemoteChecksums.begin();
	while (localIt != s_pendingLocalChecksums.end() && remoteIt != s_pendingRemoteChecksums.end()) {
		if (localIt->first < remoteIt->first) {
			++localIt;
			continue;
		}
		if (remoteIt->first < localIt->first) {
			++remoteIt;
			continue;
		}

		long long localSum = localIt->second;
		long long remoteSum = remoteIt->second;
		int turnNumber = localIt->first;
		localIt = s_pendingLocalChecksums.erase(localIt);
		remoteIt = s_pendingRemoteChecksums.erase(remoteIt);

		writeLockstepTrace(steamManager.isHost(), turnNumber, "CHECKSUM_CHECK Evaluated. Local: " + std::to_string(localSum) + " Remote: " + std::to_string(remoteSum));

		if (localSum != remoteSum) {
			ofLogError("Net") << "DESYNC DETECTED! Local: " << localSum << " vs Remote: " << remoteSum << ". Halting game.";
			writeLockstepTrace(steamManager.isHost(), turnNumber, "*** DESYNC DETECTED! Local: " + std::to_string(localSum) + " vs Remote: " + std::to_string(remoteSum) + " ***");

			steamManager.disarmLeaverBuster();

			std::string roleStr = steamManager.isHost() ? "host" : "client";
			std::string dumpName = "latest_desync_dump_" + roleStr + ".txt";
			std::string traceName = "lockstep_trace_" + roleStr + ".log";

			std::string dumpStr = buildSnapshotString();
			ofBuffer dumpBuf;
			dumpBuf.set(dumpStr.c_str(), dumpStr.size());
			ofBufferToFile(dumpName, dumpBuf);
			writeLockstepTrace(steamManager.isHost(), globalTurnCounter, "Dumped full diverging state to: " + dumpName);

			// --- SEND DISCORD WEBHOOK WITH FILE ATTACHMENTS ---
			std::string webhookURL = "https://discord.com/api/webhooks/1521578853904941208/AFp-keJub945lhJcOlg3H8WtYw7QKY7AIDxvhxBQ5STHNstNbUSmypRGDuVI33rPdWTa";

			std::string myName = steamManager.getLocalPlayerName();
			if (myName.empty()) myName = "A Mage";
			std::string oppName = steamManager.getOpponentName();
			if (oppName.empty()) oppName = "Opponent";

			std::string msg = "🚨 **FATAL DESYNC DETECTED** 🚨\n";
			msg += "**Players:** " + myName + " vs " + oppName + "\n";
			msg += "**Turn:** " + std::to_string(globalTurnCounter) + "\n";
			msg += "**Role:** " + (steamManager.isHost() ? std::string("Host") : std::string("Client")) + "\n";
			msg += "Attached are the local state dump and lockstep trace for debugging.";

			std::vector<std::string> uploadFiles = { dumpName, traceName };
			sendDiscordFileWebhook(webhookURL, msg, uploadFiles);

			desyncMessage = "Local: " + std::to_string(localSum) + "\nRemote: " + std::to_string(remoteSum) + "\nCheck latest_desync_dump logs.";
			currentState = STATE_DESYNC;
			g_desyncStartTime = ofGetElapsedTimef();

			// --- FULL MATCH LOG SAVING (DESYNC) ---
			std::string matchLog = "=== MATCH SUMMARY ===\n";
			matchLog += "Timestamp: " + ofGetTimestampString("%Y-%m-%d %H:%M:%S") + "\n";
			matchLog += "End Reason: Fatal Desync\n";
			matchLog += "Seed: " + std::to_string(currentMapSeed) + "\n";
			matchLog += "Turns: " + std::to_string(globalTurnCounter) + "\n";
			matchLog += "Winner ID: N/A\n\n";
			matchLog += "--- PLAYERS ---\n";
			matchLog += "Player 0: " + player0SteamName + "\n";
			matchLog += "Player 1: " + player1SteamName + "\n\n";
			matchLog += "--- EVENT LOG ---\n";
			for (const auto & line : s_fullMatchLog) {
				matchLog += line + "\n";
			}
			matchLog += "\n--- STATS ---\n";
			for (int i = 0; i < 2; i++) {
				matchLog += "Player " + std::to_string(i) + " Stats:\n";
				matchLog += "  Max Dmg/Turn: " + std::to_string(matchStats[i].maxDamageInOneTurn) + "\n";
				matchLog += "  Cards Played: " + std::to_string(matchStats[i].cardsPlayed) + "\n";
				matchLog += "  Minions Spawned: " + std::to_string(matchStats[i].minionsSpawned) + "\n";
				matchLog += "  Total Healing: " + std::to_string(matchStats[i].totalHealing) + "\n";
			}
			matchLog += "=====================\n";

			std::string filename = getSavesDirPath().string() + "/match_log_DESYNC_" + ofGetTimestampString("%Y%m%d_%H%M%S") + ".txt";
			ofFile f(filename, ofFile::WriteOnly);
			f << matchLog;
			f.close();
			ofLogNotice("MatchLog") << "Saved full match log to " << filename;
			// --------------------------------------

			InputCommandPacket cmd = {};
			cmd.type = PKT_INPUT_COMMAND;
			cmd.playerID = myLocalPlayerID;
			cmd.commandId = nextCommandId++;
			cmd.turnNumber = globalTurnCounter;
			cmd.commandType = CMD_PSEUDO_ACTION;
			strncpy(cmd.stringData, "Desync", sizeof(cmd.stringData) - 1);
			steamManager.sendPacket(&cmd, sizeof(cmd));
		}
	}
}

// --- Networking helper implementations ---
void ofApp::sendPlaceSummonedBegin(int minionType, int ownerPlayerID, int sourceX, int sourceY, int numToPlace) {
	PlaceSummonedBeginPacket bp = {};
	bp.type = PKT_PLACE_SUMMONED_BEGIN;
	bp.playerID = myLocalPlayerID;
	bp.minionType = (uint8_t)minionType;
	bp.ownerPlayerID = ownerPlayerID;
	bp.sourceX = sourceX;
	bp.sourceY = sourceY;
	bp.numToPlace = numToPlace;
	steamManager.sendPacket(&bp, sizeof(bp));
	ofLogNotice("Network") << "Host sent PlaceSummonedBegin (helper): type=" << (int)bp.minionType << " owner=" << bp.ownerPlayerID << " source=(" << bp.sourceX << "," << bp.sourceY << ") num=" << bp.numToPlace;
}

void ofApp::sendPlaceSummonedMinion(int minionType, int ownerPlayerID, int targetX, int targetY, int minionHP, int minionAP, int minionPlayerID) {
	PlaceSummonedMinionPacket pkt = {};
	pkt.type = PKT_PLACE_SUMMONED_MINION;
	pkt.playerID = myLocalPlayerID;
	pkt.minionType = (uint8_t)minionType;
	pkt.ownerPlayerID = ownerPlayerID;
	pkt.targetX = targetX;
	pkt.targetY = targetY;
	pkt.minionHP = minionHP;
	pkt.minionAP = minionAP;
	// In deterministic lockstep mode we no longer broadcast individual minion
	// placement packets. Both peers spawn minions locally via the command
	// execution path. Suppress network send to avoid duplicate spawns.
	ofLogNotice("Network") << "Suppressed PlaceSummonedMinion send in lockstep mode: type=" << pkt.minionType << " owner=" << pkt.ownerPlayerID << " target=(" << pkt.targetX << "," << pkt.targetY << ")";
}

void ofApp::sendCardActionBegin(int cardType, int actorIndex, int targetX, int targetY, int p0, int p1, int p2, int p3, const std::string & label) {
	// Suppressed under deterministic lockstep migration: keep call sites, but
	// do not construct or send a CardActionBegin packet anymore.
	ofLogNotice("Network") << "Suppressed sendCardActionBegin (no packet): card=" << cardType << " actor=" << actorIndex << " target=(" << targetX << "," << targetY << ") p0=" << p0 << " p1=" << p1 << " label=" << label;
}

// Send menu state for opponent visualization
void ofApp::sendMenuState(int menuType, int targetIndex, int hoveredChoice, int cardIndex) {
	if (!isMultiplayer) return;

	MenuStatePacket pkt = {};
	pkt.type = PKT_MENU_STATE;
	pkt.playerID = myLocalPlayerID;
	pkt.seq = 0; // steamManager will stamp a seq
	pkt.menuType = menuType;
	pkt.targetIndex = targetIndex;
	pkt.hoveredChoice = hoveredChoice;
	pkt.cardIndex = cardIndex;

	// Send to opponent for visualization (host/client both forward/receive as needed)
	steamManager.sendPacket(&pkt, sizeof(pkt));
	ofLogNotice("Network") << "Sent MenuState: type=" << menuType << " target=" << targetIndex << " hover=" << hoveredChoice << " cardIndex=" << cardIndex;
}

// When I click a card
void ofApp::sendActionPacket(int cardIndex, int tx, int ty, int cost, int menuChoice, const std::string & cardNameOverride) {
	// 1. Check if it's my turn or my minion's turn
	if (currentPlayerIndex < 0 || currentPlayerIndex >= (int)players.size()) return;
	const Player & currentPlayer = players[currentPlayerIndex];

	// FIX: Explicitly check ownership for both Minions and Main Players!
	int controlledPlayerID = currentPlayer.isMinion ? currentPlayer.ownerID : currentPlayer.playerID;

	if (isMultiplayer && controlledPlayerID != myLocalPlayerID) {
		ofLogNotice("Network") << "sendActionPacket: abort - not controlling this player (controlledPlayerID=" << controlledPlayerID << " myLocalPlayerID=" << myLocalPlayerID << ")";
		return;
	}

	// 2. Create deterministic InputCommandPacket representing this play
	InputCommandPacket pkt = {};
	pkt.type = PKT_INPUT_COMMAND;
	pkt.playerID = myLocalPlayerID;
	pkt.commandId = nextCommandId++;
	pkt.turnNumber = globalTurnCounter;
	pkt.commandType = CMD_PLAY_CARD;
	pkt.params[0] = cardIndex;
	pkt.params[1] = tx;
	pkt.params[2] = ty;
	pkt.params[3] = menuChoice;
	// store card name (for validation on host)
	if (!cardNameOverride.empty()) {
		strncpy(pkt.stringData, cardNameOverride.c_str(), sizeof(pkt.stringData) - 1);
		pkt.stringData[sizeof(pkt.stringData) - 1] = '\0';
	}

	bool validSend = false;
	// If no name yet, try to resolve from cardIndex
	if (pkt.stringData[0] == '\0') {
		if (cardIndex >= 0 && cardIndex < (int)currentPlayer.hand.size()) {
			strncpy(pkt.stringData, currentPlayer.hand[cardIndex].name.c_str(), sizeof(pkt.stringData) - 1);
			pkt.stringData[sizeof(pkt.stringData) - 1] = '\0';
			validSend = true;
		}
	} else {
		// If we have a name, try to find it in our hand and sync index if found
		bool foundInHand = false;
		for (int i = 0; i < (int)currentPlayer.hand.size(); ++i) {
			if (currentPlayer.hand[i].name == pkt.stringData) {
				// Found the named card in hand
				validSend = true;
				foundInHand = true;
				if (cardIndex != i) pkt.params[0] = i;
				break;
			}
		}
		// If name not found in hand, allow name-only sends (caller may have removed card locally
		// before sending; permit sending as long as a name was provided).
		if (!foundInHand) {
			validSend = true; // permit name-only send
		}
	}

	if (!validSend) {
		ofLogWarning("Network") << "sendActionPacket: Aborting send - card not found in hand: cardIndex=" << cardIndex << " name='" << pkt.stringData << "' menuChoice=" << menuChoice;
		return;
	}

	ofLogNotice("Network") << "sendActionPacket: Sending card '" << pkt.stringData << "' (cardIndex=" << pkt.params[0] << ") to target=(" << tx << "," << ty << ") cost=" << cost;

	// 3. Send to Network
	// If we're a client, attach a clientActionID for ACK matching and record for resend
	if (isClient()) {
		pkt.clientActionID = ++actionClientActionCounter;
		lastSentActionPacket = pkt;
		lastSentActionValid = true;
		lastSentActionTime = ofGetElapsedTimef();
		lastSentActionResendCount = 0;
	}
	steamManager.sendPacket(&pkt, sizeof(pkt));

	// Local execution is handled by the caller (playCard + result handling).
}

void ofApp::sendMagicHandResolutionPacket(int choice) {
	if (!isMultiplayer) return;
	if (currentPlayerIndex < 0 || currentPlayerIndex >= (int)players.size()) return;
	const Player & currentPlayer = players[currentPlayerIndex];
	int controlledPlayerID = currentPlayer.isMinion ? currentPlayer.ownerID : currentPlayer.playerID;
	if (controlledPlayerID != myLocalPlayerID) return;
	if (interactingCardIndex < 0 || interactingCardIndex >= (int)currentPlayer.hand.size()) return;

	InputCommandPacket pkt = {};
	pkt.type = PKT_INPUT_COMMAND;
	pkt.playerID = myLocalPlayerID;
	pkt.commandId = nextCommandId++;
	pkt.turnNumber = globalTurnCounter;
	pkt.commandType = CMD_MENU_CHOICE;
	pkt.params[0] = interactingCardIndex;
	pkt.params[1] = magicHandTargetTile.x;
	pkt.params[2] = magicHandTargetTile.y;
	pkt.params[3] = choice;
	strncpy(pkt.stringData, currentPlayer.hand[interactingCardIndex].name.c_str(), sizeof(pkt.stringData) - 1);
	pkt.stringData[sizeof(pkt.stringData) - 1] = '\0';

	ofLogNotice("Network") << "sendMagicHandResolutionPacket: Sending '" << pkt.stringData << "' choice=" << choice
						   << " target=(" << pkt.params[1] << "," << pkt.params[2] << ")";
	steamManager.sendPacket(&pkt, sizeof(pkt));
}

// executeAction/executeOpponentCardPlay removed: incoming ActionPacket are now converted
// into `InputCommandPacket` inside `processNetworkPackets()` and queued for lockstep processing.

// Host-side validation for incoming ActionPackets (card plays).
// Ensures the chosen target(s) are still valid under the host's authoritative
// board state (e.g. non-self targets required for certain damage cards).
// Legacy ActionPacket validation removed as ActionPacket is deprecated under lockstep.

// Verify sync
long long ofApp::calculateChecksum() {
	// FNV-1a 64-bit
	const uint64_t FNV_OFFSET = 14695981039346656037ULL;
	const uint64_t FNV_PRIME = 1099511628211ULL;
	uint64_t h = FNV_OFFSET;
	auto mix = [&](uint64_t v) {
		h ^= v;
		h *= FNV_PRIME;
	};

	// --- 1. GLOBAL & RNG ---
	uint64_t h_global = FNV_OFFSET;
	auto mix_global = [&](uint64_t v) { h_global ^= v; h_global *= FNV_PRIME; mix(v); };

	mix_global((uint64_t)globalTurnCounter);
	mix_global((uint64_t)currentPlayerIndex);
	mix_global((uint64_t)currentAP);
	mix_global((uint64_t)gameplayRngAdvanceCount);
	mix_global((uint64_t)currentMapSeed);
	mix_global((uint64_t)nextSummonOrder);

	// --- 2. GAME & DRAFT STATE ---
	uint64_t h_state = FNV_OFFSET;
	auto mix_state = [&](uint64_t v) { h_state ^= v; h_state *= FNV_PRIME; mix(v); };

	GameState syncState = currentState;
	if (isMultiplayer && (currentState == STATE_PAUSED || currentState == STATE_SETTINGS || currentState == STATE_SAVE_BROWSER || currentState == STATE_DESYNC)) {
		syncState = pausedFromState;
	}
	mix_state((uint64_t)syncState);
	mix_state((uint64_t)(isInGameDraft ? 1 : 0));
	mix_state((uint64_t)(initialDraftComplete ? 1 : 0));
	mix_state((uint64_t)draftStage);
	mix_state((uint64_t)draftPlayerIndex);
	mix_state((uint64_t)draftPicksRemaining);
	mix_state((uint64_t)currentDraftClassTier);

	mix_state((uint64_t)networkPending.draftQueue.size());
	for (int v : networkPending.draftQueue)
		mix_state((uint64_t)v);

	mix_state((uint64_t)floatingKeyInstances.size());
	for (const auto & k : floatingKeyInstances) {
		mix_state((uint64_t)k.pos.x);
		mix_state((uint64_t)k.pos.y);
		mix_state((uint64_t)k.set);
	}

	mix_state((uint64_t)graveyard.size());
	for (const auto & g : graveyard) {
		mix_state((uint64_t)g.x);
		mix_state((uint64_t)g.y);
		mix_state((uint64_t)g.deck.size());
	}

	// --- 3. BOARD STATE ---
	uint64_t h_board = FNV_OFFSET;
	auto mix_board = [&](uint64_t v) { h_board ^= v; h_board *= FNV_PRIME; mix(v); };

	for (int y = 0; y < BOARD_HEIGHT; ++y) {
		for (int x = 0; x < BOARD_WIDTH; ++x) {
			mix_board((uint64_t)(board[x][y].hasWall ? 1 : 0));
			mix_board((uint64_t)(board[x][y].isMagicWall ? 1 : 0));
			mix_board((uint64_t)(board[x][y].hasPlayer ? 1 : 0));
		}
	}

	// --- 4. PLAYER STATE ---
	uint64_t h_players = FNV_OFFSET;
	auto mix_players = [&](uint64_t v) { h_players ^= v; h_players *= FNV_PRIME; mix(v); };

	for (const auto & p : players) {
		mix_players((uint64_t)p.playerID);
		mix_players((uint64_t)p.ownerID);
		mix_players((uint64_t)p.isMinion);
		mix_players((uint64_t)p.summonOrder);
		mix_players((uint64_t)p.x);
		mix_players((uint64_t)p.y);
		mix_players((uint64_t)p.health);
		mix_players((uint64_t)p.maxHealth);
		mix_players((uint64_t)p.block);
		mix_players((uint64_t)p.ward);
		mix_players((uint64_t)p.fortification);
		mix_players((uint64_t)p.barrier);
		mix_players((uint64_t)p.holyBlock);
		mix_players((uint64_t)p.luck);
		mix_players((uint64_t)p.bonusTurns);
		mix_players((uint64_t)p.ap);
		mix_players((uint64_t)p.onFire);
		mix_players((uint64_t)p.isParalyzed);
		mix_players((uint64_t)p.paralysisHeadsCount);
		mix_players((uint64_t)p.isPoisoned);
		mix_players((uint64_t)p.poisonReduction);
		mix_players((uint64_t)p.nextTurnAPBonus);
		mix_players((uint64_t)p.nextAttackAddPoison);
		mix_players((uint64_t)p.nextTurnD10AP);
		mix_players((uint64_t)p.nextTurnExtraDraw);
		mix_players((uint64_t)p.replicateQueued);
		mix_players((uint64_t)p.nextTurnBonusDiceFromMinions);
		mix_players((uint64_t)p.strengthenElementsTurnsRemaining);
		mix_players((uint64_t)p.sleepTurnsRemaining);
		mix_players((uint64_t)p.freeHandCardTurns);
		mix_players((uint64_t)p.summonedOnTurnCycle);
		mix_players((uint64_t)p.inTortoiseForm);
		mix_players((uint64_t)p.tortoiseDamageTaken);
		mix_players((uint64_t)p.inGhostForm);
		mix_players((uint64_t)p.ghostDamageTaken);
		mix_players((uint64_t)p.freeKickTurns);
		mix_players((uint64_t)p.defenseCycle);

		auto mixCard = [&](const Card & c) {
			mix_players((uint64_t)c.type);
			mix_players((uint64_t)c.cost);
			mix_players((uint64_t)c.value);
		};

		mix_players((uint64_t)p.deck.size());
		for (const auto & c : p.deck)
			mixCard(c);

		mix_players((uint64_t)p.hand.size());
		for (const auto & c : p.hand)
			mixCard(c);

		mix_players((uint64_t)p.discardPile.size());
		for (const auto & c : p.discardPile)
			mixCard(c);

		mix_players((uint64_t)p.playedCardsPile.size());
		for (const auto & c : p.playedCardsPile)
			mixCard(c);

		mix_players((uint64_t)p.cardsPlayedThisTurn.size());
		for (auto t : p.cardsPlayedThisTurn)
			mix_players((uint64_t)t);
	}

	if (isMultiplayer) {
		std::string chkStr = "CHECKSUM COMPONENTS | Final: " + std::to_string(h) + " | Global: " + std::to_string(h_global) + " | State: " + std::to_string(h_state) + " | Board: " + std::to_string(h_board) + " | Players: " + std::to_string(h_players);
		writeLockstepTrace(steamManager.isHost(), globalTurnCounter, chkStr);

		std::string stateDump = "STATE DUMP | AP: " + std::to_string(currentAP) + " | RNG Adv: " + std::to_string(gameplayRngAdvanceCount) + " | CurPlayer: " + std::to_string(currentPlayerIndex);
		writeLockstepTrace(steamManager.isHost(), globalTurnCounter, stateDump);

		for (const auto & p : players) {
			std::string pStr = "  -> Unit " + std::to_string(p.playerID) + " (Own:" + std::to_string(p.ownerID) + ")" + " Pos:(" + std::to_string(p.x) + "," + std::to_string(p.y) + ")" + " HP:" + std::to_string(p.health) + "/" + std::to_string(p.maxHealth) + " D/H/D/P:" + std::to_string(p.deck.size()) + "/" + std::to_string(p.hand.size()) + "/" + std::to_string(p.discardPile.size()) + "/" + std::to_string(p.playedCardsPile.size()) + " B/W/F/B/HB:" + std::to_string(p.block) + "/" + std::to_string(p.ward) + "/" + std::to_string(p.fortification) + "/" + std::to_string(p.barrier) + "/" + std::to_string(p.holyBlock);
			writeLockstepTrace(steamManager.isHost(), globalTurnCounter, pStr);
		}
	}

	return (long long)h;
}

// Public harness wrapper
bool ofApp::harnessLoadAndPrintChecksum(const std::string & path) {
	if (loadGameStateFromFile(path)) {
		long long chk = calculateChecksum();
		std::cout << "Loaded " << path << " checksum=" << chk << std::endl;
		return true;
	}
	return false;
}
// Auto-advance a small number of turns by sending deterministic CMD_END_TURN
// commands as the current player. This runs simulation ticks until the
// turn advances or a safety cap is reached for each advancement.
void ofApp::harnessAutoAdvanceTurns(int turns) {
	for (int t = 0; t < turns; ++t) {
		int startTurn = globalTurnCounter;
		// Determine current owner index
		int ownerIdx = currentPlayerIndex;
		if (ownerIdx < 0 || ownerIdx >= (int)players.size()) {
			ofLogNotice("Harness") << "No valid current player; stopping harness advance.";
			break;
		}

		int ownerPlayerID = players[ownerIdx].playerID;

		// Temporarily set local player id so sendInputCommand stamps the packet correctly
		int prevLocal = myLocalPlayerID;
		myLocalPlayerID = ownerPlayerID;

		InputCommandPacket endCmd = {};
		endCmd.type = PKT_INPUT_COMMAND;
		endCmd.playerID = ownerPlayerID; // will be overwritten by sendInputCommand, but keep for clarity
		endCmd.seq = 0;
		endCmd.commandId = 0; // let sendInputCommand assign canonical id
		endCmd.turnNumber = globalTurnCounter;
		endCmd.commandType = CMD_END_TURN;

		// Try smart actions: 1) attempt to play any hand card at likely targets
		// 2) attempt to move toward nearest enemy 3) fallback to END_TURN
		bool actionIssued = false;
		Player & owner = players[ownerIdx];

		// Build candidate targets: self tile, enemy tiles, adjacent tiles around enemies
		std::vector<std::pair<int, int>> candidates;
		candidates.emplace_back(owner.x, owner.y);
		for (size_t i = 0; i < players.size(); ++i) {
			if ((int)i == ownerIdx) continue;
			if (players[i].health <= 0) continue;
			candidates.emplace_back(players[i].x, players[i].y);
			// adjacents
			const int dx[4] = { 0, 1, 0, -1 };
			const int dy[4] = { -1, 0, 1, 0 };
			for (int k = 0; k < 4; ++k) {
				int nx = players[i].x + dx[k];
				int ny = players[i].y + dy[k];
				if (nx >= 0 && nx < BOARD_WIDTH && ny >= 0 && ny < BOARD_HEIGHT) candidates.emplace_back(nx, ny);
			}
		}

		// Try to play multiple cards per turn (up to a small cap).
		// Build a small loop: pick the best-scoring playable card+target, play it, resolve menus, and repeat.
		int playsThisTurn = 0;
		const int kMaxPlaysPerTurn = 4;
		while (playsThisTurn < kMaxPlaysPerTurn) {
			// Refresh owner reference (hand may have changed)
			int curOwnerIdx = findPlayerIndexByID(owner.playerID);
			if (curOwnerIdx < 0) break;
			Player & curOwner = players[curOwnerIdx];

			struct CandidatePlay {
				int cardIndex;
				int tx;
				int ty;
				double score;
			};
			std::vector<CandidatePlay> candidatesPlays;

			// Consider each card and candidate target; validate using calculateTargetHighlights
			for (int ci = 0; ci < (int)curOwner.hand.size(); ++ci) {
				const Card & c = curOwner.hand[ci];
				int cost = getEffectiveCardCostForPlayer(curOwner, c);
				if (cost > curOwner.ap) continue;

				// Run target highlight calc in harness context to set board[x][y].isTargetable
				int prevCardIndex = interactingCardIndex;
				int prevState = (int)cardInteractionState;
				interactingCardIndex = ci;
				calculateTargetHighlights(ci);
				// Score heuristic: prefer damage/heal/block/draw
				double baseScore = 0.0;
				baseScore += (double)c.baseDamage;
				baseScore += 0.5 * (double)c.damageDiceNum * (double)(c.damageDiceSides > 0 ? (c.damageDiceSides + 1) / 2.0 : 0.0);
				baseScore += 1.2 * (double)(c.healAmount + c.baseHeal);
				baseScore += 0.8 * (double)c.blockAmount + 0.8 * (double)c.wardAmount + 0.6 * (double)c.apGain;
				baseScore += 0.4 * (double)c.drawCount;

				// If card is self-targeting and caster is valid, add candidate
				if (c.targeting == TARGET_SELF) {
					candidatesPlays.push_back({ ci, curOwner.x, curOwner.y, baseScore * 0.9 + 0.1 });
				}

				// Add any board tile previously computed as targetable
				for (int tx = 0; tx < BOARD_WIDTH; ++tx) {
					for (int ty = 0; ty < BOARD_HEIGHT; ++ty) {
						if (!board[tx][ty].isTargetable) continue;
						double score = baseScore;
						// prefer enemy-occupied targets
						if (board[tx][ty].hasPlayer) score += 2.0;
						candidatesPlays.push_back({ ci, tx, ty, score });
					}
				}

				// restore
				interactingCardIndex = prevCardIndex;
				cardInteractionState = (CardInteractionState)prevState;
			}

			if (candidatesPlays.empty()) break;

			// pick best candidate
			std::sort(candidatesPlays.begin(), candidatesPlays.end(), [](const CandidatePlay & a, const CandidatePlay & b) { return a.score > b.score; });
			CandidatePlay best = candidatesPlays.front();

			// Re-validate owner still has that card index (hand may have shifted). If not, try to find card by type.
			int playCardIndex = best.cardIndex;
			if (playCardIndex < 0 || playCardIndex >= (int)players[ownerIdx].hand.size()) {
				// try to find equivalent type in hand
				bool found = false;
				for (int i = 0; i < (int)players[ownerIdx].hand.size(); ++i) {
					if (players[ownerIdx].hand[i].type == players[ownerIdx].hand[best.cardIndex < (int)players[ownerIdx].hand.size() ? best.cardIndex : 0].type) {
						playCardIndex = i;
						found = true;
						break;
					}
				}
				if (!found) break;
			}

			InputCommandPacket playCmd = {};
			playCmd.type = PKT_INPUT_COMMAND;
			playCmd.seq = 0;
			playCmd.commandId = 0;
			playCmd.turnNumber = globalTurnCounter;
			playCmd.commandType = CMD_PLAY_CARD;
			playCmd.params[0] = playCardIndex; // card index
			playCmd.params[1] = best.tx;
			playCmd.params[2] = best.ty;

			ofLogNotice("Harness") << "Harness: choosing PLAY_CARD idx=" << playCmd.params[0] << " target=(" << best.tx << "," << best.ty << ") score=" << best.score;
			sendInputCommand(playCmd, true);

			// Run ticks to let play resolve. Also auto-resolve simple menus deterministically.
			int safety = 0;
			while (safety < 60 && globalTurnCounter == startTurn) {
				simulationTick();
				// If a menu appeared, auto-resolve it with a deterministic choice
				if (cardInteractionState == CARD_INTERACTION_STATE_MENU) {
					int choice = 1; // default choice id
					switch (interactingCardType) {
					case CARD_BURST_OF_LIGHT:
						// prefer damage unless target is self
						if (interactionTargetIndex == currentPlayerIndex)
							choice = 2;
						else
							choice = 1;
						break;
					case CARD_WISDOM_BOON:
						choice = 1;
						break; // prefer damage
					case CARD_DOUBLE_HANDED:
						choice = 1;
						break; // prefer punches
					case CARD_AMNESIA:
						choice = 1;
						break; // self-path
					case CARD_DISPEL:
						choice = 2;
						break; // purge by default
					case CARD_MAGIC_BLAST:
						choice = 1;
						break;
					default:
						choice = 1;
						break;
					}

					InputCommandPacket menuCmd = {};
					menuCmd.type = PKT_INPUT_COMMAND;
					menuCmd.playerID = myLocalPlayerID;
					menuCmd.seq = 0;
					menuCmd.commandId = nextCommandId++;
					menuCmd.turnNumber = globalTurnCounter;
					menuCmd.commandType = CMD_MENU_CHOICE;
					menuCmd.params[0] = interactingCardType;
					menuCmd.params[1] = interactionTargetIndex;
					menuCmd.params[2] = choice;
					menuCmd.params[3] = interactingCardIndex;
					strncpy(menuCmd.stringData, interactingCardName.c_str(), sizeof(menuCmd.stringData) - 1);
					menuCmd.stringData[sizeof(menuCmd.stringData) - 1] = '\0';
					ofLogNotice("Harness") << "Harness: auto-resolving menu for card=" << interactingCardType << " choice=" << choice;
					sendInputCommand(menuCmd, true);
				}
				safety++;
			}

			// Check if play had observable effect (hand/AP changed or player moved/died)
			int newOwnerIdx = findPlayerIndexByID(owner.playerID);
			if (newOwnerIdx >= 0) {
				Player & newOwner = players[newOwnerIdx];
				if ((int)newOwner.hand.size() < (int)curOwner.hand.size() || newOwner.ap != curOwner.ap) {
					playsThisTurn++;
					actionIssued = true;
					// continue attempting more plays
					continue;
				}
			} else {
				// owner removed
				actionIssued = true;
				break;
			}

			// If we reach here no meaningful change occurred; stop attempting plays
			break;
		}

		// If no card played, try to move toward nearest enemy
		if (!actionIssued) {
			int bestDist = 100000;
			int tx = -1, ty = -1;
			for (size_t i = 0; i < players.size(); ++i) {
				if ((int)i == ownerIdx) continue;
				if (players[i].health <= 0) continue;
				int d = abs(players[i].x - owner.x) + abs(players[i].y - owner.y);
				if (d < bestDist) {
					bestDist = d;
					tx = players[i].x;
					ty = players[i].y;
				}
			}
			if (tx != -1) {
				InputCommandPacket mv = {};
				mv.type = PKT_INPUT_COMMAND;
				mv.seq = 0;
				mv.commandId = 0;
				mv.turnNumber = globalTurnCounter;
				mv.commandType = CMD_MOVE_UNIT;
				mv.params[0] = owner.x;
				mv.params[1] = owner.y;
				mv.params[2] = tx;
				mv.params[3] = ty;
				ofLogNotice("Harness") << "Harness: attempting MOVE_UNIT to (" << tx << "," << ty << ")";
				sendInputCommand(mv, true);
				int safety = 0;
				while (safety < 30 && globalTurnCounter == startTurn) {
					simulationTick();
					safety++;
				}
				int newIdx = findPlayerIndexByID(owner.playerID);
				if (newIdx >= 0) {
					Player & newOwner = players[newIdx];
					if (newOwner.x != owner.x || newOwner.y != owner.y) {
						actionIssued = true;
						ofLogNotice("Harness") << "Harness: MOVE_UNIT succeeded.";
					}
				} else {
					actionIssued = true; // owner removed
				}
			}
		}

		if (!actionIssued) {
			ofLogNotice("Harness") << "Harness: no action possible; sending END_TURN for playerID=" << ownerPlayerID << " at turn=" << globalTurnCounter;
			sendInputCommand(endCmd, true);
		}

		// Restore local player id
		myLocalPlayerID = prevLocal;

		// Run deterministic ticks until turn increments or safety cap (500 ticks)
		int safety = 0;
		while (globalTurnCounter == startTurn && safety < 500) {
			simulationTick();
			safety++;
		}
		ofLogNotice("Harness") << "Harness: advanced from turn " << startTurn << " to " << globalTurnCounter << " (ticks=" << safety << ")";
		// Small deterministic post-advance tick to stabilize effects
		for (int k = 0; k < 3; ++k)
			simulationTick();
	}
}
//--------------------------------------------------------------
void ofApp::applyMovement(int playerIndex, int targetX, int targetY, int newAP, const std::vector<glm::vec2> * pathOverride) {
	if (playerIndex < 0 || playerIndex >= (int)players.size()) return;
	Player & p = players[playerIndex];
	if (targetX < 0 || targetX >= BOARD_WIDTH || targetY < 0 || targetY >= BOARD_HEIGHT) return;

	const int prevX = p.x;
	const int prevY = p.y;

	// Log the movement
	addGameLog(getPlayerSteamName(playerIndex) + " moved to (" + ofToString(targetX) + "," + ofToString(targetY) + ")");

	// Record movement in Action History
	ActionHistoryEntry he;
	he.isMovement = true;
	he.playerID = p.isMinion ? p.ownerID : p.playerID;
	he.actorPlayerID = p.playerID; // Use stable, unique player ID for minion/player lookup
	he.fromX = prevX;
	he.fromY = prevY;
	he.toX = targetX;
	he.toY = targetY;

	if (pathOverride && pathOverride->size() > 1) {
		he.movementPath = *pathOverride;
	} else {
		std::vector<glm::vec2> path = findShortestPathForPlayer(playerIndex, { (float)prevX, (float)prevY }, { (float)targetX, (float)targetY });
		he.movementPath = path;
	}

	g_actionHistory.push_back(he);
	if (g_actionHistory.size() > 8) g_actionHistory.erase(g_actionHistory.begin());

	// Safety: Prevent ending movement on a tile occupied by another unit.
	// Movement selection should normally prevent this, but enforce here
	// to avoid overlapping units (which can happen with networked packets
	// or edge cases). Allow if target == previous position (no-op).
	if (!(targetX == prevX && targetY == prevY) && board[targetX][targetY].hasPlayer) {
		if (!p.inGhostForm) {
			ofLogWarning("Movement") << "applyMovement blocked: target (" << targetX << "," << targetY << ") is occupied; movement aborted.";
			return;
		}
	}

	bool othersOnPrev = false;
	for (size_t i = 0; i < players.size(); ++i) {
		if ((int)i != playerIndex && players[i].x == prevX && players[i].y == prevY && players[i].health > 0) {
			othersOnPrev = true;
			break;
		}
	}
	if (!othersOnPrev) {
		board[prevX][prevY].hasPlayer = false;
	}

	if (newAP >= 0) {
		ofLogNotice("APDebug") << "applyMovement: playerIndex=" << playerIndex << " prev_currentAP=" << currentAP << " newAP=" << newAP << " p.ap(before)=" << p.ap;
		currentAP = newAP;
		p.ap = newAP;
		ofLogNotice("APDebug") << "applyMovement: p.ap(after)=" << p.ap << " currentAP(after)=" << currentAP;
	}

	// Build animation path
	animationPath.clear();
	currentPathIndex = 0;
	glm::vec3 startPos = gridToWorld(prevX, prevY);
	glm::vec3 endPos = gridToWorld(targetX, targetY);
	playerVisualPos = startPos;
	animationPath.push_back(startPos);

	if (pathOverride && pathOverride->size() > 1) {
		for (size_t i = 1; i < pathOverride->size(); ++i) {
			animationPath.push_back(gridToWorld((int)(*pathOverride)[i].x, (int)(*pathOverride)[i].y));
		}
	} else {
		std::vector<glm::vec2> path = findShortestPathForPlayer(playerIndex, { (float)prevX, (float)prevY }, { (float)targetX, (float)targetY });
		if (path.size() > 1) {
			for (size_t i = 1; i < path.size(); ++i) {
				animationPath.push_back(gridToWorld((int)path[i].x, (int)path[i].y));
			}
		} else {
			animationPath.push_back(endPos);
		}
	}

	if (!animationPath.empty()) {
		isPlayerAnimating = true;
		animatingPlayerIndex = playerIndex;
		animationSegmentStartTime = ofGetElapsedTimef();
	}

	board[targetX][targetY].hasPlayer = true;
	p.x = targetX;
	p.y = targetY;

	// Clear the enteredWallByClick flag if the player is no longer inside a wall
	if (!board[targetX][targetY].hasWall) {
		p.enteredWallByClick = false;
	}

	invalidateTargetCache();
}
//--------------------------------------------------------------
// Anti-cheat: Get deck state as string for logging
std::string ofApp::getDeckStateString(const Player & p) {
	std::string result = "Player" + std::to_string(p.playerID) + " Deck[" + std::to_string(p.deck.size()) + "]: ";
	for (size_t i = 0; i < p.deck.size(); ++i) {
		if (i > 0) result += ", ";
		result += p.deck[i].name + "(" + std::to_string((int)p.deck[i].type) + ")";
	}
	result += " | Hand[" + std::to_string(p.hand.size()) + "]: ";
	for (size_t i = 0; i < p.hand.size(); ++i) {
		if (i > 0) result += ", ";
		result += p.hand[i].name + "(" + std::to_string((int)p.hand[i].type) + ")";
	}
	result += " | Discard[" + std::to_string(p.discardPile.size()) + "]: ";
	for (size_t i = 0; i < p.discardPile.size(); ++i) {
		if (i > 0) result += ", ";
		result += p.discardPile[i].name + "(" + std::to_string((int)p.discardPile[i].type) + ")";
	}
	return result;
}
//--------------------------------------------------------------
// ==============================================================================
// DEEP REINFORCEMENT LEARNING AI AGENT SCAFFOLDING
// ==============================================================================
void ofApp::updateAI() {
	if (!isVsAI && !isAIvsAI) return;

	// FIX: In a Human vs AI match, prevent the AI from acting when it is the Human's turn!
	if (isVsAI && !isAIvsAI && isMyTurn()) return;

	// CRITICAL FIX: If we are in AI vs AI mode, ensure we actually wait for the C++
	// state machine to settle on a valid player before asking the Python script!
	if (isAIvsAI && (players.empty() || currentPlayerIndex < 0)) return;

	if (endTurnLocked || g_isGameOver || currentState == STATE_DESYNC) return;

	// CRITICAL FIX: Strictly forbid the AI from acting during the Initiative Roll,
	// Menus, or Pauses. It can only act during pure Gameplay or Drafting!
	if (currentState != STATE_GAMEPLAY && currentState != STATE_DRAFTING) return;

	bool isGameBusy = false;

	// FIX: Prevent the AI from thinking/spamming if it already has commands waiting to execute!
	if (!commandQueue.empty() || isExecutingLockstepCommand) isGameBusy = true;

	// ADD THIS: Prevent ZMQ decisions during the draft card intro scale-up in visual mode
	if (currentState == STATE_DRAFTING && !headless && !draftDisplayInteractiveEnabled) isGameBusy = true;

	// Allow the AI to draft even if a walking animation hasn't finished its final frame
	if (isProcessingEffect || isEarthquakeActive) isGameBusy = true;
	if (currentState != STATE_DRAFTING && isPlayerAnimating) isGameBusy = true;
	for (const auto & roll : activeDiceRolls) {
		if (!roll.isFinishedVisual) isGameBusy = true;
	}

	// CRITICAL FIX: Allow AI to act when it needs to click a target or place a unit!
	if (cardPlayState != CARD_PLAY_STATE_IDLE && cardInteractionState != CARD_INTERACTION_STATE_MENU && cardInteractionState != CARD_INTERACTION_STATE_TARGETING && cardInteractionState != CARD_INTERACTION_STATE_PLACING) {
		isGameBusy = true;
	}

	if (currentState == STATE_DRAFTING && draftOptions.empty()) isGameBusy = true;
	if (draftNextScheduled || draftEndScheduled || draftAcceptLocked) isGameBusy = true;

	// Prevent AI from spamming commands before the turn officially begins
	if (turnStartDeferred) isGameBusy = true;

	if (isGameBusy) return;

	// --- AI DRAFT HANDLER ---
	// The AI now handles drafting via its standard action loop. This block has been disabled.
	// ------------------------

	// If watching the AI play normally (not headless), add a tiny delay
	if (!headless) {
		aiThinkTimer -= ofGetLastFrameTime();
		if (aiThinkTimer > 0.0f) return;
		aiThinkTimer = 0.05f;
	}

	std::vector<float> stateVector = extractGameStateForAI();
	float rewardToSend = cumulativeReward;
	cumulativeReward = 0.0f;

	int actionIndex = getAIActionFromModel(stateVector, rewardToSend, false);
	executeAIAction(actionIndex);
}

std::vector<float> ofApp::extractGameStateForAI() {
	std::vector<float> state;
	state.reserve(5700); // Reserve memory to prevent slow allocations

	// --- 1. GLOBAL STATE (5 floats) ---
	state.push_back((float)globalTurnCounter);
	state.push_back((float)currentAP);
	state.push_back(isInGameDraft ? 1.0f : 0.0f);
	state.push_back((float)draftStage);
	state.push_back((float)draftPicksRemaining);

	// The Network needs to see the board from the perspective of whoever's turn it is
	int activeID = 1;
	if (isAIvsAI) {
		if (currentState == STATE_DRAFTING) {
			activeID = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) ? players[draftPlayerIndex].playerID : 0;
		} else {
			activeID = players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID;
		}
	} else if (isVsAI) {
		activeID = 1; // In Human vs AI, the AI is always Player 1
	}
	int opponentID = (activeID == 1) ? 0 : 1;

	// --- 2. MAIN PLAYER STATES (32 floats total) ---
	auto encodePlayer = [&](int pID) {
		int idx = findPlayerIndexByID(pID);
		if (idx >= 0 && idx < (int)players.size()) {
			const Player & p = players[idx];
			state.push_back((float)p.health);
			state.push_back((float)p.maxHealth);
			state.push_back((float)p.block);
			state.push_back((float)p.ward);
			state.push_back((float)p.fortification);
			state.push_back((float)p.barrier);
			state.push_back((float)p.holyBlock);
			state.push_back((float)p.luck + computePassiveLuck(idx));
			state.push_back(p.onFire ? 1.0f : 0.0f);
			state.push_back(p.isPoisoned ? 1.0f : 0.0f);
			state.push_back(p.isParalyzed ? 1.0f : 0.0f);
			state.push_back((float)p.sleepTurnsRemaining);
			state.push_back(p.inTortoiseForm ? 1.0f : 0.0f);
			state.push_back(p.inGhostForm ? 1.0f : 0.0f);
			state.push_back((float)p.deck.size());
			state.push_back((float)p.discardPile.size());
		} else {
			for (int i = 0; i < 16; i++)
				state.push_back(0.0f);
		}
	};
	encodePlayer(activeID); // The AI making the decision
	encodePlayer(opponentID); // The Enemy

	// --- 3. CARD KNOWLEDGE (420 floats: 6 zones x 70 cards) ---
	auto encodeCardZone = [&](const std::vector<Card> & zone) {
		std::vector<float> counts(70, 0.0f);
		for (const auto & c : zone) {
			int cId = (int)c.type - 1; // CARD_NONE is 0, cards are 1-70
			if (cId >= 0 && cId < 70) counts[cId] += 1.0f;
		}
		for (float f : counts)
			state.push_back(f);
	};

	int aiIdx = findPlayerIndexByID(activeID);
	if (aiIdx >= 0) {
		encodeCardZone(players[aiIdx].hand);
		encodeCardZone(players[aiIdx].deck);
		encodeCardZone(players[aiIdx].discardPile);
	} else {
		for (int i = 0; i < 210; i++)
			state.push_back(0.0f);
	}

	int enIdx = findPlayerIndexByID(opponentID);
	if (enIdx >= 0) {
		encodeCardZone(players[enIdx].hand);
		encodeCardZone(players[enIdx].deck);
		encodeCardZone(players[enIdx].discardPile);
	} else {
		for (int i = 0; i < 210; i++)
			state.push_back(0.0f);
	}

	// --- 4. DRAFT OPTIONS (70 floats) ---
	std::vector<float> draftCounts(70, 0.0f);
	if (currentState == STATE_DRAFTING) {
		for (const Card & c : draftOptions) {
			int cardId = (int)c.type - 1;
			if (cardId >= 0 && cardId < 70) draftCounts[cardId] += 1.0f;
		}
	}
	for (float f : draftCounts)
		state.push_back(f);

	// --- 5. BOARD SPATIAL GRID (165 tiles * 33 floats = 5445 floats) ---
	for (int y = 0; y < BOARD_HEIGHT; ++y) {
		for (int x = 0; x < BOARD_WIDTH; ++x) {
			const Tile & t = board[x][y];

			state.push_back(t.hasWall ? 1.0f : 0.0f);
			state.push_back(t.isMagicWall ? 1.0f : 0.0f);

			float hasGold = 0, hasSilver = 0, hasBronze = 0;
			for (const auto & k : floatingKeyInstances) {
				if (k.pos.x == x && k.pos.y == y) {
					if (k.set == 1)
						hasGold = 1.0f;
					else if (k.set == 2)
						hasSilver = 1.0f;
					else if (k.set == 3)
						hasBronze = 1.0f;
				}
			}
			state.push_back(hasGold);
			state.push_back(hasSilver);
			state.push_back(hasBronze);

			state.push_back(t.hasPlayer ? 1.0f : 0.0f);

			bool foundOccupant = false;
			for (size_t i = 0; i < players.size(); ++i) {
				const Player & p = players[i];
				if (p.x == x && p.y == y && p.health > 0) {
					foundOccupant = true;

					int owner = p.isMinion ? p.ownerID : p.playerID;
					state.push_back(owner == activeID ? 1.0f : -1.0f);

					state.push_back(!p.isMinion ? 1.0f : 0.0f);
					state.push_back(p.isKobold ? 1.0f : 0.0f);
					state.push_back(p.isWolf ? 1.0f : 0.0f);
					state.push_back(p.isHellhound ? 1.0f : 0.0f);
					state.push_back(p.isDemon ? 1.0f : 0.0f);
					state.push_back(p.isKoboldKing ? 1.0f : 0.0f);
					state.push_back(p.isAssistant ? 1.0f : 0.0f);
					state.push_back(p.isFaerie ? 1.0f : 0.0f);
					state.push_back(p.isGolem ? 1.0f : 0.0f);
					state.push_back(p.isSkeleton ? 1.0f : 0.0f);
					state.push_back((p.isWallUnit && !p.isMagicWallUnit) ? 1.0f : 0.0f);
					state.push_back(p.isMagicWallUnit ? 1.0f : 0.0f);

					state.push_back((float)p.health);
					state.push_back((float)p.maxHealth);
					state.push_back((float)p.block);
					state.push_back((float)p.ward);
					state.push_back((float)p.fortification);
					state.push_back((float)p.barrier);
					state.push_back((float)p.holyBlock);

					state.push_back(p.onFire ? 1.0f : 0.0f);
					state.push_back(p.isPoisoned ? 1.0f : 0.0f);
					state.push_back(p.isParalyzed ? 1.0f : 0.0f);
					state.push_back((float)p.sleepTurnsRemaining);
					state.push_back(p.inTortoiseForm ? 1.0f : 0.0f);
					state.push_back(p.inGhostForm ? 1.0f : 0.0f);
					state.push_back(p.hasRegeneration ? 1.0f : 0.0f);

					break;
				}
			}

			if (!foundOccupant) {
				for (int i = 0; i < 27; ++i)
					state.push_back(0.0f);
			}
		}
	}

	return state;
}

int ofApp::getAIActionFromModel(const std::vector<float> & state, float reward, bool done) {
	if (!zmqConnected) return 0;

	std::vector<float> validActions;
	int activeID = 1;
	if (isAIvsAI) {
		if (currentState == STATE_DRAFTING) {
			activeID = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) ? players[draftPlayerIndex].playerID : 0;
		} else {
			activeID = players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID;
		}
	} else if (isVsAI) {
		activeID = 1;
	}
	int aiIdx = findPlayerIndexByID(activeID);

	if (currentState == STATE_DRAFTING) {
		validActions.push_back(20.0f);
		validActions.push_back(21.0f);
		validActions.push_back(22.0f);
	} else if (cardInteractionState == CARD_INTERACTION_STATE_MENU) {
		// Toggle Menus (Amnesia/Renewed Inspiration)
		if (interactingCardType == CARD_AMNESIA || interactingCardType == CARD_RENEWED_INSPIRATION) {
			for (int i = 0; i < 70; i++)
				validActions.push_back((float)(2200 + i));
			validActions.push_back(2300.0f); // Accept Button
		} else {
			// Standard Menus
			for (int i = 10; i <= 19; i++)
				validActions.push_back((float)i);
		}
	} else if (cardInteractionState == CARD_INTERACTION_STATE_TARGETING || cardInteractionState == CARD_INTERACTION_STATE_PLACING) {
		for (int y = 0; y < BOARD_HEIGHT; y++) {
			for (int x = 0; x < BOARD_WIDTH; x++) {
				if (board[x][y].isTargetable) validActions.push_back((float)(300 + y * BOARD_WIDTH + x));
			}
		}
	} else {
		validActions.push_back(0.0f); // End Turn

		if (aiIdx >= 0) {
			Player & aiPlayer = players[aiIdx];
			bool hasDrawn = (activeID == myLocalPlayerID) ? hasDrawnCardsThisTurn : opponentHasDrawnCardsThisTurn;
			if (!hasDrawn && (!aiPlayer.deck.empty() || !aiPlayer.discardPile.empty())) {
				validActions.push_back(1.0f); // Draw
			}

			// Assistant Reroll
			for (size_t i = 0; i < players.size(); i++) {
				if (players[i].isAssistant && players[i].health > 0 && players[i].directSummonerID == activeID && !players[i].assistantRerollUsedThisTurn) {
					if (abs(players[i].x - players[currentPlayerIndex].x) + abs(players[i].y - players[currentPlayerIndex].y) <= 1) {
						validActions.push_back(2.0f);
						break;
					}
				}
			}

			// 🧠 SMART PATHFINDING: The AI can no longer bump into walls!
			std::vector<std::vector<int>> distMap(BOARD_WIDTH, std::vector<int>(BOARD_HEIGHT, 9999));
			std::queue<glm::ivec2> q;
			q.push({ aiPlayer.x, aiPlayer.y });
			distMap[aiPlayer.x][aiPlayer.y] = 0;
			bool isGhost = aiPlayer.inGhostForm;

			while (!q.empty()) {
				glm::ivec2 curr = q.front();
				q.pop();
				int d = distMap[curr.x][curr.y];

				if (d > 0 && d <= aiPlayer.ap && !board[curr.x][curr.y].hasWall && !board[curr.x][curr.y].hasPlayer) {
					validActions.push_back((float)(100 + curr.y * BOARD_WIDTH + curr.x)); // Move Action
				}

				if (d < aiPlayer.ap) {
					glm::ivec2 dirs[4] = { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } };
					for (auto dir : dirs) {
						int nx = curr.x + dir.x;
						int ny = curr.y + dir.y;
						if (nx >= 0 && nx < BOARD_WIDTH && ny >= 0 && ny < BOARD_HEIGHT) {
							bool blocked = false;
							if (!isGhost && (board[nx][ny].hasWall || board[nx][ny].hasPlayer)) {
								blocked = true;
							}
							if (!blocked && distMap[nx][ny] == 9999) {
								distMap[nx][ny] = d + 1;
								q.push({ nx, ny });
							}
						}
					}
				}
			}

			// Valid Card Plays
			int savedInteractionState = cardInteractionState;
			int savedInteractingCardIdx = interactingCardIndex;

			for (int i = 0; i < (int)aiPlayer.hand.size(); ++i) {
				int cost = getEffectiveCardCostForPlayer(aiPlayer, aiPlayer.hand[i]);
				if (aiPlayer.ap >= cost) {
					interactingCardIndex = i;
					calculateTargetHighlights(i);
					bool hasTargets = false;

					for (int y = 0; y < BOARD_HEIGHT; y++) {
						for (int x = 0; x < BOARD_WIDTH; x++) {
							if (board[x][y].isTargetable) {
								validActions.push_back((float)(500 + i * (BOARD_WIDTH * BOARD_HEIGHT) + (y * BOARD_WIDTH + x)));
								hasTargets = true;
							}
						}
					}

					if (!hasTargets && (aiPlayer.hand[i].targeting == TARGET_NONE || aiPlayer.hand[i].targeting == TARGET_SELF)) {
						validActions.push_back((float)(500 + i * (BOARD_WIDTH * BOARD_HEIGHT) + (aiPlayer.y * BOARD_WIDTH + aiPlayer.x)));
					}
				}
			}
			cardInteractionState = (CardInteractionState)savedInteractionState;
			interactingCardIndex = savedInteractingCardIdx;
			calculateTargetHighlights(interactingCardIndex);
		}
	}

	std::vector<float> payload;
	payload.reserve(3 + state.size() + validActions.size());
	payload.push_back(done ? 1.0f : 0.0f);
	payload.push_back(reward);
	payload.insert(payload.end(), state.begin(), state.end());
	payload.push_back(-1.0f); // Separator
	payload.insert(payload.end(), validActions.begin(), validActions.end());

	zmq::message_t request(payload.size() * sizeof(float));
	memcpy(request.data(), payload.data(), payload.size() * sizeof(float));
	zmqSocket->send(request, zmq::send_flags::none);

	zmq::message_t reply;
	auto res = zmqSocket->recv(reply, zmq::recv_flags::none);

	int actionIndex = 0;
	if (res.has_value() && reply.size() >= sizeof(int)) {
		actionIndex = *static_cast<int *>(reply.data());
	}
	return actionIndex;
}

void ofApp::executeAIAction(int actionIndex) {
	InputCommandPacket cmd = {};
	cmd.type = PKT_INPUT_COMMAND;

	int activeID = 1;
	if (isAIvsAI) {
		if (currentState == STATE_DRAFTING) {
			activeID = (draftPlayerIndex >= 0 && draftPlayerIndex < (int)players.size()) ? players[draftPlayerIndex].playerID : 0;
		} else {
			activeID = players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID;
		}
	} else if (isVsAI) {
		activeID = 1;
	}
	cmd.playerID = activeID;
	cmd.commandId = 0;
	cmd.turnNumber = globalTurnCounter;

	if (actionIndex == 0) {
		cmd.commandType = CMD_END_TURN;
		cmd.params[0] = currentPlayerIndex;
		endTurnLocked = true;
		sendInputCommand(cmd, true);
	} else if (actionIndex == 1) {
		cmd.commandType = CMD_DRAW_CARDS;
		cmd.params[0] = currentPlayerIndex;
		cmd.params[1] = players[currentPlayerIndex].isDemon ? 3 : 2;
		sendInputCommand(cmd, true);
	} else if (actionIndex == 2) {
		int assistantIndex = -1;
		for (int i = 0; i < (int)players.size(); i++) {
			if (players[i].isAssistant && players[i].health > 0 && players[i].directSummonerID == players[currentPlayerIndex].playerID && !players[i].assistantRerollUsedThisTurn) {
				if (abs(players[i].x - players[currentPlayerIndex].x) + abs(players[i].y - players[currentPlayerIndex].y) <= 1) {
					assistantIndex = i;
					break;
				}
			}
		}
		if (assistantIndex != -1) {
			cmd.commandType = CMD_PSEUDO_ACTION;
			cmd.params[0] = assistantIndex;
			strncpy(cmd.stringData, "AssistantReroll", sizeof(cmd.stringData) - 1);
			sendInputCommand(cmd, true);
		}
	} else if (actionIndex >= 10 && actionIndex <= 19) {
		int choice = (actionIndex - 10) + 1;
		if (interactingCardType == PSEUDO_CARD_GHOST_RELOCATE) choice -= 1;

		cmd.commandType = CMD_MENU_CHOICE;
		cmd.params[0] = interactingCardType;
		cmd.params[1] = interactionTargetIndex;
		cmd.params[2] = choice;
		cmd.params[3] = interactingCardIndex;
		if (interactingCardType == CARD_GIANT_MAGIC_HAND) {
			cmd.params[4] = magicHandTargetTile.x;
			cmd.params[5] = magicHandTargetTile.y;
		}
		sendInputCommand(cmd, true);
	} else if (actionIndex >= 20 && actionIndex <= 22) {
		int draftPick = actionIndex - 20;
		if (currentDraftOptionPoolIndices.size() >= 3) {
			cmd.commandType = CMD_ACCEPT_DRAFT;
			cmd.params[0] = draftPlayerIndex;
			cmd.params[1] = currentDraftClassTier;

			if (!isInGameDraft && draftStage == 0) {
				cmd.params[2] = 2; // Copies
				if (draftPick == 0) {
					cmd.params[3] = currentDraftOptionPoolIndices[0];
					cmd.params[4] = currentDraftOptionPoolIndices[1];
				} else if (draftPick == 1) {
					cmd.params[3] = currentDraftOptionPoolIndices[0];
					cmd.params[4] = currentDraftOptionPoolIndices[2];
				} else {
					cmd.params[3] = currentDraftOptionPoolIndices[1];
					cmd.params[4] = currentDraftOptionPoolIndices[2];
				}
				cmd.params[5] = -1;
			} else {
				cmd.params[2] = 1; // Copies
				cmd.params[3] = currentDraftOptionPoolIndices[draftPick];
				cmd.params[4] = -1;
				cmd.params[5] = -1;
			}
			sendInputCommand(cmd, true);
			draftAcceptLocked = true;
		}
	} else if (actionIndex >= 100 && actionIndex <= 264) {
		int tileIdx = actionIndex - 100;
		int tx = tileIdx % BOARD_WIDTH;
		int ty = tileIdx / BOARD_WIDTH;

		cmd.commandType = CMD_MOVE_UNIT;
		cmd.params[0] = players[currentPlayerIndex].x;
		cmd.params[1] = players[currentPlayerIndex].y;
		cmd.params[2] = tx;
		cmd.params[3] = ty;
		sendInputCommand(cmd, true);
	} else if (actionIndex >= 300 && actionIndex <= 464) {
		int tileIdx = actionIndex - 300;
		int tx = tileIdx % BOARD_WIDTH;
		int ty = tileIdx / BOARD_WIDTH;
		handleCardTargetClick(tx, ty);
	} else if (actionIndex >= 500 && actionIndex <= 2150) {
		int encodedVal = actionIndex - 500;
		int tileIdx = encodedVal % (BOARD_WIDTH * BOARD_HEIGHT);
		int handIndex = encodedVal / (BOARD_WIDTH * BOARD_HEIGHT);

		int tx = tileIdx % BOARD_WIDTH;
		int ty = tileIdx / BOARD_WIDTH;

		cmd.commandType = CMD_PLAY_CARD;
		cmd.params[0] = handIndex;
		cmd.params[1] = tx;
		cmd.params[2] = ty;
		sendInputCommand(cmd, true);
	} else if (actionIndex >= 2200 && actionIndex <= 2299) {
		int toggleIdx = actionIndex - 2200;
		if (interactingCardType == CARD_AMNESIA) {
			auto it = std::find(amnesiaSelectedIndices.begin(), amnesiaSelectedIndices.end(), toggleIdx);
			if (it != amnesiaSelectedIndices.end())
				amnesiaSelectedIndices.erase(it);
			else if (amnesiaSelectedIndices.size() < (size_t)numCardsToRemove)
				amnesiaSelectedIndices.push_back(toggleIdx);
		} else if (interactingCardType == CARD_RENEWED_INSPIRATION) {
			auto it = std::find(renewedSelectedHandIndices.begin(), renewedSelectedHandIndices.end(), toggleIdx);
			if (it != renewedSelectedHandIndices.end())
				renewedSelectedHandIndices.erase(it);
			else
				renewedSelectedHandIndices.push_back(toggleIdx);
		}
	} else if (actionIndex == 2300) {
		if (interactingCardType == CARD_AMNESIA && amnesiaSelectedIndices.size() == (size_t)numCardsToRemove) {
			cmd.commandType = CMD_MENU_CHOICE;
			cmd.params[0] = (int)CARD_AMNESIA;
			cmd.params[1] = amnesiaTargetPlayerIndex;
			cmd.params[2] = 3;
			cmd.params[3] = interactingCardIndex;

			uint32_t maskLow = 0, maskHigh = 0;
			for (int idx : amnesiaSelectedIndices) {
				if (idx < 32)
					maskLow |= (1U << idx);
				else if (idx < 64)
					maskHigh |= (1U << (idx - 32));
			}
			cmd.params[4] = (int)maskLow;
			cmd.params[5] = (int)maskHigh;

			sendInputCommand(cmd, true);
			amnesiaDeckCopy.clear();
			amnesiaSelectedIndices.clear();
			resetCardInteraction();
		} else if (interactingCardType == CARD_RENEWED_INSPIRATION) {
			cmd.commandType = CMD_RENEWED_INSPIRATION;
			cmd.params[0] = currentPlayerIndex;
			cmd.params[1] = renewedSelectedHandIndices.size();
			cmd.params[2] = interactingCardIndex;

			uint32_t maskLow = 0, maskHigh = 0;
			for (int idx : renewedSelectedHandIndices) {
				if (idx < 32)
					maskLow |= (1U << idx);
				else if (idx < 64)
					maskHigh |= (1U << (idx - 32));
			}
			cmd.params[4] = (int)maskLow;
			cmd.params[5] = (int)maskHigh;

			sendInputCommand(cmd, true);
			renewedSelectedHandIndices.clear();
			resetCardInteraction();
		}
	} else if (actionIndex == 99999) {
		cmd.commandType = CMD_PSEUDO_ACTION;
		strncpy(cmd.stringData, "Forfeit", sizeof(cmd.stringData) - 1);
		sendInputCommand(cmd, true);
	}
}

// Anti-cheat: Log all player deck states to file and console
void ofApp::logDeckStates(const std::string & reason) {
	std::string timestamp = ofGetTimestampString("%Y-%m-%d %H:%M:%S");
	std::string logEntry = "\n=== DECK STATE LOG ===\n";
	logEntry += "Time: " + timestamp + "\n";
	logEntry += "Reason: " + reason + "\n";
	logEntry += "Turn: " + std::to_string(globalTurnCounter) + "\n";
	logEntry += "Current Player: " + std::to_string(currentPlayerIndex) + "\n";
	logEntry += "Local Player ID: " + std::to_string(myLocalPlayerID) + "\n";
	logEntry += "Is Host: " + std::string(steamManager.isHost() ? "true" : "false") + "\n\n";

	for (const auto & p : players) {
		logEntry += getDeckStateString(p) + "\n";
	}
	logEntry += "=====================\n";

	// Log to console
	ofLogNotice("DeckState") << logEntry;

	// Append to file
	std::string filename = "deck_states_" + std::string(steamManager.isHost() ? "host" : "client") + ".log";
	ofBuffer buffer;
	buffer.set(logEntry.c_str(), logEntry.size());

	ofBufferToFile(filename, buffer, true); // true = append mode
}

// Simple deterministic dice resolver used by a few inline spawn paths.
int ofApp::resolveDiceRoll(int numDice, int sides) {
	int total = 0;
	std::string rollStr = "DICE ROLL: " + std::to_string(numDice) + "d" + std::to_string(sides) + " -> [";
	for (int i = 0; i < numDice; ++i) {
		int raw = getGameRandom(1, sides);
		if (i > 0) rollStr += ", ";
		rollStr += std::to_string(raw);
		total += raw;
	}
	rollStr += "] = " + std::to_string(total) + " | RNG Advance: " + std::to_string(gameplayRngAdvanceCount);
	if (isMultiplayer) writeLockstepTrace(steamManager.isHost(), globalTurnCounter, rollStr);
	return total;
}

// Detailed resolver that returns per-die raw faces and the sum of raw faces.
int ofApp::resolveDiceRollDetailed(int numDice, int sides, std::vector<int> & outRaw) {
	outRaw.clear();
	int totalRaw = 0;
	std::string rollStr = "DICE ROLL DETAILED: " + std::to_string(numDice) + "d" + std::to_string(sides) + " -> [";
	for (int i = 0; i < numDice; ++i) {
		int raw = getGameRandom(1, sides);
		outRaw.push_back(raw);
		if (i > 0) rollStr += ", ";
		rollStr += std::to_string(raw);
		totalRaw += raw;
	}
	rollStr += "] = " + std::to_string(totalRaw) + " | RNG Advance: " + std::to_string(gameplayRngAdvanceCount);
	if (isMultiplayer) writeLockstepTrace(steamManager.isHost(), globalTurnCounter, rollStr);
	return totalRaw;
}

void ofApp::saveReplay(const std::string & filename) {
	ofJson j;
	j["seed"] = currentMapSeed;
	j["player0"] = player0SteamName;
	j["player1"] = player1SteamName;

	ofJson cmds = ofJson::array();
	for (const auto & rc : matchReplayLog) {
		ofJson cj;
		cj["frame"] = rc.frame;
		cj["cmdId"] = rc.cmd.commandId;
		cj["turn"] = rc.cmd.turnNumber;
		cj["type"] = rc.cmd.commandType;
		cj["player"] = rc.cmd.playerID;
		cj["p0"] = rc.cmd.params[0];
		cj["p1"] = rc.cmd.params[1];
		cj["p2"] = rc.cmd.params[2];
		cj["p3"] = rc.cmd.params[3];
		cj["p4"] = rc.cmd.params[4];
		cj["p5"] = rc.cmd.params[5];
		cj["p6"] = rc.cmd.params[6];
		cj["p7"] = rc.cmd.params[7];
		cj["str"] = std::string(rc.cmd.stringData);
		cmds.push_back(cj);
	}
	j["commands"] = cmds;

	std::string path = getSavesDirPath().string() + "/" + filename;
	ofSaveJson(path, j);
	ofLogNotice("Replay") << "Saved replay to " << path;
}

void ofApp::loadReplay(const std::string & filename) {
	std::string path = getSavesDirPath().string() + "/" + filename;
	ofJson j = ofLoadJson(path);
	if (j.empty()) {
		ofLogError("Replay") << "Failed to load replay: " << path;
		return;
	}

	isReplayMode = true;
	isMultiplayer = false; // Replays play back entirely offline

	currentMapSeed = j.value("seed", 0);
	player0SteamName = j.value("player0", "Player 1");
	player1SteamName = j.value("player1", "Player 2");

	replayPlaybackQueue.clear();
	for (const auto & cj : j["commands"]) {
		ReplayCommand rc;
		rc.frame = cj.value("frame", 0);
		rc.cmd.commandId = cj.value("cmdId", 0);
		rc.cmd.turnNumber = cj.value("turn", 0);
		rc.cmd.commandType = cj.value("type", 0);
		rc.cmd.playerID = cj.value("player", 0);
		rc.cmd.params[0] = cj.value("p0", 0);
		rc.cmd.params[1] = cj.value("p1", 0);
		rc.cmd.params[2] = cj.value("p2", 0);
		rc.cmd.params[3] = cj.value("p3", 0);
		rc.cmd.params[4] = cj.value("p4", 0);
		rc.cmd.params[5] = cj.value("p5", 0);
		rc.cmd.params[6] = cj.value("p6", 0);
		rc.cmd.params[7] = cj.value("p7", 0);

		std::string str = cj.value("str", "");
		strncpy(rc.cmd.stringData, str.c_str(), sizeof(rc.cmd.stringData) - 1);
		rc.cmd.stringData[sizeof(rc.cmd.stringData) - 1] = '\0';

		replayPlaybackQueue.push_back(rc);
	}

	replayPlaybackIndex = 0;
	setupGame(); // Start the game with the forced seed
	addGameLog("Replay loaded! Watching...");
}